// Language: German is in the markup, English comes from the EN table.
const $=id=>document.getElementById(id);
// Language: German is written in the markup; English comes from this table. Choice is kept per browser.
let L='de';try{L=localStorage.getItem('lang')||(/^de/i.test(navigator.language)?'de':'en')}catch{L=/^de/i.test(navigator.language)?'de':'en'}
const t=(de,en)=>L==='en'?en:de;
const EN={"Lagerfeuer und Rast": "Campfire and rest","Der Gastgeber ruft eine kurze oder lange Rast; drei Nachtwachen je Landschaft und eine Frage am Feuer für jeden.": "The host calls a short or long rest; three night watches per landscape and a question at the fire for everyone.","Heldenlied des Barden": "Bard's hero song","Am Ende jedes Kapitels singt der Spark ein kurzes Lied über die Helden, aus festen Strophen mit ihren Namen. Braucht Musik am Tisch.": "At the end of each chapter the Spark sings a short song about the heroes, from fixed verses with their names. Needs music at the table.","Angriffe erkennen": "Spot attacks","Steckte in gelesenem Text eine Anweisung, legt das Hilfsmodell danach einen Fall an. Die festen Sperren gelten immer.": "When text that was read hid an order, the helper model makes a case afterwards. The fixed locks always hold.","Für kurze Texte": "For short texts","Themen im Gedächtnis, Antwortvorschläge und Nachfragen auf der Uhr schreibt erst das Hilfsmodell.": "Topics in the memory, reply suggestions and follow-ups on the watch are written by the helper model first.","Hilfsmodell": "Helper model","Ein kleines Sprachmodell auf dem Modell-Rechner beantwortet einfache Einordnungen zuerst; lädt es noch, antwortet sofort das große.": "A small language model on the model computer answers simple classifications first; while it is still loading, the big one answers at once.","Für die Weiche": "For routing","Fragen, die keine Regel erkennt, ordnet erst das Hilfsmodell einer Werkzeuggruppe zu.": "Questions no rule recognizes are sorted into a tool group by the helper model first.","Für den Dungeon-Master": "For the Dungeon Master","Der Richter nach jedem Zug und der Erzähler-Prüfstand fragen erst das Hilfsmodell.": "The judge after every turn and the narrator test bench ask the helper model first.","Für Mails": "For mail","Aufräumen und wichtige Mails erkennen fragen erst das Hilfsmodell.": "Tidying and recognizing important mail ask the helper model first.","Echte Würfel am Tisch": "Real dice at the table","Wer am echten Tisch sitzt, wirft seinen eigenen W20 und tippt oder sagt die Zahl; nach 30 Sekunden würfelt der Spark selbst. Nie im Auto.": "Whoever sits at the real table throws their own d20 and taps or says the number; after 30 seconds the Spark rolls itself. Never in the car.","Wappen für Gruppe und Fraktionen": "Arms for group and factions","Die Gruppe wählt Farbe und Zeichen ihres Wappens, jede Fraktion trägt ein eigenes; das Panel zeichnet sie selbst.": "The group chooses colour and charge of its arms, every faction carries its own; the panel draws them itself.","Gesichter für NSCs": "Faces for NPCs","Jede getroffene Figur bekommt ein festes Porträt; spätere Szenenbilder nehmen es als Vorlage, das Gesicht bleibt gleich.": "Every person met gets a fixed portrait; later scene pictures take it as a reference, the face stays the same.","Abenteuer-Import": "Adventure import","Ein geschriebenes Abenteuer (PDF, Word, Markdown) wird im Geschichten-Planer ein Entwurf mit Akten und Schauplätzen; das Panel prüft ihn.": "A written adventure (PDF, Word, Markdown) becomes a draft with acts and places in the story planner; the panel checks it.","Gold mit Zweck": "Gold with a purpose","Erzähler-Prüfstand": "Narrator bench","Erzähler-Fehler beheben": "Fix narrator errors","Dungeon-Richter": "Dungeon judge","Krit- und Patzer-Tabellen": "Critical and fumble tables","Ehrungen des Abends": "Honours of the evening","Knapp daneben": "Near miss","Helfen und Gruppenprobe": "Helping and group checks","Schriftstücke": "Writings","Monster-Album": "Monster album","Narben": "Scars","Wer wieder aufsteht oder kritisch getroffen wird, behält eine Narbe, selten mit −1 auf einen Wert bis zum Heiler.": "Who stands up again or takes a critical hit keeps a scar, rarely with −1 on a value until a healer.","Nur Narben": "Scars only","Wunden ändern nur das Aussehen, nie einen Wert.": "Wounds only change the look, never a value.","Jeder Held sammelt die besiegten Gegner; nach 1, 3 und 5 Siegen weiß das Album mehr über sie.": "Every hero collects the foes defeated; after 1, 3 and 5 wins the album knows more about them.","Gefundene Briefe, Steckbriefe und Verse erscheinen als Pergament; der Gastgeber zeigt sie allen, einem Platz oder niemandem.": "Letters, wanted posters and verses found appear as parchment; the host shows them to all, to one seat or to nobody.","Wer in seiner Aktion einem Helden mit Namen hilft, gibt ihm Vorteil; bei einer Gruppenprobe reicht es, wenn die Hälfte sie schafft.": "Who helps a hero by name in their action gives them advantage; in a group check it is enough when half of them pass.","Fehlen einer Probe 1 oder 2, wählt der Held: aufgeben oder es mit einem gewürfelten Preis doch schaffen. Nie bei Angriffen.": "When a check misses by 1 or 2, the hero chooses: give up, or make it after all at a rolled price. Never on attacks.","Am Ende der Runde bekommt jeder Held eine Urkunde mit seinen Zahlen, die Besten einen festen Titel wie „Klinge des Abends“.": "At the end of the round every hero gets a certificate with their numbers, the best a fixed title like \"Blade of the evening\".","Ein kritischer Treffer oder eine 1 würfelt einen W12 auf einer festen Tabelle je Schadensart; Patzer bleiben mild.": "A critical hit or a 1 rolls a d12 on a fixed table per kind of damage; fumbles stay mild.","Nach den festen Prüfungen schätzt das Modell, ob die Erzählung den Aktionen oder Würfen widerspricht; ab 90 % schreibt der Spark einmal neu.": "After the fixed checks the model estimates whether the narration contradicts the actions or dice; from 90 % the Spark writes once more.","Nach 👎 mit festem Grund erzählt der Spark die letzte Szene einmal neu; oft Gemeldetes wird ein fester Hinweis der Welt.": "After a 👎 with a fixed reason the Spark tells the last scene again once; what is reported often becomes a fixed hint of the world.","Der Admin spielt feste Szenen durch das laufende Modell; feste Regeln geben Punkte, Modelle stehen nebeneinander.": "The admin plays fixed scenes through the running model; fixed rules give points, models side by side.","Fraktionen mit Uhren": "Factions with clocks","Quest-Gegenstände": "Quest items","Schlüssel, Karten und Siegel der Geschichte ohne Gewicht; das Panel prüft jeden Fund, nur wer sie trägt, öffnet ihre Türen.": "The story's keys, maps and seals without weight; the panel checks every find, only who carries them opens their doors.","Gruppen der Geschichte verfolgen ihr Ziel mit einer Uhr; das Panel dreht sie, die Helden helfen oder stören.": "The story's groups pursue their goal with a clock; the panel turns it, the heroes help or hinder.","Zufallsregeln": "Random rules","NSC-Gedächtnis und Chronik": "NPC memory and chronicle","Orakel": "Oracle","Kampfstufen": "Combat stages","Der Gastgeber wählt, wie schwer die Begegnungen sind: leicht, mittel, schwer oder tödlich.": "The host chooses how hard the encounters are: easy, medium, hard or deadly.","Der Gastgeber fragt Ja oder Nein mit Chaosgrad oder würfelt auf die Tabellen; die Erzählung hält sich an die Antwort.": "The host asks yes or no with a chaos grade or rolls on the tables; the narration holds to the answer.","Figuren mit Karte aus festen Tabellen und Haltung zu jedem Helden; nur die Figuren der Szene gehen ans Modell; dazu Chronik und Ruf.": "People with a card from fixed tables and an attitude to each hero; only the scene's people go to the model; plus chronicle and reputation.","Der Gastgeber legt eigene Regeln mit Chance, Auslöser und Wirkung fest; das Panel würfelt sie und wendet sie an.": "The host sets rules of their own with chance, trigger and effect; the panel rolls and applies them.","Schreiber-Abgleich": "Scribe check","Ein zweiter kleiner Modellaufruf liest jede Erzählung und schlägt fehlende Änderungen vor; das Panel nimmt sie nach festen Grenzen.": "A second small model call reads every narration and proposes missing changes; the panel takes them by fixed limits.","Grenzen und X-Karte": "Lines and X-card","Jeder Platz legt fest, was nie vorkommt und was nur angedeutet wird; die X-Karte erzählt die letzte Szene anonym ruhiger neu. Ab Werk an.": "Every seat sets what never appears and what is only hinted at; the X-card tells the last scene again more calmly, anonymously. On from the start.","In Siedlungen Gasthaus, Schmied, Lehrstunde und Gerüchte zu festen Preisen nach der Stufe der Gruppe.": "In settlements inn, smith, lesson and rumours at fixed prices by the group's level.","Heldenmut": "Heroic courage","Einmal am Abend eine misslungene Probe neu würfeln oder einen Treffer kritisch machen; 👍 der Mitspieler schenken einen zweiten.": "Once an evening roll a failed check again or make a hit critical; 👍 of the other players give a second one.","Spielleiter-Regler": "Game master dial","Nach jedem Kampf werden die nächsten Begegnungen bis zu ein Viertel leichter oder schwerer; der Gastgeber kann das festhalten.": "After every fight the next encounters get up to a quarter easier or harder; the host can hold it.","Balance-Prüfstand": "Balance bench","Der Spark spielt nachts Kämpfe mit den echten Regeln allein durch und zeigt unter „Regeln anpassen“ die Siege je Stufe und Gruppengröße.": "At night the Spark plays fights with the real rules by itself and shows under \"Adjust rules\" the wins per level and group size.","Gäste mit E-Mail": "Guests with e-mail","Gäste melden sich mit einem Code vom Postfach des Admins an und behalten ihre Helden auf jedem Gerät; „Du bist dran“ per Mail.": "Guests sign in with a code from the admin's mailbox and keep their heroes on any device; \"Your turn\" by mail.","Bilder für Ausrüstung und Zauber": "Pictures for gear and spells","Ein gemaltes Bild je Gegenstand und Zauber im Stil der Welt, nachts oder per Knopf, dazu eigene für benannte Funde. Braucht Bilder malen.": "A painted picture per item and spell in the world's style, at night or on a button, plus own ones for named finds. Needs Painting pictures.","Zeitserver im Heimnetz": "Time server in the home network","Stellt die Uhren beider Rechner auch ohne Internet, etwa die FRITZ!Box. Wirkt nach dem nächsten Update.": "Sets the clocks of both computers without the internet too, for example the FRITZ!Box. Takes effect after the next update.","Eine IP-Adresse im Heimnetz, leer heißt: nur die üblichen Zeitserver im Internet. Der Spark setzt sie vor die üblichen Server, auf diesem und dem Modell-Rechner. Gehen die Uhren beider Rechner mehr als eine Minute auseinander, nimmt der Modell-Rechner keine Befehle an. An der FRITZ!Box: Heimnetz, Netzwerk, Netzwerkeinstellungen, Zeitsynchronisation. Prüfen unter Zustand → Überblick → Ohne Internet.": "An IP address in the home network; empty means only the usual time servers on the internet. The Spark puts it before the usual servers, on this and on the model computer. When the clocks of the two computers are more than a minute apart, the model computer takes no commands. On the FRITZ!Box: Home Network, Network, Network Settings, Time Synchronization. Check under Status → Summary → Without the internet.","Ohne Internet": "Without the internet","Läuft der Spark im Heimnetz weiter, wenn das Internet fehlt? Sprachmodell, Hören, Sprechen, Uhren, Zeitserver und Namen.": "Does the Spark keep running at home when the internet is gone? Language model, listening, speaking, clocks, time server and names.","Nur lesen: eine Uhrzeit-Frage an den Zeitserver, eine Abfrage je Name, nie Inhalte.": "Only reading: one time question to the time server, one lookup per name, never content.","Dungeon-Master": "Dungeon Master","KI-Dungeon-Master": "AI Dungeon Master","Rollenspiel für bis zu fünf, auch ohne Profil per Link; das Modell erzählt, Würfel, Beute und Stufen bestimmt das Panel fest.": "Role-playing game for up to five, also without a profile by link; the model narrates, the panel fixes dice, loot and levels.","Regeln, Katalog und Geschichten": "Rules, catalogue and stories","Geschichten (auch vom Sprachmodell entworfen), Welten, Klassen, Gegenstände, Kurven und Prompt; das Panel prüft alles.": "Stories (also drafted by the language model), worlds, classes, items, curves and prompt; the panel checks everything.","Regeln anpassen": "Adjust rules","Satzende am Tonfall": "Turn end by tone","Misst an jeder Sprechpause, ob der Tonfall nach fertigem Satz klingt (Smart Turn); entscheidet noch nichts, nur Zahlen.": "Measures at each speaking pause whether the tone sounds like a finished sentence (Smart Turn); decides nothing yet, numbers only.","Ins Wort fallen: erst anhalten": "Barge-in: pause first","Ein „mhm“ oder Husten hält die Antwort nur an; sie läuft weiter, erst ein echter Satz oder „Stopp“ beendet sie.": "A \"mhm\" or a cough only pauses the answer; it plays on, only a real sentence or \"stop\" ends it.","Unklare Fragen anonym merken": "Keep unclear questions anonymously","Fragen, die keine Regel erkennt, stehen ohne Namen, Nummern und Adressen unter Funktionen → Weiche bei „unklar“, sieben Tage lang.": "Questions no rule recognizes are listed without names, numbers and addresses under Features → Routing at \"unclear\", for seven days.","Rechnen mit festem Werkzeug": "Exact calculations","Das Panel rechnet Rechnungen, Prozent und Daten genau aus, nicht das Sprachmodell, und prüft Rechnungen in Antworten nach.": "The panel computes sums, percentages and dates exactly, not the language model, and checks sums in answers.","Uhrzeit, Datum, Rechnungen, Datumsrechnungen und Einheiten beantwortet das Panel selbst, ohne Sprachmodell. Die Antwort kommt sofort.": "The panel answers the time, the date, calculations, date calculations and units itself, without the language model. The answer comes at once.","Angriffsprobe": "Attack probe","Kachel „Angriffe prüfen“: misst, wie oft das Sprachmodell Befehlen in fremdem Text folgen würde. Kein Werkzeug läuft, nur Zahlen.": "Tile \"Probe attacks\": measures how often the language model would follow orders in outside text. No tool runs, numbers only.","Karte: Dokumente pro Tag und Profil": "Map: documents per day and profile","5 bis 500, Standard 200. Ein Schritt nennt nur Verbindungen und ist kurz.": "5 to 500, default 200. A step only names connections and is short.","Einladungen aus Mails": "Invitations from mail","Eine Einladung (.ics) aus einer Mail mit einem Tipp in den Kalender; mit „Mails senden“ auch die Antwort an den Einladenden.": "An invitation (.ics) from a mail into the calendar with one tap; with \"Send mail\" also the answer to the organiser.","Kontakte für Kontakte-Apps": "Contacts for contacts apps","Das Adressbuch „Auf dem Spark“ in der Kontakte-App des iPhone (CardDAV), mit dem App-Passwort des Kalender-Servers.": "The address book \"On the Spark\" in the iPhone's Contacts app (CardDAV), with the calendar server's app password.","Wissenskarte": "Knowledge map","Die Seiten des Wissensbuchs als Karte mit Verbindungen, jede mit Quelle und nach festen Regeln geprüft.": "The pages of the knowledge book as a map with connections, each with its source and checked by fixed rules.","Kontakte ändern": "Edit contacts","Auf der Seite Kontakte bearbeiten, anlegen und löschen, zurück ins eigene Adressbuch oder auf dem Spark.": "Edit, add and delete on the page Contacts, back into the own address book or on the Spark.","Prüft und repariert eine abgeschottete Kopie des Spark-Codes auf dem Modell-Rechner: ohne deine Daten, ohne Internet. Dein Spark selbst bleibt unberührt, eingespielt wird nie etwas.": "Checks and repairs a sealed-off copy of the Spark's code on the model computer: without your data, without internet. Your Spark itself stays untouched, nothing is ever installed.","Die Werkstatt ist aus. Einschalten unter Funktionen → Werkstatt.": "The workshop is off. Switch it on under Features → Workshop.","Testen, untersuchen und reparieren unter Zustand → Werkstatt.": "Test, look into and repair under Status → Workshop.","Offen": "Open","Alles Offene im Assistenten": "Everything open in the assistant","Was dich braucht, kommt als Karte mit Knöpfen ins Gespräch; „Später“ legt es auf die Seite Offen.": "What needs you comes as a card with buttons into the conversation; \"Later\" puts it on the page Open.","Teilen mit Profilen": "Sharing with profiles","Profile teilen Dokumente einzeln mit anderen Profilen; Ich → Geteilt zeigt alles Geteilte (auch Listen und Kalender). Gäste nie.": "Profiles share documents with single other profiles; Me → Shared shows everything shared (also lists and calendars). Never guests.","Listen teilen": "Share lists","Ein Profil teilt eine Liste mit einem anderen: sehen oder mitschreiben (eintragen, abhaken). Neues von anderen kommt als Hinweis.": "A profile shares a list with another one: to see or to write along (put on, tick off). New things from others come as a note.","Listen in Erinnerungen": "Lists in Reminders","Mitschreib-Link": "Write link","Ein Link für Leute ohne Profil: nur eintragen, auf Wunsch auch ansehen, mit Ablauf und jederzeit widerrufbar.": "A link for people without a profile: only put things on, optionally also look, with an end date and revocable at any time.","Die Listen auf dem Spark erscheinen über den Kalender-Server in der Erinnerungen-App des iPhone, in beide Richtungen.": "The lists on the Spark show in the iPhone's Reminders app through the calendar server, both ways.","Postausgang (SMTP)": "Outgoing server (SMTP)","PIN vergessen? Ein Admin setzt sie neu.": "Forgot the PIN? An admin sets a new one.","Senden per Sprache": "Sending by voice","nur Antworten auf eine gerade gelesene Mail": "only replies to a mail just read","auch neue Mails an Kontakte": "also new mails to contacts","„Antworte ihr per Mail: …“ oder „Schreib eine Mail an Anna: …“. Der Spark liest Empfänger und Text vor, gesendet wird erst nach deinem „Ja“.": "\"Antworte ihr per Mail: …\" or \"Schreib eine Mail an Anna: …\". The Spark reads recipient and text back, it is sent only after your \"Yes\".","Mails senden": "Send mail","Auf der Seite E-Mail: neue Mail oder Antwort mit drei Vorschlägen, gesendet erst nach der Vorschau. Höchstens 10 Empfänger, 30 Mails am Tag.": "On the E-mail page: a new mail or a reply with three suggestions, sent only after the preview. At most 10 recipients, 30 mails a day.","Mails ordnen": "Order mail","Auf der Seite E-Mail: gelesen oder ungelesen, ins Archiv, in einen eigenen Ordner, gleich wieder zurück.": "On the E-mail page: read or unread, into the archive, into an own folder, back again right away.","Nur du selbst auf der Seite E-Mail: in den Papierkorb mit Rückgängig, dort endgültig nur nach Rückfrage. Regeln und Assistent nie.": "Only you yourself on the E-mail page: into the trash with undo, for good there only after a question. Rules and the assistant never.","Mails löschen": "Delete mail","Kalender teilen": "Share calendars","Ein Profil teilt einen Kalender mit einem anderen, nur sehen oder sehen und eintragen. Private Termine nur als „belegt“.": "A profile shares a calendar with another one, see only or see and add. Private appointments only as „belegt“.","Anrufe per Assistent": "Calls by the assistant","„Ruf Sabine an“ zum Assistenten: erst dein Ja ruft an. Ohne Bildschirm kommt der Anruf aufs Handy; Android auch übers Telefon.": "\"Call Sabine\" to the assistant: only your yes calls. Without a screen the call comes to your phone; Android also by phone.","Nicht jetzt": "Not now","Mehrere Stimmen gleichzeitig": "Several voices at once","Bündelt mehrere Stimmen im Decoder, damit bei mehreren Anfragen der erste Ton früher kommt.": "Batches several voices in the decoder so that with several requests the first audio comes sooner.","einzeln (Standard von vllm-omni)": "one by one (vllm-omni's default)","bis zu 2 gebündelt": "up to 2 batched","bis zu 4 gebündelt": "up to 4 batched","Laufen mehrere Antworten gleichzeitig, rechnet der Decoder sie zusammen und mit vorbereiteten CUDA-Graphen. Das braucht beim Start etwas mehr Speicher und Zeit. Vorher und nachher unter Zustand → Prüfen → Leistung messen vergleichen. Eine Änderung startet die Sprachausgabe neu, das dauert ein paar Minuten.": "When several answers run at once, the decoder computes them together and with prepared CUDA graphs. That takes a little more memory and time at start. Compare before and after under Status → Checks → Measure performance. A change restarts speech output, which takes a few minutes.","Gleichen Anfang merken": "Remember the same beginning","Die Engine merkt sich den Teil, der bei jedem Satz derselben Stimme gleich ist (Präfix-Cache).": "The engine remembers the part that is the same in every sentence of the same voice (prefix cache).","Referenz der eigenen Stimme kürzen": "Shorten the reference of your own voice","Nur für geklonte Stimmen: eine kürzere Aufnahme macht den ersten Ton schneller.": "Only for cloned voices: a shorter recording makes the first audio faster.","aus: die ganze Aufnahme": "off: the whole recording","auf etwa 8 s": "to about 8 s","auf etwa 10 s": "to about 10 s","auf etwa 15 s": "to about 15 s","Bei jedem Satz verarbeitet die Sprachausgabe die ganze Referenzaufnahme der Stimme mit. Ist sie länger, schneidet der Spark sie einmal an einer Sprechpause ab, lässt das Stück von der Spracherkennung neu aufschreiben und nimmt dann dieses Stück. Die Aufnahme selbst bleibt unverändert; aus schaltet zurück.": "With every sentence speech output also processes the voice's whole reference recording. When it is longer, the Spark cuts it once at a pause in speaking, has speech recognition write the piece down again and then takes this piece. The recording itself stays unchanged; off switches back.","Wachposten": "Sentry","Feste Regeln melden den Admins, wenn sich an Anmeldung, Zugängen oder Schutz etwas tut oder das Protokoll verändert wurde.": "Fixed rules tell the admins when something happens at sign-in, ways in or protection, or the log was changed.","Wissensbuch": "Knowledge book","Eigene Dokumente werden in ruhigen Minuten zu Seiten, jeder Satz mit Quelle und nach festen Regeln geprüft.": "In quiet minutes own documents become pages, every sentence with its source and checked by fixed rules.","Dokumente pro Tag und Profil": "Documents per day and profile","Stichprobe je Nacht": "Sample per night","0 bis 100, Standard 50. So viele Sätze prüft das Sprachmodell nachts gegen ihre Quelle; 0 = nur feste Regeln.": "0 to 100, default 50. This many sentences the language model checks against their source at night; 0 = fixed rules only.","5 bis 200, Standard 40. Höchstens 300 Seiten pro Profil, 5 Seiten pro Dokument.": "5 to 200, default 40. At most 300 pages per profile, 5 pages per document.","Ausgelassene Ordner": "Left-out folders","Auswahl begrenzen (top_k)": "Limit the choice (top_k)","0 = Standard des Servers, bis 100; Qwen empfiehlt 20. Vergleich: Qualitätstest „Mit Qwen-Empfehlung prüfen“.": "0 = the server's default, up to 100; Qwen recommends 20. Compare: quality test \"Test with Qwen's recommendation\".","Mit Qwen-Empfehlung prüfen": "Test with Qwen's recommendation","Antwort-Prüfung erweitern": "Extended answer check","Auch Temperaturen, Kilometer, Prozent und Namen in Anführungszeichen müssen in einem Werkzeug-Ergebnis stehen; gerundet zählt als richtig.": "Temperatures, kilometres, percentages and names in quotation marks must be in a tool result too; rounded counts as right.","Schnellere Websuche": "Faster web search","Höchstens 3 Sekunden je Seite, nur die Stellen, die zur Frage passen, und dieselbe Suche 10 Minuten aus dem Speicher.": "At most 3 seconds per page, only the parts that fit the question, and the same search from memory for 10 minutes.","Einfaches sofort beantworten": "Answer simple things at once","Bei sehr vielen gemerkten Fakten bekommt das Sprachmodell nur die neuesten und die passenden. Antworten kommen schneller und genauer.": "With very many remembered facts the language model only gets the newest ones and the ones matching the question. Answers come faster and more precisely.","Großes Gedächtnis kürzen": "Trim a large memory","Weiche abstimmen": "Tune the switch","Das Sprachmodell schlägt Wörter für die Gruppen vor; das Panel misst jedes und behält nur, was hilft.": "The language model proposes words for the groups; the panel measures each and keeps only what helps.","Das Sprachmodell schlägt Wörter vor, die Übungshälfte der Alltagssätze zeigt, ob sie helfen, die Prüfhälfte, dass nichts schlechter wird. Kein Testsatz darf kippen; gespeichert wird erst mit „Übernehmen“.": "The language model proposes words; the practice half of the everyday sentences shows whether they help, the check half that nothing gets worse. No test sentence may flip; nothing is saved before \"Apply\".","Abstimmen": "Tune","„Weiche abstimmen“ ist aus (Funktionen → Gezielte Werkzeugwahl).": "\"Tune the switch\" is off (Features → Targeted tool choice).","Die Abstimmung läuft schon.": "The tuning is already running.","Kein Vorschlag zum Übernehmen.": "No proposal to apply.","Die Wörter der Weiche haben sich seitdem geändert. Bitte neu abstimmen.": "The switch's words changed since. Please tune again.","Ein Testsatz käme jetzt anders heraus. Bitte neu abstimmen.": "A test sentence would now turn out different. Please tune again.","Werkstatt": "Workshop","Tests, Code-Messung, Diagnose und Reparatur in einer abgeschotteten Kopie auf dem Modell-Rechner: ohne Daten, ohne Internet.": "Tests, code measurement, diagnosis and repair in a sealed-off copy on the model computer: no data, no internet.","Jede Nacht testen": "Test every night","Einmal pro Nacht alle Selbsttests wie auf GitHub; nach einem Modellwechsel danach die Code-Messung.": "Once a night all self-tests as on GitHub; after a model switch the code measurement follows.","Start ab (Uhr)": "Start from (o'clock)","0 bis 23, Standard 3. Die Messung startet bis 5 Stunden danach.": "0 to 23, default 3. The measurement starts up to 5 hours later.","Testlauf": "Test run","Code-Messung": "Code measurement","Reparatur": "Repair","Was passiert, was sollte passieren?": "What happens, what should happen?","Diese Art von Auftrag gibt es nicht.": "There is no such kind of order.","Ein Auftrag läuft schon.": "An order is already running.","OpenCode fehlt. Auf dem Modell-Rechner einmal: sudo ./install.sh --werkstatt": "OpenCode is missing. On the model computer once: sudo ./install.sh --werkstatt","Erst auf das eigene Sprachmodell umziehen: sudo speech-spark modelle llm uebernehmen": "First move to the own language model: sudo speech-spark modelle llm uebernehmen","Bitte das Problem in 8 bis 2000 Zeichen beschreiben.": "Please describe the problem in 8 to 2000 characters.","Der Auftrag ließ sich nicht starten. Auf dem Modell-Rechner: sudo ./install.sh --werkstatt": "The order could not be started. On the model computer: sudo ./install.sh --werkstatt","Die Werkstatt ist aus (Funktionen → Werkstatt).": "The workshop is off (Functions → Workshop).","Kein solcher Auftrag.": "No such order.","Namen fürs Hören": "Names for listening","Die Spracherkennung bekommt die Namen von Räumen, Geräten und Personen und schreibt sie richtig.": "The speech recognition gets the names of rooms, devices and people and writes them correctly.","Prüfzugang für die iPhone-App": "Review access for the iPhone app","Für Apples Prüfung im App Store: Adresse und ein getippter Code statt des Kopplungslinks, 14 Tage gültig.": "For Apple's App Store review: the address and a typed code instead of the pairing link, valid 14 days.","Apps merken sich den letzten Stand": "Apps keep the last state","Die Apps zeigen beim Öffnen gleich Gespräche, Chats und Einstellungen vom letzten Mal. Nur auf dem eigenen Handy, ohne Dateien.": "The apps show the conversations, chats and settings of last time as soon as they open. Only on your own phone, without files.","Aufträge mit Plan, Rückfrage und Vorschlag": "Jobs with plan, questions and proposals","Ein Auftrag zeigt seine Schritte, fragt nach und schlägt am Ende etwas vor, ausgeführt erst nach deinem Ja.": "A job shows its steps, asks back and proposes something at the end, carried out only after your Yes.","Ablauf und Freigabe zeigen": "Show steps and approvals","Unter jeder Antwort zugeklappt die benutzten Werkzeuge; ein Vorschlag oder eine Rückfrage als Karte mit Knöpfen zum Antippen.": "Below every answer the tools used, folded; a proposal or a question back as a card with buttons to tap.","Reddit und Feeds": "Reddit and feeds","Eigener Reddit-Posteingang, Subreddits und RSS-Feeds lesen, nie posten.": "Read the own Reddit inbox, subreddits and RSS feeds, never post.","Uhr: Nachrichten": "Watch: messages","Die letzten Chats lesen und mit festen Sätzen oder Diktat antworten. Private Chats bleiben am Handy.": "Read the latest chats and reply with fixed sentences or dictation. Private chats stay on the phone.","Uhr: Antwortvorschläge": "Watch: reply suggestions","Bis zu drei kurze Antworten vom Sprachmodell zum Antippen; geschickt wird nur, was man wählt.": "Up to three short replies from the language model to tap; only what you pick is sent.","Uhr: Fernbedienung": "Watch: remote","Bis zu 12 selbst gewählte Geräte aus Home Assistant und die eigenen Lautsprecher mit festen Tasten.": "Up to 12 own picked devices from Home Assistant and the own speakers with fixed buttons.","Uhr: Schritte, Puls und Schlaf": "Watch: steps, pulse and sleep","Die Zahlen der Uhr versiegelt im Profil, nur unter Ich → Pebble-Uhr zu sehen und zu löschen.": "The watch's numbers sealed in the profile, seen and deleted only under Me → Pebble watch.","Spark-Zifferblatt": "Spark watchface","Eigenes Zifferblatt mit Uhrzeit, nächstem Termin, Erinnerung und Wetter; holt alle 15 Minuten neu.": "An own watchface with the time, next appointment, reminder and weather; fetched again every 15 minutes.","Uhr: Mein Tag und meine Woche": "Watch: my day and my week","Heute und die letzten und nächsten 7 Tage in festen Sätzen aus den eigenen Daten, ohne Sprachmodell.": "Today and the last and next 7 days in fixed sentences from your own data, without the language model.","Uhr: Meldungen für Admins": "Watch: notes for admins","Fällt ein Dienst aus, zeigt das Zifferblatt der Admins es an und vibriert einmal. Nur mit dem Dienst-Wächter.": "When a service fails, the admins' watchface shows it and vibrates once. Only with the service watch.","Uhr: Schnell merken": "Watch: quick notes","In der Liste „Merken“ wählen und einen Satz sagen: er kommt ins Gedächtnis wie „merk dir“.": "Pick „Merken“ in the list and say a sentence: it goes into memory like „remember“.","Uhr: Ort beim Merken": "Watch: place with a note","Das Handy hängt den Ort (auf etwa 100 m) an den gemerkten Satz, wenn man es der Pebble-App erlaubt.": "The phone adds the place (to about 100 m) to the noted sentence when the Pebble app is allowed to.","Uhr: Nachfragen zum Antippen": "Watch: follow-ups to tap","Bis zu drei Folgefragen unter einer Antwort, antippen fragt weiter. Nie nach Mail, Web oder einem Vorschlag.": "Up to three follow-ups under an answer, tap one to ask on. Never after mail, web or a proposal.","Uhr: Schnellbefehle": "Watch: quick commands","Eigene feste Sätze je Profil (Ich → Pebble-Uhr); lang OBEN zeigt sie, Mitte schickt einen ab.": "Own fixed sentences per profile (Me → Pebble watch); hold UP to see them, SELECT sends one.","Uhr: Erinnerungen und Timer am Handgelenk": "Watch: reminders and timers on the wrist","Die nächsten 8 Erinnerungen und Timer liegen auf der Uhr und vibrieren auch ohne Handy.": "The next 8 reminders and timers are kept on the watch and vibrate even without the phone.","Rundlauf": "Round trip","Sprechen, Hören, Sprachmodell · echter Probelauf": "Speaking, listening, language model · real test run","Rundlauf prüfen": "Round-trip check","Alle paar Minuten ein echter Probelauf durch Sprechen, Hören und Sprachmodell. Hakt ein Schritt zweimal, hören die Admins es.": "Every few minutes a real test run through speaking, listening and the language model. If a step fails twice, the admins hear of it.","Abstand": "Spacing","alle 2 Minuten": "every 2 minutes","alle 5 Minuten": "every 5 minutes","alle 15 Minuten": "every 15 minutes","Ausgelassen, solange jemand spricht, in einer Wartungspause, bei einem Update und während Bilder oder Musik entstehen. Ergebnis unter Zustand → Überblick.": "Left out while someone talks, in a maintenance pause, during an update and while pictures or music are being made. Result under Status → Summary.","Praxistest": "Hands-on test","Was neu ist und im Alltag noch ausprobiert werden sollte, das Neueste oben. Je Punkt „Klappt“, „Problem“ oder „Später“. Nur für Admins.": "What is new and should still be tried out in daily use, the newest first. Per point „Works“, „Problem“ or „Later“. Admins only.","Lieder machen lassen, instrumental oder mit Gesang; ohne Internet, als KI-erzeugt markiert.": "Have songs made, instrumental or with singing; without the internet, marked as made by an AI.","Das Musikmodell kommt mit der Installation auf dem Modell-Rechner: sudo ./install.sh --musik 2b oder xl (nacheinander installiert bleiben beide). „Musik testen“ misst jedes installierte Modell. Sexuelles, Gewalt, Hass, „im Stil von“ einem Künstler und Passwörter macht er nie (feste Regeln); Namen gehen.": "The music model comes with the installation on the model computer: sudo ./install.sh --musik 2b or xl (installed one after the other, both stay). \"Test music\" measures every installed model. It never makes anything sexual, violent or hateful, \"in the style of\" an artist or with passwords (fixed rules); names are fine.","wie installiert": "as installed","2B turbo + 1,7B": "2B turbo + 1.7B","2B turbo + 0,6B": "2B turbo + 0.6B","XL turbo + 1,7B (klingt besser, braucht mehr Speicher)": "XL turbo + 1.7B (sounds better, needs more memory)","Lieder pro Profil und Tag": "Songs per profile and day","1 bis 100, Standard 10.": "1 to 100, default 10.","50 bis 20000, Standard 500. Ein Lied von 2 Minuten braucht rund 3 MB.": "50 to 20000, default 500. A song of 2 minutes takes about 3 MB.","Längstes Lied (Sekunden)": "Longest song (seconds)","30 bis 600, Standard 300. Ohne Angabe wird ein Lied 2 Minuten lang.": "30 to 600, default 300. Without a length a song is 2 minutes long.","Misst Musik machen mit ACE-Step 1.5 auf dem Modell-Rechner, und zwar jedes installierte Modell: zwei feste Probestücke (30 Sekunden Klavier, 60 Sekunden mit deutschem Gesang), dazu Zeit, Speicher an der Spitze und beide Stücke zum Anhören. Modelle kommen mit der Installation auf dem Modell-Rechner:": "Measures making music with ACE-Step 1.5 on the model computer, every installed model: two fixed samples (30 seconds of piano, 60 seconds with German vocals), plus time, memory at the peak and both samples to listen to. Models come with the installation on the model computer:","(xl klingt besser und braucht mehr Speicher; nacheinander installiert bleiben beide). Welches Modell die Profile nutzen, wählst du bei Musik machen unter Funktionen.": "(xl sounds better and needs more memory; installed one after the other, both stay). Which model the profiles use, you pick at Making music under Features.","Tipps beim Sprechen": "Tips while talking","Das kannst du auch sagen": "You can also say","Am Lautsprecher, Telefon und im Auto höchstens ein Beispielsatz am Tag; je Profil abschaltbar.": "On speakers, phone and in the car at most one example sentence a day; each profile can switch it off.","Beispielsätze für Funktionen, die an sind, aber nie benutzt werden. Ein Tipp setzt den Satz nur ins Eingabefeld.": "Example sentences for functions that are on but never used. A tap only puts the sentence into the input field.","Steuerzentrale am Bildschirm": "Control centre on the screen","Alles auf einer Textanzeige am HDMI-Ausgang des Panel-Rechners; startet beim Booten ohne Anmeldung, nur Art, Ort, Zeit und Zahlen.": "Everything on one text screen at the panel computer's HDMI output; starts at boot without signing in, only kind, place, time and numbers.","Anzeige an ab (Uhr)": "Screen on from (hour)","Anzeige aus ab (Uhr)": "Screen off from (hour)","Standard 7 bis 23 Uhr; zweimal dieselbe Stunde heißt immer an. Außerhalb schläft der Bildschirm.": "Default 7 to 23 o'clock; the same hour twice means always on. Outside, the screen sleeps.","Schriftgröße": "Font size","Automatisch nach Auflösung": "Automatic by resolution","Kleiner (mehr Platz)": "Smaller (more room)","Größer (besser lesbar)": "Larger (easier to read)","Automatisch: Full HD etwa 160 × 45 Zeichen, 4K etwa 240 × 67.": "Automatic: Full HD about 160 × 45 characters, 4K about 240 × 67.","Rechner": "Computers","beide Rechner · letzte 20 Minuten": "both computers · last 20 minutes","Musik machen": "Making music","Musik testen": "Test music","Musik bearbeiten": "Editing music","Ein Lied verlängern, umbauen, in eine andere Musikrichtung bringen, schneiden; das Original bleibt, eigene Lieder nur mit Rechte-Haken.": "Extend a song, rework it, move it to another music style, cut it; the original stays, own songs only with the rights tick.","Bilder ändern": "Changing pictures","Ein eigenes Foto oder Bild nach einem Satz ändern lassen, mit FLUX.2 klein; das Original bleibt, das Ergebnis als KI-bearbeitet markiert.": "Have an own photo or picture changed after a sentence, with FLUX.2 klein; the original stays, the result is marked as AI-edited.","Gehäuse": "Case","Pironman 5 am Panel-Rechner: das Display zeigt dem Admin Zustand und Zahlen, die LEDs die Statusfarbe, die Lüfter laufen nach Temperatur.": "Pironman 5 on the panel computer: the display shows the admin status and numbers, the LEDs the status colour, the fans run by temperature.","Keins": "None","Seitenwechsel (Sekunden)": "Page change (seconds)","3 bis 60, Standard 6.": "3 to 60, default 6.","Helligkeit des Displays (%)": "Display brightness (%)","1 bis 100, Standard 60.": "1 to 100, default 60.","Helligkeit der LEDs (%)": "LED brightness (%)","0 bis 100, Standard 30; 0 schaltet sie aus.": "0 to 100, default 30; 0 switches them off.","Display": "Display","Immer an": "Always on","Nur bei Problemen": "Only on problems","Nachts": "At night","Display und LEDs aus": "Display and LEDs off","Gedimmt": "Dimmed","Wie am Tag": "As by day","Nacht von (Uhr)": "Night from (hour)","Nacht bis (Uhr)": "Night until (hour)","Standard 22 bis 7 Uhr.": "Default 22 to 7 o'clock.","Drehung des Displays": "Display rotation","Seiten des Displays": "Pages of the display","Antippen schaltet eine Seite an oder aus, Ziehen oder ◀ ▶ ändert die Reihenfolge. Mindestens eine bleibt an. Die Bilder zeigen die Werte von jetzt.": "A tap switches a page on or off, dragging or ◀ ▶ changes the order. At least one stays on. The pictures show the values of now.","Lüfter an ab (°C)": "Fans on from (°C)","40 bis 80, Standard 55.": "40 to 80, default 55.","Lüfter aus unter (°C)": "Fans off below (°C)","30 bis 75, Standard 48. Eine neue Grenze gilt nach „Einrichten“ und einem Neustart.": "30 to 75, default 48. A new threshold counts after “Einrichten” and a restart.","Einrichten": "Set up","Entfernen": "Remove","Neu starten": "Restart","Terminal-Client": "Terminal client","Programm „spark-tui“ für ein Terminal, etwa die uConsole: Chat, Gespräche, Heute und Aufträge. Gekoppelt unter Ich → Terminal.": "The \"spark-tui\" program for a terminal, e.g. the uConsole: chat, conversations, Today and jobs. Paired under Me → Terminal.","Notbetrieb mit Parakeet": "Emergency mode with Parakeet","Panel auf eigenem Rechner, DGX weg: Parakeet hört, feste Befehle (Licht, Uhrzeit, Erinnerungen) gehen ohne Sprachmodell.": "Panel on its own computer, DGX gone: Parakeet hears, fixed commands (lights, time, reminders) work without a language model.","Modell-Rechner": "Model computer","Sprache, LLM und Bilder · Heimnetz": "Speech, LLM and pictures · home network","Der Modell-Rechner antwortet gerade nicht.": "The model computer is not answering right now.","Protokoll zeigen": "Show log","Protokoll kopieren": "Copy log","Eigene Modelle": "Own models","Admins fügen Sprach- und Bildverständnis-Modelle von Hugging Face hinzu, nur nach festen Regeln (safetensors, kein fremder Code).": "Admins add language and image understanding models from Hugging Face, only under fixed rules (safetensors, no foreign code).","Modelle wechseln": "Switch models","Modellwechsel": "Model switch","Admins wechseln unter Zustand → Modelle das Modell einer Art; das alte bleibt 7 Tage zum Zurückholen.": "Admins switch the model of a kind under Status → Models; the old one stays 7 days to bring back.","Modelle": "Models","LLM-Tor": "LLM gate","LLM-Engine": "LLM engine","Bildverständnis": "Image understanding","Jetzt": "Now","Heute": "Today","letzte 24 Std. · antippen öffnet die Stelle": "last 24 h · tap opens the place","Bereiche": "Areas","Zum offenen Punkt": "To the open point","Gruppen mit anderen Sparks": "Groups with other Sparks","Admins einer Gruppe nehmen ihre angenommenen Kontakte auf anderen Sparks auf; bisher nur Text, höchstens 10 Sparks pro Gruppe.": "Group admins add their accepted contacts on other Sparks; text only for now, at most 10 Sparks per group.","Fotos und Dateien zu anderen Sparks": "Photos and files to other Sparks","Fotos, Dateien und Sprachnachrichten in Chats mit anderen Sparks; der Empfänger prüft sie, höchstens 500 MB pro Spark und Tag.": "Photos, files and voice messages in chats with other Sparks; the receiver checks them, at most 500 MB per Spark and day.","Mailstil lernen": "Learn mail style","Für dich aus Mails": "For you from mail","Findet in den eigenen Mails Rechnungen mit Frist, Verträge, Bestellungen, Angebote, offene Antworten und Phishing; feste Regeln, nur lesend.": "Finds bills with a deadline, contracts, orders, offers, open replies and phishing in the own mails; fixed rules, read-only.","Neue Mails sofort": "New mail at once","Bestätigungscodes": "Confirmation codes","Code aus einer neuen Mail („482913 ist dein Code“) als Mitteilung aufs genutzte Gerät, mit Kopieren; nie über Telegram, nie im Log.": "A code from a new mail (\"482913 is your code\") as a note on the device in use, with copy; never through Telegram, never in the log.","Neue Mails nach Sekunden auf der Seite E-Mail, Regeln greifen gleich (IMAP IDLE); für aktive Leser, höchstens 4 Verbindungen.": "New mail on the E-mail page within seconds, rules act at once (IMAP IDLE); for active readers, at most 4 connections.","Lernt aus den gesendeten Mails, wie jemand schreibt, damit Mail-Entwürfe nach ihm klingen; nur lesend, keine Mail wird gespeichert.": "Learns from the sent mails how someone writes, so mail drafts sound like them; read-only, no mail is kept.","Automatisch bei Neustart": "Automatically on restart","Startet ein Modell neu (auch beim Umschalten in qwen38), pausiert der Spark diesen Teil selbst, bis er wieder antwortet.": "When a model restarts (also when qwen38 switches), the Spark pauses that part by itself until it answers again.","Installieren": "Install","Anrufen": "Call","Videoanruf": "Video call","Ablehnen": "Decline","Annehmen": "Answer","Mit Video": "With video","Stumm": "Mute","Kamera aus": "Camera off","Auflegen": "Hang up","Anrufe (Sprache und Video)": "Calls (voice and video)","Anrufen und Videoanrufe in Chats zu zweit; Ton und Bild gehen verschlüsselt von Gerät zu Gerät, der Spark vermittelt nur. Braucht https.": "Voice and video calls in chats of two; sound and picture go encrypted from device to device, the Spark only connects them. Needs https.","Anrufe von unterwegs": "Calls when away","Ein eigener Vermittler (TURN) auf dem Spark verbindet Anrufe auch aus dem Mobilfunk; er sieht nur verschlüsselte Pakete.": "An own relay (TURN) on the Spark connects calls from mobile networks too; it only sees encrypted packets.","Adresse des Sparks von außen": "Address of the Spark from outside","Nur der Name, ohne https:// und Pfad; leer = die Adresse für andere Sparks. Im Router UDP 3478 und UDP 49160 bis 49200 an den Spark weiterleiten. Ändern braucht den zweiten Anmeldeschritt.": "Only the name, without https:// and path; empty = the address for other Sparks. In the router forward UDP 3478 and UDP 49160 to 49200 to the Spark. Changing it needs the second sign-in step.","Dieses Gerät wartet nicht mehr auf den Verlauf.": "This device is no longer waiting for the history.","Wartungspause": "Maintenance pause","Vor einem Update von Sprachmodell, Spracherkennung oder Sprachausgabe hält der Spark kurz an: fester Satz statt Fehler, Hintergrund wartet.": "Before an update of the language model, speech recognition or speech output the Spark pauses: a fixed sentence instead of an error, background work waits.","+15 min": "+15 min","Pause starten": "Start pause","Vor einem Update von Sprachmodell, Spracherkennung oder Sprachausgabe: der Spark antwortet mit einem festen Satz, Hintergrundarbeit wartet, der Dienst-Wächter bleibt still. Danach geht es von selbst weiter, sobald alles wieder antwortet.": "Before an update of the language model, speech recognition or speech output: the Spark answers with a fixed sentence, background work waits, the service watch stays quiet. Afterwards it goes on by itself once everything answers again.","Ablage-Ordner": "Filing folder","Ordner „spark_ablage“ im Heimnetz: der Spark legt dort Erstelltes ab und holt den Eingang zu den Dokumenten. Woanders schreibt er nie.": "Folder \"spark_ablage\" at home: the Spark puts what it made there and takes the inbox into the documents. It writes nowhere else.","Eingang abholen alle (Minuten)": "Take in the inbox every (minutes)","5 bis 1440, Standard 15; nur in ruhigen Minuten. Abgeholtes wandert nach Eingang/erledigt, nichts wird gelöscht.": "5 to 1440, default 15; only in quiet minutes. What was taken in moves to Eingang/erledigt, nothing is deleted.","Wissensordner": "Knowledge folders","Profile wählen Ordner an ihren Orten; der Spark liest die Dokumente dort nur und findet sie bei Fragen.": "Profiles pick folders at their places; the Spark only reads the documents there and finds them when asked.","Höchstens Dokumente von Orten pro Profil": "At most documents from places per profile","Abgleich alle (Minuten)": "Compare every (minutes)","15 bis 1440, Standard 30; nur in ruhigen Minuten, nie während der Spark spricht.": "15 to 1440, default 30; only in quiet minutes, never while the Spark speaks.","Pro Profil nur Zahlen und Zustand, nie Pfade oder Dateinamen.": "Per profile only numbers and state, never paths or file names.","Treffer nachsortieren": "Re-rank hits","Ein kleines Modell auf dem Prozessor liest Frage und Fundstellen zusammen und stellt die passendsten nach vorn.": "A small model on the processor reads question and passages together and puts the best fitting first.","klein, etwa 120 MB (empfohlen)": "small, about 120 MB (recommended)","groß, etwa 570 MB, genauer und langsamer": "large, about 570 MB, more exact and slower","Höchstens warten (ms)": "Wait at most (ms)","300 bis 2000, Standard 800. Länger wartet keine Antwort; die Suchprüfung zeigt, ob es sich lohnt.": "300 to 2000, default 800. No answer waits longer; the search check shows whether it pays off.","Suchprüfung": "Search check","Prüffragen mit bekannter richtiger Stelle messen nachts, wie gut die Dokumentensuche trifft; nur Zahlen, nichts ändert sich von selbst.": "Test questions with a known right place measure at night how well the document search hits; numbers only, nothing changes by itself.","Prüffragen vom Spark": "Test questions by the Spark","Das Sprachmodell schreibt in ruhigen Minuten zu zufälligen Stellen der Dokumente eine Frage; das Panel prüft sie nach festen Regeln.": "In quiet minutes the language model writes a question about random places of the documents; the panel checks it by fixed rules.","Prüffragen pro Tag und Profil": "Test questions per day and profile","5 bis 100, Standard 20. Höchstens 300 Prüffragen pro Profil, 3 pro Dokument.": "5 to 100, default 20. At most 300 test questions per profile, 3 per document.","Suche prüfen": "Check the search","Wie oft die Dokumentensuche bei den Prüffragen aller Profile die richtige Stelle unter den ersten 5 findet, nach Suchart. Nur Summen, nie eine Frage oder ein Dokument. Schalter unter Funktionen → Eigene Dokumente.": "How often the document search finds the right place among the first 5 for the test questions of all profiles, by kind of search. Sums only, never a question or a document. Switch under Features → Own documents.","Speicher und NAS": "Storage and NAS","Kopie meiner Daten": "Copy of my data","Profile verbinden ihre NAS oder Cloud einmal als Ort und wählen dort, wofür; die Sicherung nutzt dieselbe Anmeldung.": "Profiles connect their NAS or cloud once as a place and choose there what it is for; the backup uses the same sign-in.","Profile legen eine verschlüsselte Kopie ihrer Daten an einem ihrer Orte ab; der Spark arbeitet immer lokal weiter.": "Profiles keep an encrypted copy of their data at one of their places; the Spark always keeps working locally.","Ordner für Kopien": "Folder for copies","Pro Profil nur Name, Art, Zustand und wofür der Ort da ist, nie Adresse oder Passwort.": "Per profile only name, kind, state and what the place is for, never address or password.","Wie im Messenger, verschlüsselt auf dem Spark; „Sag Anna, das Essen ist fertig“ landet nach „Ja“ im Chat.": "Like a messenger, encrypted on the Spark; \"Tell Anna dinner is ready\" lands in the chat after \"Yes\".","Nach Antworten mit Werkzeugen: ab 90 % „erfunden“ ein Fall im Fall-Eingang, nie vor dem Sprechen.": "After answers with tool results: from 90 % \"made up\" a case in the case inbox, never before speaking.","„Geht immer noch nicht“ nach einer Handlung: erst nachsehen, nicht erneut schalten, außer auf Bitte.": "\"Still does not work\" after a deed: look first, do not switch again unless asked.","Profile können eine Antwort bewerten (fünf Gründe, kurzer Text) oder „Das war falsch“ sagen.": "Profiles can rate an answer (five reasons, a short text) or say \"That was wrong\". Every profile switches it on itself.","Höchstens drei am Tag, nur der Titel. Jedes Admin-Profil kann es für sich ausschalten.": "At most three a day, only the title. Every admin profile can switch it off for itself.","Das Sprachmodell (/v1/systemone des LLM-Tors oder von qwen38) liefert Wahrscheinlichkeiten, das Panel entscheidet mit festen Schwellen.": "The language model (/v1/systemone of the LLM-Tor or of qwen38) gives probabilities, the panel decides with fixed thresholds.","Fragen zum Spark beantwortet der Assistent aus Anleitungen, Schaltern und Doku, mit dem Weg im Panel.": "The assistant answers questions about the Spark from guides, switches and docs, with the way in the panel.","Gleich nach der Frage ein kurzer, fertig aufgenommener Satz, was der Spark tut.": "Right after the question a short pre-recorded sentence of what the Spark is doing.","Fragt der Assistent zurück, holt das Panel schon Kalender, Mails, Wetter oder Pakete. Nur lesen.": "When the assistant asks back, the panel already fetches calendar, mail, weather or parcels. Reading only.","Bei kurzen, eindeutigen Lesefragen holt das Panel die Daten selbst, ohne erste Runde des Sprachmodells.": "For short, clear reading questions the panel fetches the data itself, without the language model's first round.","Feste Regeln erkennen, worum es geht; das Sprachmodell sieht nur die passenden Werkzeuge.": "Fixed rules recognize what it is about; the language model sees only the matching tools.","200 bis 1500, Standard 400. So lange wartet die Antwort höchstens auf die eigenen Quellen. Testen unter Zustand → Prüfen.": "200 to 1500, default 400. The answer waits at most this long for the own sources. Test it under Status → Checks.","Beobachten": "Watching","Webseiten regelmäßig prüfen lassen, Meldung nur bei Neuem (Firmware, Folge, Preis). Das Panel prüft jeden Fund selbst.": "Have web pages checked regularly, a message only when something is new (firmware, episode, price). The panel checks every find itself.","Technik": "Architecture","Überblick": "Overview","Datenfluss": "Data flow","Speicherorte": "Storage places","Bausteine": "Building blocks","Wie der Spark gebaut ist: die Teile, der Weg einer Anfrage und wo welche Daten liegen. Aus dem Code der installierten Version.": "How the Spark is built: the parts, the way of a request and where which data lies. From the code of the installed version.","NAS-Verbindungen": "NAS connections","Docling-Server": "Docling server","Ein Docling-Server im Heimnetz liest Dokumente und Scans in Pausen noch einmal, mit Tabellen. Die Dateien gehen dafür an ihn.": "A Docling server in the home network reads documents and scans once more in quiet moments, with tables. The files go to it for that.","Adresse des Docling-Servers": "Address of the Docling server","API-Schlüssel (DOCLING_SERVE_API_KEY)": "API key (DOCLING_SERVE_API_KEY)","Achtung: Mit http gehen Dateien und Schlüssel unverschlüsselt durchs Heimnetz. Besser https, zum Beispiel mit Caddy vor dem Docling-Server.": "Careful: with http, files and key cross the home network unencrypted. Better https, for example with Caddy in front of the Docling server.","Probe lesen": "Read sample","Du hast schon 20 offene Anfragen.": "You already have 20 open requests.","Höchstens 300 Kontakte auf anderen Sparks.": "At most 300 contacts on other Sparks.","Höchstens 5 offene Kopplungs-Codes.": "At most 5 open pairing codes.","Höchstens 200 Sparks.": "At most 200 Sparks.","Chats mit anderen Sparks": "Chats with other Sparks","Personen auf anderen Sparks per Adresse anfragen; erst nach „Annehmen“ kommt eine Nachricht durch. Braucht eine Adresse von außen.": "Ask people on other Sparks by their address; only after \"Accept\" does a message get through. Needs an address from outside.","Adresse dieses Sparks von außen": "This Spark's address from outside","Nur der Name, unter dem andere Sparks diesen per https erreichen, ohne https:// und ohne Pfad. Ändern braucht den zweiten Anmeldeschritt.": "Only the name other Sparks reach this one at over https, without https:// and without a path. Changing it needs the second login step.","Wer darf sich verbinden": "Who may connect","nur gekoppelte Sparks (ein Code zwischen beiden Admins, empfohlen)": "only paired Sparks (a code between both admins, recommended)","jeder Spark, wie bei E-Mail (sperren geht)": "every Spark, like e-mail (blocking works)","Chats mit anderen Sparks sind gerade ausgeschaltet.": "Chats with other Sparks are switched off right now.","Chats mit anderen Sparks sind auf dem Spark aus.": "Chats with other Sparks are off on the Spark.","Chats mit anderen Sparks sind für dich aus.": "Chats with other Sparks are off for you.","Chats sind auf diesem Spark für dich aus.": "Chats are off for you on this Spark.","Diese Person ist nicht mehr in deinen Kontakten auf anderen Sparks.": "This person is no longer in your contacts on other Sparks.","Mit diesem Spark sind Chats gerade nicht erlaubt.": "Chats with this Spark are not allowed right now.","Eine Spark-Adresse sieht so aus: name@spark.example.de": "A Spark address looks like this: name@spark.example.de","Diese Adresse ist auf diesem Spark. Schreib der Person einfach unter ＋ Neuer Chat.": "This address is on this Spark. Just write to the person under ＋ New chat.","Zu viele Nachrichten warten auf andere Sparks. Bitte später noch einmal.": "Too many messages wait for other Sparks. Please try again later.","Zuerst die eigene Adresse von außen eintragen.": "First enter the own address from outside.","Der Code sieht so aus: spark.example.de#… (vom Admin des anderen Sparks).": "The code looks like this: spark.example.de#… (from the other Spark's admin).","Das ist der Code dieses Sparks.": "That is this Spark's own code.","Der andere Spark ist nicht erreichbar oder hat Chats mit anderen Sparks nicht an.": "The other Spark is not reachable or does not have chats with other Sparks on.","Dieser Spark hat einen anderen Schlüssel als beim letzten Mal. Erst entfernen, dann neu koppeln.": "This Spark has a different key than last time. Remove it first, then pair again.","Der andere Spark hat den Code nicht angenommen (abgelaufen, schon benutzt oder falsch).": "The other Spark did not accept the code (expired, already used or wrong).","Diesen Spark gibt es in der Liste nicht.": "This Spark is not in the list.","Kontakt auf einem anderen Spark": "Contact on another Spark","Einklappen": "Collapse","Die feste Gruppe „Alle“ und „Sag allen, wir fahren um acht“; jedes Profil nimmt selbst daran teil.": "The fixed group \"Alle\" (everybody) and \"Tell everybody we leave at eight\"; each profile joins it itself.","„Durchsage im Wohnzimmer: Essen ist fertig“, nur auf Lautsprechern, deren Besitzer Durchsagen erlaubt.": "\"Announcement in the living room: dinner is ready\", only on speakers whose owner allows announcements.","80 % (Standard)": "80 % (default)","Die Testsätze der Weiche einmal durch die Einordnung schicken: wie oft sie eingrenzt und wie oft das falsch wäre, je Schwelle, mit Vorschlag. Läuft im Hintergrund und wartet, solange jemand spricht.": "Send the switch's test sentences through the classification once: how often it narrows and how often that would be wrong, per threshold, with a suggestion. Runs in the background and waits while somebody speaks.","Einordnung messen": "Measure classification","Im Einstellungs-Assistenten": "In the settings assistant","Welcher Vorschlag aus dem Katalog zu einem Fall passt, mit Wahrscheinlichkeit; vorgeschlagen erst ab 60 %.": "Which catalog proposal fits a case, with a probability; proposed only from 60 %.","Antworten im Hintergrund prüfen": "Check answers in the background","Beschwerde erkennen": "Recognize complaints","Aufgabenblatt zum Ankreuzen": "Task sheet to tick","Punkte zum Ankreuzen; der Spark führt die Antworten aus, bei Admins auch Vorschläge. Es liegt immer ein Blatt da, auch ohne Offenes.": "Points to tick; the Spark carries out the answers, for admins also proposals. There is always a sheet, also with nothing open.","Papier fürs reMarkable": "Paper for the reMarkable","Gestaltete Blätter im Format des Geräts mit „Kann weg“ und Kästchen zum Abhaken, Ordner nach Art, selbst aufräumen; je Profil einzeln.": "Designed sheets in the device's format with \"Can go\" and boxes to tick, folders by kind, tidying up by itself; per profile.","Private Chats (Ende-zu-Ende)": "Private chats (end-to-end)","Chats zu zweit, die nur die Geräte der beiden lesen; der Spark speichert sie nur verschlüsselt und kann sie nicht lesen. Braucht https.": "Chats for two that only the two people's devices can read; the Spark stores them only encrypted and cannot read them. Needs https.","Das ist kein gültiger Schlüssel.": "That is not a valid key.","Private Chats sind für dich ausgeschaltet.": "Private chats are switched off for you.","Höchstens 10 Geräte für private Chats. Ein altes unter ⓘ → Deine Geräte entfernen.": "At most 10 devices for private chats. Remove an old one under ⓘ → Your devices.","Diese Person hat private Chats nicht an.": "This person does not have private chats on.","Diese Person hat noch kein Gerät für private Chats. Sie muss einmal einen privaten Chat öffnen.": "This person has no device for private chats yet. They have to open a private chat once.","Dieses Gerät hat noch keinen Schlüssel für private Chats.": "This device has no key for private chats yet.","Private Chats sind auf dem Spark aus.": "Private chats are off on the Spark.","Dieses Gerät ist für private Chats nicht mehr eingetragen. Seite neu laden.": "This device is no longer added for private chats. Reload the page.","Die andere Person hat ein neues Gerät. Seite neu laden und noch einmal senden.": "The other person has a new device. Reload the page and send again.","Private Chats gehen nur verschlüsselt.": "Private chats only work encrypted.","„Warum?“ für alle Profile": "\"Why?\" for every profile","„Warum hast du eben im Web gesucht?“ erklärt den Weg der letzten Antwort in einfachen Worten, ohne Regeln.": "\"Why did you just search the web?\" explains the way of the last answer in plain words, without rules.","Automatisch zurücknehmen": "Undo automatically","Sinkt danach die 👍-Quote der Gruppe um 15 Punkte oder kommt der Fall wieder, nimmt der Spark die Regel zurück und sagt es.": "When the 👍 share of the group then drops by 15 points, or the case comes back, the Spark undoes the rule and says so.","Spark-Tagebuch": "Spark diary","Der Spark notiert 7 Tage lang, was er selbst getan hat, und beantwortet daraus „Was hast du heute für mich gemacht?“.": "For 7 days the Spark notes what it did itself and answers \"What did you do for me today?\" from it.","Werkzeug-Hinweise": "Tool hints","Ein Satz pro Werkzeug, den das Modell bekommt, wenn das Werkzeug angeboten wird.": "One sentence per tool that the model gets when the tool is offered.","Eine Zeile pro Werkzeug: vorne der Name, dann ein Doppelpunkt und ein Satz mit 4 bis 200 Zeichen, ohne spitze oder geschweifte Klammern. Höchstens 20 Hinweise. Der Einstellungs-Assistent schlägt nur feste Sätze vor.": "One line per tool: the name first, then a colon and a sentence of 4 to 200 characters, without angle or curly brackets. At most 20 hints. The settings assistant only proposes fixed sentences.","Fall analysieren": "Analyse case","Das lokale Modell wählt für einen Fall eine Regel aus festen Vorlagen und spielt sie nach. Übernehmen kannst nur du.": "The local model picks a rule from fixed templates for a case and replays it. Only you can take it.","Eine Zeile pro Werkzeug, zum Beispiel calendar_events, web_search oder document_status; jedes Werkzeug der Weiche geht. Nur ganze Wörter, höchstens 20 pro Werkzeug. Die eingebauten Wörter bleiben immer.": "One line per tool, for example calendar_events, web_search or document_status; every tool of the Weiche works. Whole words only, at most 20 per tool. The built-in words always stay.","Taten prüfen": "Check deeds","Fehlerschleife stoppen": "Stop error loops","Sagt die Antwort „ist jetzt an“ oder „habe eingetragen“, ohne dass ein Werkzeug es geschafft hat, sagt der Spark ehrlich, was passiert ist.": "When the answer says \"is on now\" or \"I have entered it\" and no tool managed it, the Spark says honestly what happened.","Scheitert ein Werkzeug zweimal mit denselben Angaben, ruft der Spark es in dieser Antwort nicht noch einmal auf.": "When a tool fails twice with the same details, the Spark does not call it again in this answer.","Stopp beim Vorlesen": "Stop while it speaks","Während ein Lautsprecher spricht, bleibt sein Mikrofon an: „Stopp“ ohne Weckwort macht ihn sofort still. Nur Boards mit Echo-Filter.": "While a speaker talks its microphone stays on: \"Stopp\" without the wake word makes it quiet at once. Only boards with echo cancelling.","Zuordnungen": "Mappings","Deine eigenen Wörter für deine Geräte: „Fernseher im Wohnzimmer“ schaltet dann sofort das Gerät, das du gewählt hast. Das Codewort braucht es weiterhin.": "Your own words for your devices: \"TV in the living room\" then switches the device you chose straight away. The code word is still needed.","Rückfrage statt Raten": "Ask instead of guessing","Passt ein Befehl auf mehrere Geräte oder auf keins genau, fragt der Assistent nach und zeigt die Auswahl, statt zu raten.": "If a command fits several devices or none exactly, the assistant asks and shows the choice instead of guessing.","Auswahl merken": "Remember the choice","Nach der Auswahl fragt er, ob er sie sich merken soll; nach „Ja“ gilt derselbe Satz künftig sofort.": "After the choice it asks whether to remember it; after \"yes\" the same sentence works straight away from then on.","Themen im Gedächtnis": "Memory topics","Das Sprachmodell im Heimnetz ordnet neue Einträge Themen zu (Person, Zuhause, Arbeit …). Nur zur Anzeige, entscheidet nichts.": "The language model in the home network sorts new entries into topics (person, home, work …). Only for display, decides nothing.","Im Gespräch nachfragen": "Check back in conversations","Passt ein vielleicht veralteter Eintrag zur Frage, fragt der Spark nach der Antwort: „Stimmt das noch?“ Einmal pro Gespräch, 3× am Tag.": "When an entry that may be out of date fits the question, the Spark asks after the answer: \"Is this still right?\" Once per conversation, 3× a day.","Gedächtnis prüfen": "Memory check","Jeder Eintrag behält, woher er kommt; feste Regeln markieren, was veraltet sein könnte. Das Modell nennt es nie als Tatsache.": "Every entry keeps where it came from; fixed rules mark what may be out of date. The model never states it as a fact.","Gelernt gilt als alt nach (Monaten)": "Learned counts as old after (months)","1 bis 60, Standard 6. Nur automatisch gelernte Einträge, die nie bestätigt wurden.": "1 to 60, default 6. Only entries learned automatically that were never confirmed.","Bilder aus dem Kiwix": "Pictures from the Kiwix","Titelfolie und „Bild und Text“-Folien bekommen ein Bild aus der Wikipedia im eigenen Kiwix, mit Quelle. Braucht das Kiwix-Archiv.": "The title slide and \"Picture and text\" slides get a picture from the Wikipedia in the own Kiwix, with its source. Needs the Kiwix archive.","Ideen außerhalb des Katalogs": "Ideas outside the catalog","Hat der Katalog nichts, nennt das lokale Modell eine Idee, nur zum Lesen. Ändern kannst nur du selbst.": "When the catalog has nothing, the local model names an idea, to read only. Only you can change things.","Verlauf sofort abgleichen": "Instant history sync","Was ein Profil auf einem Gerät fragt, steht sofort im offenen Panel seiner anderen Geräte, ohne Neuladen.": "What a profile asks on one device shows up at once in the open panel on its other devices, without reloading.","Ein Gespräch für alle Kanäle": "One conversation for all channels","Telegram, Siri, Begleiter, Uhr und Lautsprecher schreiben ins heutige Hauptgespräch des Profils, mit Kanal-Zeichen.": "Telegram, Siri, the companion, the watch and speakers write into the profile's main conversation of today, marked with the channel.","Verlauf offline lesen": "Read history offline","Browser, denen ein Profil vertraut, behalten eine Kopie seiner Gespräche zum Lesen ohne Spark; alle anderen speichern nichts.": "Browsers a profile trusts keep a copy of its conversations to read without the Spark; all others store nothing.","Einstellungs-Assistent": "Settings assistant","Fehler, 👎 und unklare Fragen werden Fälle mit Vorschlägen aus einem festen Katalog. Übernehmen nur du, unter Zustand → Verbessern.": "Errors, 👎 and unclear questions become cases with proposals from a fixed catalog. Only you take them, under Status → Improve.","👍/👎 unter Antworten": "👍/👎 under answers","Rückmeldung, wenn es behoben ist": "Feedback when it is fixed","Wer 👎 gemeldet hat, hört nach der Nachkontrolle, dass eine Änderung geholfen hat.": "Whoever reported 👎 hears after the re-check that a change helped.","Anfragen erklären": "Explain requests","Unter Zustand → Logs → Anfragen erklärt ein Knopf eine Anfrage in festen Sätzen und nimmt sie auf Wunsch als Fall auf.": "Under Status → Logs → Requests a button explains a request in fixed sentences and takes it as a case if you like.","Hinweis an Admins bei neuem Vorschlag": "Note to admins on a new proposal","Im Chat nach Vorschlägen fragen": "Ask for proposals in the chat","„Was schlägt der Einstellungs-Assistent vor?“ Ein „Ja“ übernimmt nie etwas.": "\"What does the settings assistant propose?\" A \"yes\" never takes anything.","Fälle als Meldung vorbereiten": "Prepare cases as reports","Hilft nichts aus dem Katalog, wird der Fall ein Entwurf unter Probleme melden, mit Vorschau vor dem Senden.": "When nothing from the catalog helps, the case becomes a draft under Reporting problems, with a preview before sending.","Schritte für die Umgebung": "Steps for the environment","Liegt es an einem Dienst außerhalb des Spark, zeigt der Vorschlag Schritte zum Kopieren. Ausgeführt wird nichts.": "When a service outside the Spark is the cause, the proposal shows steps to copy. Nothing is run.","Vorschläge für die eigenen Einstellungen": "Proposals for the own settings","Aus den eigenen 👎 eines Profils, z. B. kürzere Antworten. Nur das Profil selbst übernimmt sie.": "From a profile's own 👎, e.g. shorter answers. Only the profile itself takes them.","Autopilot für kleine Änderungen": "Autopilot for small changes","Übernimmt Stufe A und B bei grünem Prüfstand und zwei Meldungen selbst: eine am Tag, höchstens drei Schritte, zurück bei Verschlechterung.": "Takes stage A and B itself with a green test bench and two reports: one a day, at most three steps, back when it gets worse.","Fragen ans Sprachmodell pro Tag": "Questions to the language model per day","1 bis 100. Nur ein Sprachmodell im Heimnetz wird gefragt; es wählt nur aus fertigen Vorschlägen.": "1 to 100. Only a language model at home is asked; it only picks from finished proposals.","Nachkontrolle nach Stunden": "Re-check after hours","6 bis 72.": "6 to 72.","Verbessern": "Improve","Jetzt nachsehen": "Look now","Fehler, 👎 und unklare Fragen werden Fälle. Der Spark schlägt Änderungen aus einem festen Katalog vor, prüft sie auf dem Prüfstand und schaut nach 24 Stunden, ob sie geholfen haben. Nichts ändert sich, bevor du übernimmst.": "Errors, 👎 and unclear questions become cases. The Spark proposes changes from a fixed catalog, checks them on the test bench and looks after 24 hours whether they helped. Nothing changes before you take it.","Der Einstellungs-Assistent ist aus. Einschalten unter Funktionen → Einstellungs-Assistent.": "The settings assistant is off. Switch it on under Features → Settings assistant.","Vorschläge für dich": "Proposals for you","Notzugang": "Emergency access","Das Panel-Passwort ist der Notzugang. Im Alltag meldest du dich mit deinem Profil an; hat es Admin-Rechte, bist du damit Admin.": "The panel password is the emergency access. Day to day you sign in with your profile; if it has admin rights, that makes you admin.","Notzugang (Panel-Passwort)": "Emergency access (panel password)","Wann fragt der Spark nach dem Code?": "When does the Spark ask for the code?","Schutz": "Protection","Daten": "Data","Konten": "Accounts","Personen": "People","Alles vergessen …": "Forget everything …","Löscht alles, was sich der Assistent über dich gemerkt hat. Lässt sich nicht rückgängig machen.": "Deletes everything the assistant remembered about you. Cannot be undone.","Anmeldung": "Sign-in","Browser": "Browsers","Geräte mit Schlüssel: Lautsprecher, Uhr, Handy-App.": "Devices with a key: speakers, watch, phone app.","Live-Übersicht": "Live overview","Neue geprüfte Versionen holen und einspielen.": "Fetch and install new tested versions.","Sichert jeden Tag, was der Spark weiß, auf Wunsch auch verschlüsselt auf einen NAS.": "Backs up every day what the Spark knows, on request also encrypted to a NAS.","Auf dem Spark": "On the Spark","Der Spark schreibt auf Bitte Briefe, Präsentationen und Tabellen als Word, PDF, PowerPoint oder Excel; erst die Gliederung, nach deinem Ja.": "On request the Spark writes letters, presentations and spreadsheets as Word, PDF, PowerPoint or Excel; first the outline, then after your yes.","Profile laden eigene Word- oder PowerPoint-Vorlagen hoch (ohne Makros, höchstens 10 MB); der Spark füllt sie.": "Profiles upload own Word or PowerPoint templates (no macros, at most 10 MB); the Spark fills them.","Dokumente erstellen": "Creating documents","Eigene Vorlagen": "Own templates","Quelle": "Source","Sortierung": "Sort order","Dokumente durchsuchen": "Search documents","Auswählen": "Select","＋ Hinzufügen": "＋ Add","Einstellungen für Dokumente": "Settings for documents","Suchen: Name, Absender, Tag; Enter auch im Inhalt": "Search: name, sender, tag; Enter also in the content","Vorlesen": "Read aloud","Antworten auf diesem Gerät vorlesen": "Read answers aloud on this device","Lautsprecher-Updates auch über http": "Speaker updates over http too","An: wie bisher, auch über http. Aus: über WLAN nur mit https (Proxy-Adresse), sonst per USB, sicherer im Heimnetz.": "On: as before, also over http. Off: over Wi-Fi only with https (proxy address), otherwise over USB, safer at home.","Probleme melden": "Reporting problems","Admin per Assistent informieren": "Tell the admin through the assistant","Neue Meldung eines Profils: der Assistent sagt es den Admin-Profilen, nur wer, Bereich und Weg, nie der Text.": "A profile's new report: the assistant tells the admin profiles, only who, area and way, never the text.","Profile melden Probleme als Issue an GitHub, mit anonymisierten Logs; was rausgeht, sehen sie vorher.": "Profiles report problems as an issue on GitHub, with anonymized logs; they see beforehand what goes out.","GitHub-Repo für Meldungen": "GitHub repository for reports","besitzer/name, am besten privat. Meldungen gehen nur dorthin.": "owner/name, private is best. Reports go only there.","Problem melden": "Report a problem","Meldungen": "Reports","Geräte-Updates": "Device updates","Neue Firmware und App-Versionen für Lautsprecher, Android, Pebble und Begleiter: Überblick und ein Hinweis pro Version.": "New firmware and app versions for speakers, Android, Pebble and companion: an overview and one note per version.","Lautsprecher nachts aktualisieren": "Update speakers at night","Erst einer, dann die übrigen; hält an, wenn einer nicht mit der neuen Version zurückkommt.": "First one, then the others; stops when one does not come back with the new version.","Beginn des Nachtfensters (60 Minuten)": "Start of the night window (60 minutes)","Hinweis auf neue XiaoZhi-Version": "Note on a new XiaoZhi version","Nur an den Admin, wenn das Original der Lautsprecher-Firmware neuer ist. Gebaut wird nichts von selbst.": "Only to the admin, when the original of the speaker firmware is newer. Nothing is built by itself.","Jetzt suchen": "Look now","Weiter verteilen": "Go on distributing","Nur Versionsnummern und Gerätenamen. Die Dateien kommen nur von GitHub und werden per Prüfsumme geprüft.": "Only version numbers and device names. The files come only from GitHub and are checked by checksum.","Funktionen vorschlagen": "Suggesting functions","Passt eine Funktion, die noch aus ist: ein Hinweis mit „Einrichten“. Höchstens 1 pro Gespräch, 3 pro Woche; schaltet nie selbst.": "When a function that is still off would help: a hint with \"Set up\". At most 1 per conversation, 3 a week; never switches by itself.","… auch von selbst": "… also by itself","Höchstens ein Vorschlag pro Woche als Mitteilung unter „Von selbst“ (braucht „Von selbst melden“).": "At most one suggestion a week as a notification under \"Proactive\" (needs \"Speaking up by itself\").","Eigene MCP-Dienste für Profile": "Own MCP services for profiles","Jedes Profil bindet unter Ich eigene MCP-Dienste an; nur es selbst nutzt sie, jedes Werkzeug einzeln freigegeben.": "Every profile connects its own MCP services under Me; only it uses them, every tool released one by one.","… auch in Hintergrundaufträgen": "… also in background jobs","Lesende Werkzeuge eigener Dienste in Aufträgen des Profils, nie handelnde.": "Reading tools of own services in the profile's jobs, never acting ones.","… mit Anmeldung (OAuth)": "… with sign-in (OAuth)","Dienste, die eine Anmeldung statt eines Schlüssels wollen; der Spark meldet sich selbst als Programm an.": "Services that want a sign-in instead of a key; the Spark registers itself as a program.","Eigene MCP-Dienste der Profile": "Profiles' own MCP services","Dienste, die Profile unter": "Services that profiles connected themselves under","Ich → Meine MCP-Dienste": "Me → My MCP services","selbst angebunden haben, ohne Schlüssel. Sperren gilt sofort, auch wenn das Profil den Dienst neu anbindet.": ", without keys. Blocking applies at once, also when the profile connects the service again.","Heute Nacht einspielen": "Install overnight","Eine neue geprüfte Version kommt nachts zwischen 3 und 5 Uhr, wenn gerade niemand spricht.": "A new tested version is installed at night between 3 and 5 am, while nobody is talking.","Höchstens einmal pro Nacht und nur eine Version, deren Tests auf GitHub durchgelaufen sind. Vorher wird gesichert, wie beim Knopf. Spricht gerade jemand mit dem Spark, wartet das Update bis zur nächsten Pause in diesem Zeitraum. Beim Notaus startet nichts. Einschalten braucht den zweiten Anmeldeschritt, wenn er an ist.": "At most once a night and only a version whose tests passed on GitHub. A backup is made first, like with the button. If somebody is talking with the Spark, the update waits for the next pause in that time. Nothing starts during the kill switch. Turning it on needs the second sign-in step when that is on.","Was ist neu": "What's new","Was ist neu (Changelog)": "What's new (changelog)","Alle Änderungen bis zur installierten Version, eine Zeile pro Version, neueste oben.": "All changes up to the installed version, one line per version, newest first.","Ansehen": "View","Ältere zeigen": "Show older","Suchen, z. B. reMarkable": "Search, e.g. reMarkable","Darf am PC handeln": "May act on the PC","Seite oder freigegebenes Programm öffnen, Musik, Lautstärke, Sperren; jedes Mal mit Rückfrage am PC.": "Open a page or a released program, music, volume, lock; each time with a question at the PC.","Morgenblatt, @Spark-Fragen auf Papier, Aufgaben, Besprechungen, Wochenrückblick, Webseiten, Eingang und eine Anleitung; je Profil einzeln.": "Morning sheet, @Spark questions on paper, tasks, meetings, week in review, web pages, inbox and a guide; each profile on its own.","Einordnung prüfen": "Check classification","ordnet die Einordnung mit Wahrscheinlichkeit zu, erst ab 80 % (qwen38, etwa 0,2 s)": "sorted by the classification with probabilities, only from 80 % (qwen38, about 0.2 s)","Auch Absender außerhalb der Liste, wenn die Einordnung die Mail nach Absender und Betreff zu mindestens 80 % für wichtig hält.": "Also senders not on the list when the classification rates the mail important by sender and subject with at least 80 %.","Wichtige Mails erkennen": "Recognize important mail","Zu jeder Frage eine zweite Meinung: beantwortet, erfunden. Zählt nicht für bestanden; Zweifel zeigt der Test zum Ansehen.": "A second opinion per question: answered, made up. Does not count for passing; doubts are shown to look at.","Im Qualitätstest": "In the quality test","Mails, die keine feste Regel einordnet: Kategorie mit echter Wahrscheinlichkeit, von selbst verschoben erst ab 90 %, sonst Rückfrage.": "Mails no fixed rule sorts: category with a real probability, moved by itself only from 90 %, otherwise it asks.","Beim Postfach aufräumen": "When tidying the inbox","Einordnung mit Wahrscheinlichkeit": "Classification with probabilities","Mein Notaus": "My kill switch","Legt nur dein Profil still: alle anderen Anmeldungen und Geräte-Schlüssel, MCP und Telegram sind zu, und in deinem Namen passiert nichts mehr (Smart Home, Mail, Termine, Nachrichten, Aufträge, Von selbst). Lesen und Fragen gehen in diesem Browser weiter. Die anderen Profile merken nichts.": "Stops only your profile: all other logins and device keys, MCP and Telegram are closed, and nothing happens in your name any more (smart home, mail, appointments, messages, jobs, on its own). Reading and asking go on in this browser. The other profiles notice nothing.","Mein Notaus auslösen": "Trigger my kill switch","Mein Notaus von Profilen": "Profiles' own kill switch","Diese Profile haben nur ihren eigenen Teil stillgelegt. Aufheben kann das Profil selbst mit PIN, oder du hier.": "These profiles stopped only their own part. The profile itself lifts it with its PIN, or you here.","Der Kopf unten rechts weiß, auf welcher Seite man ist, auch unter Ich; Fragen per Sprache oder Text.": "The face at the bottom right knows which page you are on, also under Me; questions by voice or text.","Frag etwas zu dieser Seite …": "Ask something about this page …","Fragen": "Ask","Frage": "Question","Schreibhilfe": "Writing help","Mails und andere Texte korrigieren, kürzen, übersetzen oder eine Antwort entwerfen; nichts wird gespeichert oder gesendet.": "Correct, shorten, translate mails and other texts or draft a reply; nothing is stored or sent.","Hilfe zum Spark": "Help with the Spark","Einstellungen vorschlagen": "Suggest settings","Unter der Antwort eine Karte mit passenden Schaltern; erst der Tipp auf „Übernehmen“ ändert etwas. Nie Sicherheit.": "A card with fitting switches under the answer; only the tap on “Apply” changes anything. Never security.","Frag Spark auf jeder Seite": "Ask Spark on every page","angehaltene Aufträge weiterlaufen lassen (sonst abgebrochen)": "let held jobs go on (else they are cancelled)","ganz aus, alles wie vorher": "fully off, everything as before","zurück auf Stufe 1 (außen bleibt zu)": "back to stage 1 (outside stays closed)","Als Admin anmelden": "Sign in as admin","Auslösen": "Trigger","Notaus": "Kill switch","Notaus auslösen": "Trigger the kill switch","Nur Art und Anzahl seit dem Auslösen, nie Inhalte.": "Only kind and count since triggering, never content.","Nur als Admin, im Browser, im Heimnetz, mit frischem Code. Sprache, Telegram, Home Assistant, MCP und das Sprachmodell können den Notaus nie aufheben.": "Only as admin, in the browser, at home, with a fresh code. Voice, Telegram, Home Assistant, MCP and the language model can never lift the kill switch.","Panel-Passwort (ohne zweiten Anmeldeschritt)": "Panel password (without second sign-in step)","Stufe erhöhen": "Raise the stage","Was der Notaus gerade abhält": "What the kill switch is holding off","Wieder einschalten": "Switch back on","Wieder einschalten …": "Switch back on …","Wirkt sofort auf alle Geräte. Aufheben kann nur ein Admin im Heimnetz mit Code.": "Works at once on all devices. Only an admin at home with a code can lift it.","Sofort-Meldungen aus Home Assistant": "Instant notes from Home Assistant","Regeln hören direkt auf Home Assistant statt jede Minute nachzusehen; kurze Bewegungen gehen nicht verloren. Bleibt im Heimnetz.": "Rules listen to Home Assistant directly instead of looking every minute; short motion is not missed. Stays in the home network.","Haus-Meldungen über Lautsprecher": "House notes on speakers","Eine Regel darf ihren eigenen Satz ohne Namen auch laut sagen, z. B. „Es hat geklingelt“, auf Lautsprechern, die Durchsagen annehmen.": "A rule may also say its own sentence without names aloud, e.g. \"Someone rang the bell\", on speakers that take announcements.","Home Assistant meldet an Spark": "Home Assistant tells the Spark","Home Assistant schickt Ereignisse wie „klingel“ mit eigenem Schlüssel; der Spark sagt den festen Satz dazu.": "Home Assistant sends events like \"klingel\" with its own key; the Spark says the fixed sentence for it.","Smart-Home-Regel per Sprache": "Smart home rule by voice","„Sag mir Bescheid, wenn jemand an der Haustür ist“ legt nach einem „Ja“ eine Regel an.": "\"Tell me when someone is at the front door\" adds a rule after a \"yes\".","Kamerabild beschreiben": "Describe a camera picture","Eine Regel kann ein Standbild einer Kamera aus Home Assistant vom lokalen Modell kurz beschreiben lassen; das Bild wird nicht gespeichert.": "A rule can have the local model briefly describe a camera still from Home Assistant; the picture is not stored.","Live-Seite": "Live page","Zeigt unter Zustand → Live, wer gerade fragt, welchen Weg die Anfrage nimmt und was der Wächter entscheidet.": "Shows under Status → Live who is asking, which way the request takes and what the guard decides.","Live-Monitor im Heimnetz": "Live monitor in the home network","Ein Bildschirm zeigt die Live-Seite ohne Anmeldung unter /live, nach einmaligem Koppeln mit einem Code.": "A screen shows the live page without a login at /live, after pairing once with a code.","Namen auf dem Monitor": "Names on the monitor","Aus: der Monitor zeigt „Person“ statt Namen, auch bei Profilen, die Namen erlauben.": "Off: the monitor shows “Person” instead of names, also for profiles that allow names.","Höchstens gleichzeitig": "At most at once","So viele Monitore dürfen zugleich zeigen.": "This many monitors may show at the same time.","Monitore": "monitors","Nur Wege, Werkzeugnamen, Zeiten und Zahlen, nie Frage, Antwort, Suchbegriffe oder Inhalte. Alles bleibt im Speicher und ist nach einem Neustart weg. Namen nur, wenn das Profil es unter Ich → Gespräch erlaubt. Sehen können es der Admin und Mit-Admins.": "Only ways, tool names, times and numbers, never question, answer, search terms or contents. Everything stays in memory and is gone after a restart. Names only when the profile allows it under Me → Conversation. The admin and co-admins can see it.","Nur aus dem Heimnetz. Unten „Neuer Monitor“ erzeugt einen 6-stelligen Code, 10 Minuten gültig, einmal benutzbar. Auf dem Bildschirm https://Spark-Adresse:31443/live öffnen und den Code eingeben. Der Monitor bleibt 90 Tage gekoppelt; Löschen beendet ihn sofort.": "Home network only. “New monitor” below makes a 6-digit code, valid 10 minutes, usable once. Open https://Spark-address:31443/live on the screen and enter the code. The monitor stays paired for 90 days; deleting ends it at once.","Vorab holen bei Rückfrage": "Fetch ahead on a question back","Sofortige Rückmeldung": "Instant acknowledgement","Eindeutiges direkt abrufen": "Fetch clear questions directly","Spark als MCP-Server": "Spark as MCP server","Andere Programme nutzen Sprache, Nachschlagen und den Assistenten über MCP; jedes Profil gibt jedem Programm eigene Werkzeuge.": "Other programs use speech, look-ups and the assistant over MCP; each profile gives each program its own tools.","MCP-Server von außen (OAuth)": "MCP server from outside (OAuth)","Auch über den Reverse-Proxy, etwa für claude.ai: nur mit zweitem Anmeldeschritt des Profils und Warnhinweis.": "Also through the reverse proxy, e.g. for claude.ai: only with the profile's second sign-in step and a warning.","MCP: Handeln mit Bestätigung": "MCP: acting with confirmation","Programme dürfen Schalten, Termine und Erinnerungen vorschlagen; ausgeführt wird erst nach dem Ja des Profils im Panel.": "Programs may propose switching, appointments and reminders; they run only after the profile's yes in the panel.","Programme wie Open WebUI, n8n, Home Assistant oder Claude verbinden sich unter": "Programs like Open WebUI, n8n, Home Assistant or Claude connect under","Ich → Spark als MCP-Server": "Me → Spark as MCP server","mit einem eigenen Zugang pro Profil (Adresse": "with their own access per profile (address",", Streamable HTTP). Hier siehst du alle Zugänge und kannst jeden sofort beenden.": ", Streamable HTTP). Here you see every access and can end each one at once.","Bei ähnlich guten Treffern gewinnt die neuere Notiz; „Was habe ich zuletzt notiert?“ nennt die neuesten Seiten. Gilt für alle Dokumente.": "With similar hits the newer note wins; \"What did I note last?\" names the newest pages. Applies to all documents.","Codewort am Lautsprecher": "Code word at a speaker","Stimme am Lautsprecher nur knapp erkannt oder etwas ungewöhnlich: vor Persönlichem fragt er nach dem Codewort. Fremde Stimmen nie.": "Voice recognised only narrowly at a speaker or something unusual: it asks for the code word before personal things. Never foreign voices.","Die Modelle, die der Server unter dieser Adresse meldet.": "The models the server at this address reports.","leer = das erste, das der Server meldet": "empty = the first one the server reports","Vertraute Browser": "Trusted browsers","So lange fragt ein Browser, dem man bei der Anmeldung vertraut, keinen Code (7 bis 90). Nach 30 Tagen ohne Nutzung fragt er wieder.": "This long a browser trusted at sign-in asks for no code (7 to 90). After 30 days without use it asks again.","Diesem Browser 60 Tage vertrauen": "Trust this browser for 60 days","Bücher auswählen": "Choose books","Ohne Auswahl nimmt der Assistent die deutsche und englische Wikipedia. Wikipedia-Bücher beantworten „Was ist …?“, die übrigen durchsucht er bei „Schau in meinem Archiv …“. Höchstens 10, danach speichern.": "Without a choice the assistant uses the German and English Wikipedia. Wikipedia books answer \"What is …?\", it searches the others for \"Look in my archive …\". At most 10, then save.","Eigenes Kiwix-Archiv": "Own Kiwix archive","Wissen aus deinem kiwix-serve, auch ohne Internet. Fällt die Websuche aus, antwortet der Assistent daraus.": "Knowledge from your kiwix-serve, also without internet. If the web search fails, the assistant answers from it.","Adresse des Kiwix": "Kiwix address","Am besten die Adresse im Heimnetz: schneller und geht ohne Internet. Ändern braucht den zweiten Anmeldeschritt.": "Best use the home network address: faster and works without internet. Changing it needs the second sign-in step.","Bücher": "Books","leer = alle, höchstens 10": "empty = all, at most 10","Kiwix-Archiv": "Kiwix archive","Prüft, ob der Spark dein Kiwix erreicht, welche Bücher es hat und wie schnell eine Testsuche antwortet. Adresse und Schalter unter Funktionen → Websuche.": "Checks whether the Spark reaches your Kiwix, which books it has and how fast a test search answers. Address and switch under Features → Web search.","Kiwix prüfen": "Check Kiwix","Admin-Rechte": "Admin rights","Profile mit Admin-Rechten": "Profiles with admin rights","Ein Profil mit Rolle ist in seiner eigenen Anmeldung Admin, ohne zweite Stufe.": "A profile with a role is admin in its own sign-in, with no second stage.","wirkt sofort, mit Code": "takes effect at once, with a code","Admin-Protokoll": "Admin log","Auswahl passend zum gewählten Modell.": "Choice to match the selected model.","Wikipedia direkt": "Wikipedia straight away","Wissensfragen wie „Was ist ein Quasar?“ beantwortet der Assistent aus dem Wikipedia-Artikel, ohne Websuche.": "Knowledge questions like “What is a quasar?” are answered from the Wikipedia article, without a web search.","Adresse der Wikipedia": "Wikipedia address","Leer = de.wikipedia.org, ohne Treffer dort en.wikipedia.org. Nur die Suchwörter verlassen den Spark.": "Empty = de.wikipedia.org, with no hit there en.wikipedia.org. Only the search words leave the Spark.","Rollen per Sprache": "Roles by voice","Profile speichern eigene Rollen und wechseln mit „Sei jetzt …“; das Panel schaltet, die Rolle ändert nur den Ton.": "Profiles save their own roles and switch with “Be … now”; the panel switches, the role only changes the tone.","Panel-Bereiche in der iPhone-App": "Panel areas in the iPhone app","Die App zeigt Teile des Panels selbst und öffnet jede Seite von Ich in der App. Gilt für jedes Profil mit gekoppeltem iPhone.": "The app shows parts of the panel itself and opens every page of Me inside the app. Applies to every profile with a paired iPhone.","Steckbrief und Tags": "Document card and tags","Das Sprachmodell notiert in Pausen Titel, Art, Absender, Frist und Schlagwörter jedes Dokuments; der Assistent sucht damit gezielter.": "In quiet minutes the language model notes title, kind, sender, deadline and keywords of each document; the assistant searches more precisely.","Größte PDF-Datei (MB)": "Largest PDF file (MB)","20 bis 300, Standard 100. Andere Dateiarten bis 20 MB. Große Scans brauchen beim Hochladen kurz etwa das Dreifache an Arbeitsspeicher.": "20 to 300, default 100. Other kinds of files up to 20 MB. Big scans briefly need about three times their size in memory while uploading.","Lange Dokumente nachts lesen": "Read long documents at night","Tagsüber nur kurze Dokumente (bis 10 Seiten) in Pausen, lange erst nach 30 Minuten Ruhe oder im Nachtfenster, dort bis 400 Seiten mehr.": "By day only short documents (up to 10 pages) in quiet moments, long ones only after 30 minutes of quiet or in the night window, there up to 400 more pages.","Nachtfenster": "Night window","bis": "to","Uhr-App „Spark“ per Einrichtungscode koppeln statt Adresse und Schlüssel abzutippen. Der Uhr-Schlüssel darf nur fragen.": "Pair the \"Spark\" watch app with a setup code instead of typing address and key. The watch key may only ask.","Android-App": "Android app","App „Spark“ als APK von dieser Seite: der Spark wie am Handy, dazu Mitteilungen und Teilen an Spark.": "App \"Spark\" as APK from this page: the Spark like on the phone, plus notes and sharing to Spark.","App jetzt holen": "Fetch the app now","Pebble-Uhr koppeln": "Pair the Pebble watch","Eigene Dokumente": "Own documents","Profilnamen, Speicher und Zahlen, nie Inhalte. Dokumentnamen nur, wenn jemand ein Dokument für alle freigegeben hat.": "Profile names, space and numbers, never contents. Document names only when someone shared a document for everyone.","Gemeinsame Dokumente": "Shared documents","Ein Profil gibt einzelne Dokumente „Für alle“ frei, die anderen Profile finden und öffnen sie. Gäste und unbekannte Stimmen nie.": "A profile shares single documents \"for everyone\", the other profiles find and open them. Never guests or unknown voices.","Vorrang für Sprache": "Speech first","Vorrang prüfen": "Check priority","Spracherkennung und Sprachausgabe gehen immer vor: Hintergrundarbeit wartet, solange gesprochen wird, und eine laufende Hintergrund-Anfrage an das Sprachmodell wird abgebrochen und später wiederholt. Der Test spricht einen Satz dreimal: alleine, während das Sprachmodell eine lange Antwort schreibt, und dasselbe mit Vorfahrt. Dauert etwa eine Minute.": "Speech recognition and speech output always come first: background work waits while someone speaks, and a running background request to the language model is cancelled and repeated later. The test speaks one sentence three times: alone, while the language model writes a long answer, and the same with priority. Takes about a minute.","Bilder und Scans lesen": "Read pictures and scans","Fotos und gescannte PDF-Seiten liest das Sprachmodell einmal in Gesprächspausen ab; danach findet die Dokumentensuche ihren Text.": "The language model reads photos and scanned PDF pages once in quiet moments; the document search then finds their text.","Bedeutungssuche": "Meaning search","Ein kleines Modell auf dem Prozessor findet auch Stellen mit anderen Worten („Auto“ findet „Kfz“); etwa 300 MB, nur bei Bedarf.": "A small model on the processor also finds passages in other words (\"car\" finds \"vehicle\"). About 300 MB of memory, only while needed.","Originale aufbewahren": "Keep originals","Die hochgeladene Datei bleibt auf dem Spark, lässt sich wieder öffnen und kommt in die Sicherung.": "The uploaded file stays on the Spark, can be opened again and goes into the backup.","Speicher pro Profil (MB)": "Space per profile (MB)","50 bis 5000, für alle Uploads eines Profils zusammen. Einzelnen Profilen gibst du unter Personen und Geräte beim Profil → Details → Platz für Uploads mehr oder weniger. Ist er voll, nimmt der Spark nichts Neues an; Originale nur, solange Platz ist.": "50 to 5000, for all uploads of a profile together. Under People and devices at the profile → Details → Space for uploads you give single profiles more or less. When it is full, the Spark takes nothing new; originals only while there is room.","PDF bis 100 MB (der Admin kann mehr erlauben); Word, Excel, PowerPoint, OpenDocument, Text, Markdown, HTML, CSV oder E-Mail (.eml) je bis 20 MB. Der Assistent sucht darin, wenn eine Frage dazu passt. Nur du kannst sie nutzen, außer du gibst ein Dokument „Für alle“ frei.": "PDF up to 100 MB (the admin may allow more); Word, Excel, PowerPoint, OpenDocument, text, Markdown, HTML, CSV or e-mail (.eml) up to 20 MB each. The assistant searches them when a question fits. Only you can use them, unless you share a document \"For everyone\".","Suchen": "Search","Schneller Antwortbeginn": "Faster answer start","Die Uhrzeit geht mit der Frage mit. So liest das Sprachmodell Anweisung, Werkzeuge und Verlauf aus seinem Zwischenspeicher.": "The time goes along with the question. The language model then reads instructions, tools and history from its cache.","Wirkt, wenn der Sprachmodell-Server Präfix-Caching nutzt (bei vLLM Standard). Ob es hilft, zeigt Zustand → Logs → Erweitert → Gespräch: pro Antwort steht dort, wie viele Tokens gelesen wurden und wie viele davon aus dem Zwischenspeicher kamen.": "Works when the language model server uses prefix caching (default in vLLM). Whether it helps shows under Status → Logs → Advanced → Conversation: each answer lists how many tokens were read and how many came from the cache.","Raum-Modus aus der Ferne starten": "Start room mode from afar","„Raummodus im Wohnzimmer an“ lässt einen eigenen Lautsprecher zuhören, nach einem „Ja“. Braucht Lautsprecher.": "\"Raummodus im Wohnzimmer an\" lets an own speaker listen, after a \"Ja\". Needs speakers.","Diagnose": "Diagnosis","Dienste": "Services","Änderungen": "Changes","In der Ausgabe suchen …": "Search the output …","Kopieren für Thread": "Copy for thread","Live": "Live","Hört gerade zu": "Listening right now","Alle beenden": "Stop all","Nur wo und bis wann, nie was gehört wurde.": "Only where and until when, never what was heard.","Raum-Modus für Home Assistant": "Room mode for Home Assistant","Profile dürfen einen Schlüssel anlegen, mit dem Home Assistant liest, wo zugehört wird, und es beenden kann.": "Profiles may make a key with which Home Assistant reads where it listens and can end it.","Eigene Wörter pro Gruppe": "Own words per group","Kommt eines dieser Wörter in der Frage vor, gehört sie zu dieser Gruppe. Eine Zeile pro Gruppe, die Namen stehen in der Tabelle unten. Nur ganze Wörter, höchstens 20 pro Gruppe. Die eingebauten Wörter bleiben immer.": "If one of these words is in the question, it belongs to this group. One line per group, the names are in the table below. Whole words only, at most 20 per group. The built-in words always stay.","Ausprobieren": "Try it","Regeln ansehen": "Show the rules","Gezielte Werkzeugwahl": "Targeted tool choice","Fragen, die keine Regel erkennt": "Questions no rule recognizes","Nachricht": "Message","Nachricht an andere": "Message to others","Empfänger": "Recipient","Nachricht an alle": "Message to everybody","Durchsagen auf Lautsprechern": "Announcements on speakers","Sprachnachrichten": "Voice messages","Bild": "Picture","Bilder erkennen": "Picture recognition","Profile hängen im Assistenten, in der iPhone-App oder über Telegram ein Foto an; das Sprachmodell sieht es sich selbst an.": "Profiles attach a photo in the assistant, the iPhone app or over Telegram; the language model looks at it itself.","Prüft einmal, ob das laufende Sprachmodell Bilder annimmt: Es bekommt ein Testbild mit einer Zahl.": "Checks once whether the running language model accepts pictures: it gets a test picture with a number.","Bilderkennung prüfen": "Check picture recognition","Spark-Update über die iPhone-App": "Spark update from the iPhone app","Ausgewählte Profile erfahren in der App von neuen geprüften Versionen und dürfen das Update dort starten.": "Chosen profiles learn about new tested versions in the app and may start the update there.","Wer was darf, legst nur du hier fest. Starten geht nur mit dem zweiten Anmeldeschritt des Profils: Face ID und ein frischer Code aus der Authenticator-App. Installiert werden nur Stände mit grünen GitHub-Tests.": "Only you decide here who may do what. Starting needs the profile's second login step: Face ID and a fresh code from the authenticator app. Only versions with green GitHub tests are installed.","Aufträge": "Jobs","„Recherchiere …, sag mir Bescheid“: Aufträge im Hintergrund, geplante Aufträge und eigene Abläufe, nur für freigeschaltete Profile.": "\"Research …, let me know\": background jobs, scheduled jobs and own routines, only for profiles that were allowed.","Dienste per MCP": "Services over MCP","Werkzeuge fremder Dienste (Paperless, Nextcloud …), jedes einzeln freigegeben.": "Tools of outside services (Paperless, Nextcloud …), each allowed one by one.","KI-Agenten: Hermes und OpenClaw": "AI agents: Hermes and OpenClaw","Ein Agent wie Hermes Agent (Nous Research) oder OpenClaw kann mit dieser Spark hören und sprechen: Spracherkennung und Sprachausgabe laufen hier, der Agent selbst läuft woanders. Er bekommt nur Audio und den Text zum Vorlesen, keinen Zugang zu Profilen, Gedächtnis oder Werkzeugen des Assistenten.": "An agent such as Hermes Agent (Nous Research) or OpenClaw can listen and speak with this Spark: speech recognition and speech output run here, the agent itself runs elsewhere. It only gets audio and the text to read out, no access to the assistant's profiles, memory or tools.","Ergänzen in": "Add to",", dann den Agenten neu starten.": ", then restart the agent.","In der OpenClaw-Konfiguration ergänzen. Den Schlüssel für die Spracherkennung als OpenAI-API-Key-Profil hinterlegen.": "Add to the OpenClaw configuration. Store the key for speech recognition as an OpenAI API key profile.","Läuft der Agent auf einem anderen Rechner, die LAN-IP der Spark nehmen. Ohne API-Schlüssel (Einstellungen → Sicherheit) kann jeder im Heimnetz die Sprachdienste nutzen. Den Agenten nicht auf dieser Spark installieren: Er führt selbst Befehle aus und käme so an Einstellungen und Schlüssel.": "If the agent runs on another computer, use the Spark's LAN IP. Without an API key (Settings → Security) anyone on the home network can use the speech services. Do not install the agent on this Spark: it runs commands itself and could reach settings and keys.","Eigene Stimme überhören": "Ignore my own voice","Hört ein Gerät die Antwort eines anderen Geräts (Lautsprecher, iPhone), nimmt der Assistent sie nicht als neue Frage.": "When a device hears another device's answer (speaker, iPhone), the assistant does not take it as a new question.","Was er überhört": "What it ignores","Sätze, die er gerade selbst gesagt hat": "Sentences it just said itself","dazu alles, solange ein anderes Gerät spricht (empfohlen)": "also everything while another device is speaking (recommended)","Stellt dem echten Sprachmodell 20 feste Fragen, die meisten in drei Formulierungen, und prüft Werkzeug und Antwort. Echte Daten werden dabei weder gelesen noch geändert.": "Asks the real language model 20 fixed questions, most of them in three wordings, and checks tool and answer. Real data is neither read nor changed.","Wie geprüft wird": "How it checks","Die Werkzeuge liefern vorbereitete Ergebnisse (Termine, Mails, Erinnerungen, Suche, Gedächtnis, „weiß ich nicht“-Fälle). Geprüft wird, ob das Modell das richtige Werkzeug nimmt und was du nach der Antwort-Prüfung hörst. Ein Fehlschlag läuft einmal neu; der Verlauf zeigt neu kaputte und wackelnde Fragen. Läuft nach jedem Update von selbst, dauert zwei bis vier Minuten.": "The tools return prepared results (appointments, mail, reminders, search, memory, “don't know” cases). It checks whether the model picks the right tool and what you hear after the answer check. A failure runs once more; the history shows newly broken and wobbly questions. Runs by itself after every update and takes two to four minutes.","Push an die iPhone-App": "Push to the iPhone app","Meldungen kommen auch bei geschlossener App. Apple sieht nur „Neue Nachricht“, den Text holt die App vom Spark.": "Notifications arrive with the app closed too. Apple only sees \"New message\"; the app fetches the text from the Spark.","Schlüssel von developer.apple.com → Certificates, IDs & Profiles → Keys → „+“ → Apple Push Notifications service (APNs). Die .p8-Datei gibt es nur einmal zum Herunterladen.": "Key from developer.apple.com → Certificates, IDs & Profiles → Keys → \"+\" → Apple Push Notifications service (APNs). The .p8 file can be downloaded only once.","Schlüsseldatei (.p8)": "Key file (.p8)","Bundle-ID der App": "The app's bundle ID","Art der App": "Kind of app","Entwicklung (direkt aus Xcode)": "Development (straight from Xcode)","Produktion (TestFlight, App Store)": "Production (TestFlight, App Store)","Schlüssel löschen": "Delete key","Gesicht des Assistenten": "Assistant's face","Gesicht zeigt, was es tut": "Face shows what it does","Zeichen beim Suchen, Kalender, Mails, Licht und Merken; zwinkert nach Erledigtem, schaut ratlos bei Fehlern, schläft nach 5 Minuten Ruhe.": "Signs while searching, for calendar, mail, lights and memory; winks when something is done, looks puzzled on errors, sleeps after 5 quiet minutes.","Roboter": "Robot","Comic": "Comic","Comic (Frau)": "Comic (woman)","iPhone-App": "iPhone app","Profile koppeln die App „Spark“ auf ihrem iPhone: fragen und hören mit der Spark-Stimme, auch per Siri.": "Profiles pair the \"Spark\" app on their iPhone: ask and listen in the Spark voice, also through Siri.","Braucht dich": "Needs you","Zustand wird geladen …": "Loading status …","Zustand": "Status","Personen und Geräte": "People and devices","Spark verwalten": "Manage Spark","Ich": "Me","Verwalten": "Manage","Diagnose-Filter": "Diagnostic filters","Lautsprecher (esp32)": "Speakers (esp32)","Fehler": "Errors","letzte 10 min": "last 10 min","letzte Stunde": "last hour","letzte 2 Stunden": "last 2 hours","letzte 12 Stunden": "last 12 hours","letzte 24 Stunden": "last 24 hours","30 Zeilen": "30 lines","100 Zeilen": "100 lines","300 Zeilen": "300 lines","1000 Zeilen": "1000 lines","Eigener Gesprächsstil": "Own conversation style","Rückfrage ohne Weckwort": "Follow-up without wake word","Nach der Antwort auf eine gesprochene Frage hört der Assistent ein paar Sekunden weiter zu; jedes Profil wählt die Dauer.": "After answering a spoken question the assistant keeps listening for a few seconds; each profile picks the time.","Ganzen Prompt ansehen": "Show the whole prompt","Erweitert": "Advanced","Wie viel vom bisherigen Gespräch das Modell mitbekommt, 4000 bis 64000. 24000 sind etwa 8000 Tokens. Mehr braucht ein Modell mit großem Kontextfenster und mehr Speicher.": "How much of the conversation so far the model gets, 4000 to 64000. 24000 is about 8000 tokens. More needs a model with a large context window and more memory.","Websuchen pro Antwort": "Web searches per answer","1 bis 3. Mehr ist gründlicher, aber langsamer.": "1 to 3. More is more thorough, but slower.","60 bis 600. Kürzer lohnt sich, wenn das Modell auf einem anderen Rechner läuft und dort hängen kann.": "60 to 600. Shorter is worth it when the model runs on another computer and can hang there.","0 = Standard des Servers. Sonst 0.05 bis 1; kleiner = vorsichtigere Wortwahl.": "0 = the server's default. Otherwise 0.05 to 1; smaller = more careful word choice.","0 = Standard des Servers. Bis 2; hilft, wenn das Modell sich wiederholt (Qwen empfiehlt dann etwa 1).": "0 = the server's default. Up to 2; helps when the model repeats itself (Qwen then recommends about 1).","Eigene Stichwörter für die Werkzeugpflicht": "Own keywords that require a tool","Kommt eines dieser Wörter in der Frage vor, muss das Modell zuerst das Werkzeug benutzen. Eine Zeile pro Werkzeug: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Nur ganze Wörter, höchstens 20 pro Werkzeug. Die eingebauten Wörter bleiben immer.": "If one of these words is in the question, the model must use the tool first. One line per tool: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Whole words only, at most 20 per tool. The built-in words always stay.","Aus Korrekturen lernen": "Learning from corrections","Fragen aus Korrekturen": "Questions from corrections","Profile haben sie nach einer Korrektur übergeben. Sie laufen bei jedem Test mit; jedes Werkzeug findet dabei nichts, das Modell darf also nichts erfinden.": "Profiles handed them over after a correction. They run with every test; every tool finds nothing, so the model must not make anything up.","Temperatur bei der Werkzeugwahl": "Temperature when choosing tools","Gilt, solange das Modell entscheidet, welches Werkzeug es nimmt; danach gilt die Temperatur oben. 0.1 empfohlen.": "Used while the model decides which tool to take; after that the temperature above applies. 0.1 recommended.","Antwort-Prüfung": "Answer check","Wiederholung weggelassen": "Repetition left out","Heimnetz": "Home network","Aus: Kalender, Adressbücher, Aufgaben und Postfächer der Profile dürfen nur auf Adressen im Internet liegen (z. B. iCloud, GMX). An: auch Server im Heimnetz (z. B. ein NAS). Home Assistant darf immer im Heimnetz liegen. Die Dienste des Sparks selbst und Adressen wie 169.254.x sind nie erreichbar.": "Off: profile calendars, address books, task lists and mailboxes may only be on internet addresses (e.g. iCloud, GMX). On: also servers in the home network (e.g. a NAS). Home Assistant may always be in the home network. The Spark's own services and addresses like 169.254.x are never reachable.","Admin-Anmeldung": "Admin login","Nur von diesen Adressen wird die weitergereichte Absender-Adresse (X-Forwarded-For) geglaubt, z. B. 192.168.1.10. Leer = nur ein Proxy auf dem Spark selbst. Eintragen, wenn das Panel hinter einem Proxy im Heimnetz hängt: sonst teilen sich alle, die über den Proxy kommen, eine Adresse für die Sperre nach falschen Passwörtern.": "Only from these addresses is the forwarded sender address (X-Forwarded-For) believed, e.g. 192.168.1.10. Empty = only a proxy on the Spark itself. Enter it when the panel sits behind a proxy in the home network: otherwise everyone coming through the proxy shares one address for the lock after wrong passwords.","Adresse von Home Assistant übernehmen": "Take the Home Assistant address","Bus und Bahn": "Bus and train","Adresse des Fahrplandienstes": "Timetable service address","Leer = v6.db.transport.rest. Auch ein eigener db-rest oder ein regionaler Dienst (z. B. v6.vbb.transport.rest).": "Empty = v6.db.transport.rest. Also an own db-rest or a regional service (e.g. v6.vbb.transport.rest).","Home Assistant Assist (Wyoming)": "Home Assistant Assist (Wyoming)","Erlaubte Adressen": "Allowed addresses","Die Adresse deines Home Assistant, mehrere mit Komma, auch Netze wie 192.168.1.0/24. Leer = niemand.": "Your Home Assistant's address, several with commas, also networks like 192.168.1.0/24. Empty = nobody.","Listen für Einkauf und Aufgaben": "Lists for shopping and tasks","Listen": "Lists","Telegram": "Telegram","Bot-Token von @BotFather (Anleitung über den Knopf „Anleitung“).": "Bot token from @BotFather (see the \"Guide\" button).","Token löschen": "Delete token","Wetter": "Weather","Kontakte": "Contacts","Pakete": "Parcels","E-Mail": "E-mail","Adresse der Vorhersage": "Forecast address","Adresse der Ortssuche": "Place search address","Nur ändern, wenn du Open-Meteo selbst betreibst.": "Only change this if you run Open-Meteo yourself.","Alle Anleitungen": "All guides","Zu jedem Dienst, den man einschalten kann: was er kann, was du brauchst, wie du ihn einrichtest und benutzt, was das Haus verlässt und wie du ihn wieder ausschaltest. Dieselbe Anleitung steht auch neben dem Schalter unter Funktionen und im Ich.": "For every service you can switch on: what it does, what you need, how to set it up and use it, what leaves the house and how to switch it off again. The same guide is also next to its switch under Features and in the Me.","Postfach aufräumen": "Inbox tidying","Alle Einstellungen": "All settings","Adressen des Reverse-Proxys": "Reverse proxy addresses","Nur von diesen Adressen wird die weitergereichte Absender-Adresse (X-Forwarded-For) geglaubt, z. B. 192.168.1.10. Leer = von jedem Gerät im Heimnetz. Eintragen, wenn das Panel hinter einem Proxy hängt: dann kann kein anderes Gerät im Netz die Sperre nach falschen Passwörtern umgehen.": "The forwarded sender address (X-Forwarded-For) is only believed from these addresses, e.g. 192.168.1.10. Empty = from any device in the LAN. Fill in when the panel sits behind a proxy: then no other device in the network can get around the lockout after wrong passwords.","Raum-Modus": "Room mode","Fernsehstimmen überhören": "Ignore TV voices","Jedes Gerät kann wählen, nur bekannten Stimmen zuzuhören (Sprechererkennung), z. B. solange der Fernseher läuft (Home Assistant).": "Each device can choose to listen only to known voices (speaker identification), e.g. while the TV is on (Home Assistant).","Raum": "Room","Erkennung": "Recognizer","Qwen3-ASR (Grafikkarte)": "Qwen3-ASR (GPU)","Parakeet Deutsch (Prozessor)": "Parakeet German (CPU)","Parakeet (primeline, deutsch nachtrainiert) läuft auf dem Prozessor, braucht etwa 1 GiB statt mehrerer GiB und ist sehr schnell, kennt aber keinen Kontext und versteht vor allem Deutsch. Beim Umschalten startet die Spracherkennung neu; beim ersten Mal lädt Parakeet etwa 640 MB herunter.": "Parakeet (primeline, fine-tuned for German) runs on the CPU, needs about 1 GiB instead of several and is very fast, but ignores the context and mainly understands German. Switching restarts speech recognition; the first time Parakeet downloads about 640 MB.","Von selbst melden": "Speak up by itself","Aufräumen vorschlagen": "Propose cleanup","Einmal pro Woche schlägt der Assistent vor, doppelte oder überholte Einträge zusammenzufassen. Es ändert sich erst etwas, wenn du hier bestätigst.": "Once a week the assistant proposes merging duplicate or outdated entries. Nothing changes until you confirm here.","Qualitätstest": "Quality test","Stellt dem echten Sprachmodell 20 feste Fragen, die meisten zusätzlich in zwei anderen Formulierungen, mit vorbereiteten Werkzeug-Ergebnissen (Termine, Mails, Erinnerungen, Suche, Gedächtnis, „weiß ich nicht“-Fälle). Geprüft wird, ob es das richtige Werkzeug nimmt und was du nach der Antwort-Prüfung hörst. Ein Fehlschlag läuft einmal neu; der Verlauf zeigt neu kaputte und wackelnde Fragen. Echte Daten werden dabei weder gelesen noch geändert. Läuft nach jedem Update von selbst, dauert zwei bis vier Minuten.": "Asks the real language model 20 fixed questions, most of them also in two other wordings, with prepared tool results (appointments, mail, reminders, search, memory, \"I don't know\" cases). It checks that the model picks the right tool and what you hear after the answer check. A failure runs once more; the history shows newly broken and wobbly questions. No real data is read or changed. Runs by itself after every update and takes two to four minutes.","Tagesbriefing als Mitteilung": "Daily briefing as a notification","Aus": "Off","Jeden Morgen zu dieser Uhrzeit: Termine, Erinnerungen, ungelesene Mails und deine Themen, kurz zusammengefasst. Kommt auf alle Geräte mit eingeschalteten Mitteilungen und steht danach auch im Verlauf.": "Every morning at this time: appointments, reminders, unread mail and your topics in short. Goes to every device with notifications on and is kept in the history too.","Neu laden": "Reload","Protokoll leeren": "Clear log","E-Mail lesen": "Read e-mail","Frag „Hab ich neue Mails?“, „Was schreibt Anna?“ oder „Lies mir die Mail von der Telekom vor“. Der Assistent liest nur den Posteingang der letzten 30 Tage und ändert nichts: keine Mail wird gesendet, gelöscht oder als gelesen markiert. Das Passwort bleibt verschlüsselt auf dem Spark.": "Ask \"Any new mail?\", \"What does Anna write?\" or \"Read me the mail from the bank\". The assistant only reads the inbox of the last 30 days and changes nothing: no mail is sent, deleted or marked as read. The password stays encrypted on the Spark.","Postfach hinzufügen": "Add mailbox","anderer IMAP-Server": "other IMAP server","z. B. Privat": "e.g. Personal","Postfächer prüfen": "Check mailboxes","Codewort für Änderungen": "Code word for changes","Ist eines gesetzt, schaltet der Assistent erst, wenn du es in derselben Nachricht sagst, z. B. „Licht aus, Codewort Sonnenblume“. Abfragen gehen ohne. Nimm ein Wort, das die Spracherkennung sicher versteht. Leer speichern entfernt es.": "When one is set, the assistant switches only when you say it in the same message, e.g. \"Lights off, code word sunflower\". Questions work without it. Pick a word the speech recognition gets right. Saving it empty removes it.","Funktionen": "Features","Nutzer": "Users","Profile": "Profiles","Übersicht": "Overview","Websuche": "Web search","Was der Assistent können soll. Tippe auf eine Funktion für Erklärung und Einstellungen.": "What the assistant should be able to do. Tap a feature for its explanation and settings.","Zugang zum Assistenten": "Access to the assistant","Unter": "Under","beim eigenen Profil ein Gerät „Pebble“ anlegen und den Schlüssel kopieren.": "add a device \"Pebble\" to your own profile and copy the key.","Über deine eigene SearXNG-Instanz. Am besten erlaubt sie das JSON-Format (settings.yml: search.formats: [html, json]); sonst liest das Panel die normale Ergebnisseite.": "Through your own SearXNG instance. Best let it allow the JSON format (settings.yml: search.formats: [html, json]); otherwise the panel reads the normal results page.","Wie warm ist es im Wohnzimmer?": "How warm is it in the living room?","z. B. Arbeit": "e.g. Work","Deutsch": "German","Der Assistent ist nur für Profile freigegeben. Bitte melde dich mit Name und PIN an.": "The assistant is open to profiles only. Please sign in with name and PIN.","Verbinde dein Home Assistant, dann sagst du „Mach das Licht im Wohnzimmer an“ oder „Wie warm ist es im Bad?“. Nur dein Profil kann es nutzen. Der Assistent sieht alle Geräte, Zonen und Personen, die dein Home-Assistant-Benutzer sehen darf; Schlösser, Alarmanlage und Updates schaltet er nie. Der Token bleibt auf dem Spark.": "Connect your Home Assistant, then say \"Turn on the living room light\" or \"How warm is it in the bathroom?\". Only your profile can use it. The assistant sees every device, zone and person your Home Assistant user may see; it never switches locks, alarm systems or updates. The token stays on the Spark.","Langlebiger Zugriffstoken": "Long-lived access token","In Home Assistant: dein Profil → Sicherheit → Langlebige Zugriffstoken → Token erstellen. Am besten für einen eigenen Benutzer ohne Admin-Rechte.": "In Home Assistant: your profile → Security → Long-lived access tokens → Create token. Best for a separate user without admin rights.","Zertifikat nicht prüfen (selbst signiertes HTTPS)": "Don't verify the certificate (self-signed HTTPS)","Assist-Agent (leer = Standard)": "Assist agent (empty = default)","Prüfen und speichern": "Check and save","Trennen": "Disconnect","Frühere Gespräche": "Earlier conversations","Update läuft": "Update running","Starte …": "Starting …","Bitte warten. Bis das Update fertig ist, sind Änderungen gesperrt. Die Seite lädt danach von selbst neu.": "Please wait. Changes are locked until the update has finished. The page then reloads by itself.","Anbieter": "Provider","anderer CalDAV-Server": "other CalDAV server","Abo-Link (webcal://, webcals://, .ics, Google)": "Subscription link (webcal://, webcals://, .ics, Google)","Spark-Kalender (ohne Konto, nur auf dem Spark)": "Spark calendar (no account, only on the Spark)","Kalender-Server für Kalender-Apps": "Calendar server for calendar apps","Die Spark-Kalender eines Profils im Kalender des iPhone (CalDAV), mit einem App-Passwort je Profil, im Heimnetz und über den Proxy.": "A profile's Spark calendars in the iPhone's calendar (CalDAV), with an app password per profile, at home and through the proxy.","„Guten Morgen“ oder „Was steht heute an?“: Der Assistent liest Termine, Erinnerungen und deine Themen vor. Du kannst mehrere Kalender verbinden. „Trag Zahnarzt Dienstag 10 Uhr ein“ legt einen Termin im ersten CalDAV-Kalender an, aber erst, wenn du den Vorschlag mit Ja bestätigst; Abo-Links bleiben nur lesend.": "\"Good morning\" or \"What's on today?\": the assistant reads out appointments, reminders and your topics. You can connect several calendars. \"Put dentist on Tuesday 10 am\" adds an appointment to the first CalDAV calendar, but only after you confirm the proposal with yes; subscription links stay read only.","Gedächtnis": "Memory","Dokumente": "Documents","Kalender": "Calendar","Kalender hinzufügen": "Add calendar","Adresse": "Address","Prüfen und hinzufügen": "Check and add","Themen fürs Briefing (höchstens drei)": "Briefing topics (at most three)","Nächste Termine zeigen": "Show next appointments","Zurück zum Gesicht": "Back to the face","Kalender und Tagesbriefing": "Calendar and daily briefing","Kalender-Adresse": "Calendar address","Benutzer": "User","Passwort": "Password","sehr schnell: erster Ton am frühesten, kann bei voller GPU stocken": "very fast: earliest first audio, may stutter when the GPU is busy","Nochmal vorlesen": "Read again","Start der Sprachausgabe": "Speech output start","schnell": "fast","ausgewogen (empfohlen)": "balanced (recommended)","ruhig: erster Ton etwas später, läuft sehr gleichmäßig an": "calm: first audio a little later, starts very smoothly","sehr ruhig: erster Ton spürbar später": "very calm: first audio noticeably later","automatisch: vllm-omni entscheidet nach Auslastung": "automatic: vllm-omni decides by load","Die Sprachausgabe liefert den Ton in Blöcken. Ein kleiner erster Block ist früher hörbar, ein größerer läuft gleichmäßiger an; danach werden die Blöcke stufenweise größer, damit die Wiedergabe nicht abreißt. Eine Änderung startet die Sprachausgabe neu, das dauert ein paar Minuten.": "Speech output delivers audio in blocks. A small first block is audible sooner, a larger one starts more smoothly; after that the blocks grow step by step so playback does not break off. Changing it restarts speech output, which takes a few minutes.","Weitere Aufnahmen": "More recordings","Sprechererkennung": "Speaker identification","Strenge der Sprechererkennung": "Strictness of speaker identification","locker (erkennt öfter, verwechselt eher)": "loose (recognizes more often, mixes up more easily)","normal": "normal","streng (verwechselt kaum, erkennt seltener)": "strict (hardly mixes up, recognizes less often)","Meine Stimme": "My voice","Lies drei kurze Sätze vor. Danach erkennt der Assistent dich an der Stimme, auch an anderen Geräten, und antwortet mit deinem Gedächtnis, deinen Dokumenten und Einstellungen.": "Read three short sentences aloud. Then the assistant recognizes you by your voice, on other devices too, and answers with your memory, documents and settings.","Stimme einlernen": "Enroll voice","Stimme löschen": "Delete voice","Die Sprachausgabe kam nicht schnell genug nach": "Speech output fell behind","Timer und Erinnerungen": "Timers and reminders","Neues Gespräch": "New conversation","Gesprächs-Einstellungen": "Conversation settings","Hell / Dunkel": "Light / dark","Abmelden": "Log out","Meine Dokumente": "My documents","PDF, Word, Text, Markdown, HTML oder CSV, je bis 20 MB. Der Assistent sucht darin, wenn eine Frage dazu passt. Nur du kannst sie nutzen.": "PDF, Word, text, Markdown, HTML or CSV, up to 20 MB each. The assistant searches them when a question fits. Only you can use them.","0 bis 5; mehr ist genauer, aber langsamer.": "0 to 5; more is more accurate, but slower.","1 bis 10.": "1 to 10.","1.7B erkennt genauer, braucht aber mehr Speicher.": "1.7B recognizes more accurately but needs more memory.","Adresse deiner SearXNG-Instanz": "Address of your SearXNG instance","Anteil am ganzen 128-GB-Pool, z. B. 0.04 ≈ 4,8 GiB.": "Share of the whole 128 GB pool, e.g. 0.04 ≈ 4.8 GiB.","Anteil am ganzen 128-GB-Pool; 1.7B: 0.06 ≈ 7,2 GiB, 0.6B: 0.035 ≈ 4,2 GiB.": "Share of the whole 128 GB pool; 1.7B: 0.06 ≈ 7.2 GiB, 0.6B: 0.035 ≈ 4.2 GiB.","Assistent": "Assistant","Assistent ohne Passwort": "Assistant without password","Ausrufezeichen werden zu Punkten, „Oh“, „Wow“, „Hm“ am Satzanfang fallen weg.": "Exclamation marks become full stops, \"Oh\", \"Wow\", \"Hm\" at the start of a sentence are dropped.","Aussprache": "Pronunciation","Bei qwen38 steht er in ~/.config/qwen38/api-key; das Update übernimmt ihn automatisch.": "With qwen38 it is in ~/.config/qwen38/api-key; the update imports it automatically.","DGX OS beendet Prozesse ab etwa 8 GiB freiem Speicher.": "DGX OS kills processes below about 8 GiB of free memory.","Das Mikrofon braucht https; 0 = aus.": "The microphone needs https; 0 = off.","Das Modell kennt sie sonst nicht.": "The model does not know them otherwise.","Datum und Uhrzeit mitgeben": "Pass date and time","Ein Modell wird nicht geladen, wenn danach weniger als die Reserve frei bliebe.": "A model is not loaded if less than the reserve would stay free.","Eine feste Sprache erkennt kurze Sätze besser als „auto“.": "A fixed language recognizes short sentences better than \"auto\".","Emojis, Markdown, „haha“ und *lacht* entfernen.": "Remove emojis, markdown, \"haha\" and *laughs*.","Feste Zahl = gleiche Stimmführung über alle Sätze; -1 = zufällig.": "Fixed number = same delivery across sentences; -1 = random.","Gelten für Gäste und für Profile, die selbst nichts geändert haben.": "Apply to guests and to profiles that changed nothing themselves.","Genauer, aber die Antwort beginnt deutlich später.": "More accurate, but the answer starts much later.","Gilt, wenn eine Anfrage keine eigene Anweisung mitbringt.": "Used when a request brings no instruction of its own.","In Schritten; 4096 ≈ 5 Min. Audio, kleiner = weniger Speicher.": "In steps; 4096 ≈ 5 min of audio, smaller = less memory.","Kleiner = ruhiger und gleichmäßiger, größer = lebendiger; Qwen-Standard 0.9.": "Lower = calmer and steadier, higher = livelier; Qwen default 0.9.","Kleiner = weniger Ausreißer; Qwen-Standard 1.0.": "Lower = fewer outliers; Qwen default 1.0.","Kontext": "Context","Leer = das erste, das der Server meldet.": "Empty = the first one the server lists.","Lädt zusätzlich den Forced Aligner (~2 GiB); nur für Untertitel und Ähnliches nötig.": "Also loads the forced aligner (~2 GiB); only needed for subtitles and the like.","Max. Länge pro Anfrage": "Max. length per request","Mindestens 10 Zeichen.": "At least 10 characters.","Neues Passwort": "New password","OpenAI-kompatibel. Das eigene Sprachmodell trägt „modelle llm uebernehmen“ selbst ein; qwen38: http://127.0.0.1:30001/v1": "OpenAI-compatible. The own language model is entered by „modelle llm uebernehmen“ itself; qwen38: http://127.0.0.1:30001/v1","Panel-Port": "Panel port","Ruhig sprechen": "Speak calmly","Seiten ganz lesen": "Pages read in full","Sicherheit": "Security","Speicheranteil Talker": "Memory share talker","Speichern": "Save","Speicherschutz an": "Memory guard on","Sprachausgabe": "Speech output","Spracherkennung": "Speech recognition","Sprechstil": "Speaking style","Temperatur": "Temperature","Text bereinigen": "Clean text","Treffer pro Suche": "Results per search","VoiceDesign zusätzlich bereitstellen": "Also serve VoiceDesign","Vorgaben": "Defaults","Vorher nachdenken": "Think first","Wirkt nach einem Neustart des Panels.": "Takes effect after restarting the panel.","Wissen": "Knowledge","Zeitstempel": "Timestamps","Zweite Engine, braucht den gleichen Speicher noch einmal.": "Second engine, needs the same memory again.","Ältere Einträge werden automatisch gelöscht.": "Older entries are deleted automatically.","Ports": "Ports","HTTPS-Port": "HTTPS port","„Hey Spark“": "\"Hey Spark\"","Freihändig": "Hands-free","Auf Vorgaben zurücksetzen": "Reset to defaults","Dauerhaft lauschen, das Wort startet das Gespräch (Bildschirm bleibt an)": "Keep listening, the phrase starts the conversation (screen stays on)","Nach der Antwort automatisch wieder zuhören": "Listen again after each answer","PIN (mind. 4 Zeichen)": "PIN (at least 4 characters)","z. B. Lautsprecher Küche": "e.g. kitchen speaker","Gast": "Guest","Profil": "Profile","Jedes Profil hat ein eigenes Gedächtnis und eigene Gespräche. Ein Browser meldet sich im Gespräch-Reiter mit Name und PIN an; was ein Profil weiß, sieht kein anderes und kein Gast.": "Every profile has its own memory and conversations. A browser logs in on the Talk tab with name and PIN; what one profile knows, no other profile and no guest can see.","Neues Profil": "New profile","Anlegen": "Create","Geräte": "Devices","Eigene Programme und Kurzbefehle bekommen hier einen Geräteschlüssel, das Profil wählst du in der Liste. iPhone-App, Lautsprecher, Pebble-Uhr und Home Assistant richtet jedes Profil selbst unter Ich ein: Sie bleiben fest bei diesem Profil und lassen sich hier nur löschen. Der Schlüssel geht im Header": "Your own programs and shortcuts get a device key here; pick the profile in the list. The iPhone app, speakers, Pebble watch and Home Assistant are set up by each profile itself under Me: they stay with that profile and can only be deleted here. The key goes in the header","an": "to","Neues Gerät": "New device","Profil wählen": "Choose profile","Angemeldet merkt sich der Assistent Dinge nur für dich, und deine Gespräche bleiben in deinem Profil.": "Logged in, the assistant remembers things only for you, and your conversations stay in your profile.","Name": "Name","PIN": "PIN","Alles vergessen": "Forget everything","Schließen": "Close","lauscht auf „Hey Spark“": "listening for \"Hey Spark\"","Websuche (SearXNG)": "Web search (SearXNG)","Adresse deiner SearXNG-Instanz (z. B. http://192.168.1.20:8080; JSON muss in settings.yml unter search.formats erlaubt sein)": "Address of your SearXNG instance (e.g. http://192.168.1.20:8080; JSON must be allowed in settings.yml under search.formats)","Treffer pro Suche (1–10)": "Results per search (1–10)","Davon Seiten ganz lesen (0–5; mehr = genauer, aber langsamer)": "Pages read in full (0–5; more = more accurate, but slower)","Verbindung testen": "Test connection","Dieses Gespräch löschen": "Delete this conversation","Exportieren und importieren": "Export and import","Alle exportieren": "Export all","gleicher Name: beide behalten": "same name: keep both","gleicher Name: ersetzen": "same name: replace","gleicher Name: überspringen": "same name: skip","Idee: Dominik Bornhäußer": "Idea: Dominik Bornhäußer","Autoscroll (ans Ende springen, alle 3 s neu laden)": "Autoscroll (jump to the end, reload every 3 s)","Einstellungen": "Settings","Anmelden": "Log in","Abbrechen": "Cancel","Panel-Passwort": "Panel password","Aktuelles Passwort": "Current password","Neues Passwort (mindestens 10 Zeichen)": "New password (at least 10 characters)","Passwort ändern": "Change password","Sprache der Stimme:": "Language of the voice:","Mit dem Mikrofon aufnehmen": "Record with the microphone","Das Mikrofon geht nur über https:": "The microphone only works over https:","Lies diesen Text ruhig und deutlich vor, so wie die Stimme später klingen soll (etwa 10 Sekunden):": "Read this text calmly and clearly, the way the voice should sound later (about 10 seconds):","Aufnahme starten": "Start recording","… oder eine Audiodatei hochladen (wav, mp3, m4a, …)": "… or upload an audio file (wav, mp3, m4a, …)","Bereit.": "Ready.","Sag etwas oder tippe unten eine Frage.": "Say something or type a question below.","Gespräch öffnen": "Open conversation","Neu": "New","Leertaste, „Sprechen“ oder ein Klick aufs Gesicht: zuhören bzw. die laufende Antwort unterbrechen.": "Space bar, \"Speak\" or a click on the face: listen, or interrupt the running answer.","Speech auf DGX Spark": "Speech on DGX Spark","Konfiguration": "Configuration","Testen": "Test","Stimmen": "Voices","Einbinden": "Integrate","GPU-Auslastung": "GPU load","Unified Memory frei": "Unified memory free","GPU-Temperatur / Leistung": "GPU temperature / power","Speech-Dienste": "Speech services","Dienst": "Service","Modell": "Model","Anfragen": "Requests","Ø Latenz": "Avg latency","Ø erster Ton": "Avg first audio","Speicher (Torch)": "Memory (Torch)","dgx-spark-qwen38 auf dieser Box": "dgx-spark-qwen38 on this box","Speicheranteil": "Memory share","Keine qwen38-Units gefunden.": "No qwen38 units found.","GPU-Prozesse": "GPU processes","Prozess": "Process","Speicher": "Memory","aktiviert": "enabled","Standardsprache": "Default language","Speicheranteil (Anteil am ganzen 128-GB-Pool, 1.7B: 0.06 ≈ 7,2 GiB, 0.6B: 0.035 ≈ 4,2 GiB)": "Memory share (of the whole 128 GB pool; 1.7B: 0.06 ≈ 7.2 GiB, 0.6B: 0.035 ≈ 4.2 GiB)","Max. gleichzeitige Anfragen": "Max. concurrent requests","Max. Batchgröße": "Max. batch size","Max. neue Tokens": "Max. new tokens","Zeitstempel (lädt zusätzlich den Forced Aligner, ~2 GiB)": "Timestamps (also loads the forced aligner, ~2 GiB)","Datentyp": "Data type","Sprachausgabe (TTS)": "Speech output (TTS)","Speicheranteil Talker (Anteil am ganzen 128-GB-Pool, z. B. 0.04 ≈ 4,8 GiB)": "Memory share talker (of the whole 128 GB pool, e.g. 0.04 ≈ 4.8 GiB)","Speicheranteil Code2Wav": "Memory share code2wav","Max. Länge pro Anfrage in Schritten (4096 ≈ 5 Min. Audio; kleiner = weniger Speicher)": "Max. length per request in steps (4096 ≈ 5 min of audio; smaller = less memory)","VoiceDesign-Modell": "VoiceDesign model","Standardstimme": "Default voice","z. B. Ruhig und freundlich, eher langsam, wie eine Hörbuchsprecherin.": "e.g. Calm and friendly, rather slow, like an audiobook narrator.","Temperatur (kleiner = ruhiger und gleichmäßiger, größer = lebendiger; Qwen-Standard 0.9)": "Temperature (lower = calmer and steadier, higher = livelier; Qwen default 0.9)","top_p (kleiner = weniger Ausreißer; Qwen-Standard 1.0)": "top_p (lower = fewer outliers; Qwen default 1.0)","Seed (feste Zahl = gleiche Stimmführung über alle Sätze; -1 = zufällig)": "Seed (fixed number = same delivery across sentences; -1 = random)","Speicherschutz": "Memory guard","Reserve in GiB (DGX OS earlyoom greift bei ~8 GiB)": "Reserve in GiB (DGX OS earlyoom kicks in at ~8 GiB)","API-Schlüssel": "API key","Erzeugen": "Generate","Spracherkennung testen": "Test speech recognition","Audiodatei (wav, mp3, flac, …)": "Audio file (wav, mp3, flac, …)","Sprache": "Language","Transkribieren": "Transcribe","Sprachausgabe testen": "Test speech output","Stimme": "Voice","Anweisung (optional; bei VoiceDesign die Stimmbeschreibung)": "Instruction (optional; with VoiceDesign the voice description)","z. B. Begeistert und etwas schneller.": "e.g. Excited and a bit faster.","Modus": "Mode","Standard (konfiguriertes Modell)": "Default (configured model)","gestreamt (Ton spielt, während er erzeugt wird)": "streamed (audio plays while it is generated)","Sprechen": "Speak","Nur mit einem": "Only works with a","-Modell wirksam. 5–15 Sekunden saubere Sprache; der Text sollte genau dem Gesprochenen entsprechen (leer lassen geht, klont dann schlechter).": " model. 5–15 seconds of clean speech; the text should match what is said exactly (empty works, but clones worse).","z. B. dominik": "e.g. dominik","Referenz-Audio": "Reference audio","Transkript der Referenz": "Transcript of the reference","Hinzufügen": "Add","Vorhandene Stimmen": "Existing voices","Endpunkte": "Endpoints","Beide Dienste sprechen die OpenAI-Audio-API. Jede App, die dort eine eigene „Base URL“ erlaubt, kann sie nutzen.": "Both services speak the OpenAI audio API. Any app that lets you set your own \"Base URL\" there can use them.","Admin-Panel → Einstellungen → Audio": "Admin Panel → Settings → Audio","Spracherkennung (STT)": "Speech recognition (STT)","Läuft Open WebUI in Docker auf derselben Spark, statt der IP": "If Open WebUI runs in Docker on the same Spark, use","nehmen (Container mit": "instead of the IP (start the container with","starten) oder die LAN-IP der Spark.": ") or the Spark's LAN IP.","Andere Apps": "Other apps","Überall dort, wo „OpenAI-kompatibel“ für Speech-to-Text oder Text-to-Speech auswählbar ist (z. B. LibreChat, AnythingLLM, SillyTavern, Home Assistant mit OpenAI-TTS/STT-Integration, n8n): Base URL und Schlüssel wie links eintragen. Modellname ist beliebig. Unbekannte OpenAI-Stimmen wie „alloy“ werden auf die Standardstimme umgeleitet.": "Wherever \"OpenAI-compatible\" can be chosen for speech-to-text or text-to-speech (e.g. LibreChat, AnythingLLM, SillyTavern, Home Assistant with the OpenAI TTS/STT integration, n8n): enter the base URL and key as on the left. The model name can be anything. Unknown OpenAI voices like \"alloy\" fall back to the default voice.","Formate": "Formats","TTS: mp3 (Standard), wav, flac, opus, pcm. Gestreamt mit": "TTS: mp3 (default), wav, flac, opus, pcm. Streamed with","mit base64-PCM (16 bit, mono, 24 kHz), am Ende": "with base64 PCM (16 bit, mono, 24 kHz), finally",". Pro Anfrage überschreibbar:": ". Per request you can override",". Sprechstil pro Anfrage mit": ". Speaking style per request with","(ohne Angabe gilt die Standard-Anweisung aus der Konfiguration; nur 1.7B-Modelle werten das aus). VoiceDesign mit": "(without it the default instruction from the configuration applies; only 1.7B models follow it). VoiceDesign with","und": "and",", falls eingeschaltet. STT: json, verbose_json, text. Sprache als Name („German“) oder ISO-Code („de“).": ", if enabled. STT: json, verbose_json, text. Language as a name (\"German\") or ISO code (\"de\").","Python (openai-Paket)": "Python (openai package)","Jetzt prüfen": "Check now","Update installieren": "Install update","Update abbrechen": "Cancel update","Leistung messen": "Measure performance","Misst Zeit bis zum ersten Ton und zum ersten Wort, Geschwindigkeit von Stimme, Spracherkennung und Sprachmodell bei einer und bei mehreren gleichzeitigen Anfragen und den Speicher der Dienste, auch auf einem getrennten Modell-Rechner. Dauert zwei bis drei Minuten und belastet die GPU in der Zeit. Auf der Konsole:": "Measures time to first audio and to the first word, the speed of voice, speech recognition and language model with one and with several concurrent requests, and the memory of the services, also on a separate model computer. Takes two to three minutes and loads the GPU meanwhile. On the console:","Messung starten": "Start measurement","Kopieren": "Copy","Update-Protokoll": "Update log","Aktualisieren": "Refresh","Hallo, hier spricht der DGX Spark.": "Hello, this is the DGX Spark speaking.","Zahlen vorlesen": "Reading numbers","als Wörter (Datum, Uhrzeit, Geld, Prozent; Telefonnummern in Zweierblöcken)": "as words (dates, times, money, percent; phone numbers in pairs)","in Zweierblöcken (Zahlen ab 3 Stellen: 4711 → siebenundvierzig elf)": "in pairs (numbers with 3+ digits: 4711 → forty-seven eleven)","Ziffer für Ziffer (Zahlen ab 3 Stellen: 4711 → vier sieben eins eins)": "digit by digit (numbers with 3+ digits: 4711 → four seven one one)","unverändert (das Modell rät)": "unchanged (the model guesses)","Gespräch": "Talk","Der Browser erlaubt das Mikrofon nur über https. Öffne das Panel über": "The browser only allows the microphone over https. Open the panel at","und bestätige einmal die Zertifikatswarnung (das Zertifikat ist selbst erstellt). Tippen geht auch hier.": "and accept the certificate warning once (the certificate is self-signed). Typing works here too.","Stopp": "Stop","oder hier tippen, Enter sendet": "or type here, Enter sends","Senden": "Send","Verlauf": "Conversation","HTTPS-Port für den Sprach-Chat (Mikrofon braucht https; 0 = aus)": "HTTPS port for the voice chat (the microphone needs https; 0 = off)","LLM-Adresse (OpenAI-kompatibel, qwen38: http://127.0.0.1:30001/v1)": "LLM address (OpenAI-compatible, qwen38: http://127.0.0.1:30001/v1)","LLM-API-Schlüssel (qwen38: ~/.config/qwen38/api-key)": "LLM API key (qwen38: ~/.config/qwen38/api-key)","Systemanweisung": "System prompt","Erster Audio-Block beim Streamen in Frames (1 Frame ≈ 0,08 s; kleiner = früherer erster Ton, unter ~6 stockt der Anfang; 0 = vllm-omni entscheidet nach Last)": "First audio block when streaming, in frames (1 frame ≈ 0.08 s; smaller = earlier first audio, below ~6 the start stutters; 0 = vllm-omni decides by load)","Änderungsprotokoll": "Change log","Wo dein Profil angemeldet ist. Ein Gerät, das du nicht mehr nutzt oder verloren hast, kannst du hier sperren.": "Where your profile is signed in. A device you no longer use or have lost can be blocked here.","Geräte mit Schlüssel": "Devices with a key","Überall abmelden": "Log out everywhere","Meldet dein Profil in allen anderen Browsern ab; dieser bleibt angemeldet. Geräte mit Schlüssel (Lautsprecher, Uhr) sperrst du oben einzeln. Eine Anmeldung endet außerdem nach 90 Tagen ohne Nutzung.": "Logs your profile out in all other browsers; this one stays signed in. Devices with a key (speaker, watch) are blocked one by one above. A sign-in also ends after 90 days without use.","Zurück zur vorigen Version": "Back to the previous version","Funktionsprüfung": "Live check","Probiert die echten Dienste einmal aus: das Sprachmodell antwortet und ruft ein Werkzeug auf, die Websuche findet etwas (wenn an), die Sprachausgabe spricht einen Satz, die Spracherkennung versteht ihn wieder. Läuft nach jedem Update von selbst.": "Tries the real services once: the language model answers and calls a tool, web search finds something (when on), speech output says a sentence, speech recognition understands it again. Runs by itself after every update.","Sicherung": "Backup","Jetzt sichern": "Back up now","Einrichtung erneut starten": "Run setup again","Darunter zeigt das Panel oben auf jeder Seite eine Warnung und schreibt es ins Änderungsprotokoll.": "Below this the panel shows a warning on top of every page and writes it to the change log.","Wächter": "Watchdog","Startet ASR, TTS oder eine Engine neu, wenn sie 5 Minuten nicht antwortet, 5 Minuten arbeitet, ohne eine Anfrage fertigzustellen, oder 45 Minuten lädt. Höchstens dreimal pro Stunde, jeder Neustart steht im Änderungsprotokoll.": "Restarts ASR, TTS or an engine that does not answer for 5 minutes, works for 5 minutes without finishing a request, or loads for 45 minutes. At most three times an hour; every restart is in the change log.","Frühere Gespräche durchsuchen": "Search earlier conversations","Erinnerungen auf diesem Gerät": "Reminders on this device","Einschalten": "Switch on","Ausschalten": "Switch off","Zurück": "Back","Überspringen": "Skip","Weiter": "Next","Code aus der Authenticator-App": "Code from the authenticator app","Diesem Browser 30 Tage vertrauen": "Trust this browser for 30 days","Handy nicht da? Ein Wiederherstellungscode geht auch.": "Phone not at hand? A recovery code works too.","Zweiter Anmeldeschritt": "Second login step","Zweiter Anmeldeschritt für Profile": "Second login step for profiles","z. B. Rosen schneiden": "e.g. pruning roses","Merkt sich Dinge, die man ihm sagt, getrennt pro Profil.": "Remembers what you tell it, separately per profile.","Profile können nach früheren Gesprächen fragen; aus ruhigen Gesprächen merkt er sich wenige Fakten.": "Profiles can ask about past conversations; from quiet ones it keeps a few facts.","Profile laden eigene Dokumente hoch, der Assistent sucht darin.": "Profiles upload their own documents and the assistant searches them.","Das Modell sucht selbst über deine SearXNG-Instanz, wenn eine Frage aktuelle Informationen braucht.": "The model searches through your SearXNG instance when a question needs current information.","„Erinnere mich in 10 Minuten an den Ofen“: Das Gerät klingelt und sagt es an.": "\"Remind me about the oven in 10 minutes\": the device rings and says it.","Termine vorlesen, nach „Ja“ eintragen, und auf „Guten Morgen“ das Tagesbriefing.": "Reads appointments, adds them after \"yes\", and gives the daily briefing on \"good morning\".","„Setz Milch auf die Einkaufsliste“: Einkauf, Aufgaben und eigene Listen auf der Seite Listen, mit wer und wann.": "\"Put milk on the shopping list\": shopping, tasks and own lists on the page Lists, with who and when.","Vorhersage für den eigenen Ort von Open-Meteo, ohne Schlüssel.": "Forecast for your own place from Open-Meteo, no key needed.","Abfahrten und Verspätungen an der eigenen Haltestelle.": "Departures and delays at your own stop.","Telefonnummern, E-Mail-Adressen und Geburtstage aus dem eigenen Adressbuch.": "Phone numbers, e-mail addresses and birthdays from your own address book.","Licht, Geräte und Heizung per Sprache, jedes Profil mit seinem eigenen Home Assistant.": "Lights, devices and heating by voice, each profile with its own Home Assistant.","Home Assistant nutzt Spracherkennung und Stimme des Spark (Voice PE, HA-App), nur von erlaubten Adressen.": "Home Assistant uses the Spark's speech recognition and voice (Voice PE, HA app), only from allowed addresses.","Neue Mails nennen und vorlesen; der Assistent sendet, löscht und markiert nie.": "Names and reads new mail; the assistant never sends, deletes or marks anything.","Werbung und Newsletter in eigene Ordner sortieren; nie löschen, nie senden, alles umkehrbar.": "Sorts ads and newsletters into their own folders; never deletes, never sends, everything can be undone.","Was heute kommt, aus den Versandmails im eigenen Postfach.": "What arrives today, from the shipping mails in your own mailbox.","Der Assistent meldet sich, wenn wirklich etwas ist: Termine, Smart-Home-Regeln, wichtige Mails, Wetter.": "The assistant speaks up when something really matters: appointments, smart home rules, important mail, weather.","Hört an einem Gerät für eine gewählte Zeit dem Gespräch im Raum zu und hilft in Pausen.": "Listens to the conversation in the room on one device for a chosen time and helps in pauses.","Profile schreiben dem Assistenten über einen eigenen Telegram-Bot, auch mit Sprachnachrichten.": "Profiles write to the assistant through their own Telegram bot, voice messages too.","ESP32-S3-Boards mit Mikrofon und Lautsprecher als Sprachassistent im Raum.": "ESP32-S3 boards with microphone and speaker as a voice assistant in the room.","Profile können bei der Anmeldung zusätzlich einen Code aus einer Authenticator-App verlangen.": "Profiles can require an extra code from an authenticator app when signing in.","Nach einer Korrektur schlägt der Assistent einen Satz zum Merken vor und speichert ihn erst nach „Ja“.": "After a correction the assistant suggests a sentence to remember and saves it only after \"yes\".","Profile sagen in eigenen Worten, wie der Assistent mit ihnen reden soll; das ändert nur den Ton, nie die Regeln.": "Profiles say in their own words how the assistant should talk to them; this changes the tone only, never the rules.","Erkennt Profile an der Stimme, auch an fremden Geräten. Eine Stimme ist kein Passwort.": "Recognises profiles by their voice, on other devices too. A voice is not a password.","Bei der Werkzeugwahl nachdenken": "Think while choosing tools","Profile können einschalten, dass das Modell vor der Werkzeugwahl nachdenkt: zuverlässiger, aber die Antwort beginnt später.": "Profiles can switch on that the model thinks before choosing a tool: more reliable, but the answer starts later.","Sprachmodell": "Language model","Betrieb": "Operation","Reverse Proxy": "Reverse proxy","Spark selbst": "The Spark itself","Erinnerungen und das Tagesbriefing kommen als Mitteilung aufs Handy oder den Rechner, auch wenn die Seite zu ist.": "Reminders and the daily briefing arrive as a notification on your phone or computer, even when the page is closed.","Profile (Gedächtnis, Gespräche, Dokumente, Kalender, E-Mail-Konten, Smart Home, Stimmerkennung), geklonte Stimmen, Einstellungen, Panel-Passwort und was der Spark für alle hält (zweiter Anmeldeschritt des Admins, iPhone-Push, Telegram-Bot, Browser-Push, ESP32-Lautsprecher, Agent-Dienste, eigene Testfragen). Jeden Tag automatisch, die letzten sieben bleiben; dazu vor jedem Update, jeder Rückkehr zur vorigen Version und jedem Wiederherstellen, davon bleiben die letzten fünf.": "Profiles (memory, conversations, documents, calendars, mail accounts, smart home, speaker recognition), cloned voices, settings, panel password and what the Spark keeps for everyone (the admin's second login step, iPhone push, Telegram bot, browser push, ESP32 speakers, agent services, own test questions). Automatically every day, the last seven are kept; plus before every update, every return to the previous version and every restore, of which the last five are kept.","Gespeicherte Passwörter, Tokens und Schlüssel lassen sich mit einer normalen Sicherung nur auf diesem Spark lesen; auf einem anderen müssen sie neu eingegeben werden. Eine Umzugs-Sicherung bringt den Schlüssel dafür mit, verschlüsselt mit deinem Passwort: Auf dem neuen Spark dasselbe Passwort ins Feld eintragen, dann wiederherstellen. Anmelden muss sich danach jeder neu. Beim Wiederherstellen werden die Einstellungen wie auf der Einstellungsseite geprüft, und es wird alles getauscht oder nichts.": "With a normal backup, stored passwords, tokens and keys can only be read on this Spark; on another one they have to be entered again. A move backup brings the key for them, encrypted with your password: on the new Spark enter the same password in the field, then restore. Everyone has to sign in again afterwards. When restoring, the settings are checked like on the settings page, and either everything is swapped or nothing.","Umzugs-Passwort (mind. 12 Zeichen)": "Move password (at least 12 characters)","Auf einen Blick": "At a glance","Alle Einstellungen des Spark mit ihrem Stand. Antippen öffnet die Seite.": "All settings of the Spark with their state. Tap to open the page.","Welches Modell antwortet und wie genau.": "Which model answers and how precisely.","Verbindung": "Connection","Schlüssel": "Key","Beim eigenen Sprachmodell bleibt er leer, bei qwen38 trägt das Update ihn selbst ein.": "With the own language model it stays empty, with qwen38 the update enters it by itself.","Mehr": "More","Weniger": "Less","Er steht auf dem Spark in ~/.config/qwen38/api-key. Leer lassen, wenn der Server keinen Schlüssel verlangt.": "It is on the Spark in ~/.config/qwen38/api-key. Leave empty if the server needs no key.","Antworten": "Answers","Grundton aller Antworten; die festen Regeln kommen immer dazu.": "Basic tone of all answers; the fixed rules are always added.","Standard": "Default","empfohlen": "recommended","Keine Uhrzeit, kein Datum und kein Betrag, der in keinem Werkzeug-Ergebnis steht.": "No time, date or amount that is not in a tool result.","Gilt bei Fragen nach Terminen, Mails, Erinnerungen, Ergebnissen und Ähnlichem, auch für Spielstände. Antwortet das Modell ohne nachzusehen, wird es einmal neu gefragt.": "Applies to questions about appointments, mails, reminders, results and the like, also scores. If the model answers without looking, it is asked once more.","Kleiner = hält sich enger an Werkzeug-Ergebnisse; 0.3 empfohlen, Qwen-Standard 0.7.": "Lower = sticks closer to tool results; 0.3 recommended, Qwen default 0.7.","Länge einer Antwort": "Length of an answer","Höchstens so viele Tokens pro Antwort.": "At most this many tokens per answer.","Werkzeuge": "Tools","Gilt, solange das Modell ein Werkzeug wählt; danach die Temperatur oben. 0.1 empfohlen.": "Applies while the model picks a tool; afterwards the temperature above. 0.1 recommended.","· Verlaufslänge, Websuchen, Zeitlimit, Wortwahl, Wiederholungen, Werkzeugpflicht": "· history length, web searches, time limit, word choice, repetitions, tool duty","Verlaufslänge": "History length","Wie viel vom bisherigen Gespräch das Modell mitbekommt, 4000 bis 64000.": "How much of the conversation so far the model gets, 4000 to 64000.","Zeichen": "characters","24000 Zeichen sind etwa 8000 Tokens. Mehr braucht ein Modell mit großem Kontextfenster und mehr Speicher.": "24000 characters are about 8000 tokens. More needs a model with a large context window and more memory.","Zeitlimit für eine Antwort": "Time limit for an answer","60 bis 600. Kürzer lohnt sich, wenn das Modell auf einem anderen Rechner läuft.": "60 to 600. Shorter pays off when the model runs on another computer.","Sekunden": "seconds","Wortwahl (top_p)": "Word choice (top_p)","0 = Standard des Servers, sonst 0.05 bis 1; kleiner = vorsichtigere Wortwahl.": "0 = the server's default, else 0.05 to 1; lower = more careful word choice.","Wiederholungen vermeiden (presence_penalty)": "Avoid repetitions (presence_penalty)","0 = Standard des Servers, bis 2; hilft, wenn das Modell sich wiederholt (Qwen: etwa 1).": "0 = the server's default, up to 2; helps when the model repeats itself (Qwen: about 1).","Eine Zeile pro Werkzeug: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Nur ganze Wörter, höchstens 20 pro Werkzeug. Die eingebauten Wörter bleiben immer.": "One line per tool: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, tasks_show. Whole words only, at most 20 per tool. The built-in words always stay.","Wie der Spark spricht: Modell, Stimme und wie Text vorgelesen wird.": "How the Spark speaks: model, voice and how text is read out.","Sprachausgabe an": "Speech output on","Aus = der Dienst wird gestoppt; es gibt keine gesprochenen Antworten.": "Off = the service is stopped; there are no spoken answers.","CustomVoice: feste Sprecher. VoiceDesign: Stimme per Beschreibung. Base: eigene Stimmen (Stimmen).": "CustomVoice: fixed speakers. VoiceDesign: voice by description. Base: own voices (Voices).","Gilt, wenn eine Anfrage keine Sprache nennt.": "Applies when a request names no language.","Datum, Uhrzeit, Geld und Kommazahlen werden immer ausgeschrieben, außer bei „unverändert“.": "Dates, times, money and decimals are always spelled out, except with \"unchanged\".","Eine Regel pro Zeile, „Wort = so gesprochen“; ganze Wörter, Groß-/Kleinschreibung egal.": "One rule per line, \"word = spoken like this\"; whole words, case does not matter.","· Port, Temperatur, Wortwahl, Seed, Engine": "· port, temperature, word choice, seed, engine","Der Port des Dienstes auf dem Spark.": "The port of the service on the Spark.","Anteil am ganzen 128-GB-Pool.": "Share of the whole 128 GB pool.","Mehr braucht mehr Speicher.": "More needs more memory.","Kleiner erster Block = früher hörbar, größerer = läuft gleichmäßiger an.": "Smaller first block = heard earlier, larger = starts more evenly.","Stimme per Beschreibung.": "Voice by description.","bfloat16 passt für die meisten Grafikkarten.": "bfloat16 fits most graphics cards.","Eigene Stimmen für die Sprachausgabe: aufnehmen, anhören, sichern.": "Own voices for the speech output: record, listen, back up.","Stimme hinzufügen": "Add a voice","· aufnehmen oder Audiodatei hochladen": "· record or upload an audio file","So heißt die Stimme später in der Auswahl.": "The voice is listed under this name.","Lies den Text ruhig vor, so wie die Stimme später klingen soll.": "Read the text calmly, the way the voice should sound later.","… oder eine Audiodatei hochladen": "… or upload an audio file","Datei wählen …": "Choose file …","Genau der gesprochene Text; die Spracherkennung trägt ihn nach einer Aufnahme ein.": "Exactly the spoken text; speech recognition fills it in after a recording.","Eine ZIP-Datei mit Referenz-Audio und Transkript, etwa zum Sichern.": "A ZIP file with reference audio and transcript, e.g. as a backup.","Exportieren": "Export","ZIP importieren": "Import ZIP","Stimmen von einem anderen Spark übernehmen.": "Take over voices from another Spark.","Wie der Spark gesprochene Sätze in Text verwandelt.": "How the Spark turns spoken sentences into text.","Spracherkennung an": "Speech recognition on","Aus = der Dienst wird gestoppt; Sprechen mit dem Assistenten geht dann nicht.": "Off = the service is stopped; talking to the assistant does not work then.","Qwen3-ASR auf der Grafikkarte oder Parakeet auf dem Prozessor.": "Qwen3-ASR on the graphics card or Parakeet on the processor.","Namen und Fachbegriffe, die die Erkennung erwarten soll (z. B. DGX Spark, Qwen, Open WebUI).": "Names and technical terms recognition should expect (e.g. DGX Spark, Qwen, Open WebUI).","· Port, Engine": "· port, engine","Wie viele Aufnahmen auf einmal erkannt werden.": "How many recordings are recognized at once.","Obergrenze für den Text einer Aufnahme.": "Upper limit for the text of one recording.","Wer den Spark erreicht und wie du dich als Admin anmeldest.": "Who reaches the Spark and how you sign in as admin.","Wer den Spark erreicht": "Who reaches the Spark","wirkt mit Speichern": "applies on save","An: Startseite für alle im Netz, auch Gäste.": "On: start page for everyone in the network, guests too.","Aus: nur angemeldete Profile (Name und PIN) und Geräte mit Schlüssel, keine Gäste. Einstellungen bleiben immer geschützt.": "Off: only signed-in profiles (name and PIN) and devices with a key, no guests. Settings always stay protected.","Heimnetz-Adressen erlauben": "Allow home network addresses","Kalender, Kontakte und Mail der Profile dürfen auch auf Servern im Heimnetz liegen.": "Calendars, contacts and mail of the profiles may also be on servers in the home network.","Nur diesen Adressen wird die weitergereichte Absender-Adresse geglaubt.": "Only these addresses are trusted with the forwarded sender address.","Gemeint ist X-Forwarded-For. Leer = nur ein Proxy auf dem Spark selbst. Eintragen, wenn das Panel hinter einem Proxy im Heimnetz hängt: sonst teilen sich alle, die über den Proxy kommen, eine Adresse für die Sperre nach falschen Passwörtern.": "This is X-Forwarded-For. Empty = only a proxy on the Spark itself. Fill in when the panel sits behind a proxy in the home network: otherwise everyone coming through the proxy shares one address for the lock after wrong passwords.","Gesetzt = Apps senden „Authorization: Bearer <Schlüssel>“; leer = ohne Schlüssel.": "Set = apps send \"Authorization: Bearer <key>\"; empty = no key.","wirkt sofort, ohne Speichern": "applies at once, without saving","Ändern …": "Change …","Code aus einer Authenticator-App bei jeder Admin-Anmeldung.": "Code from an authenticator app at every admin sign-in.","Solange er an ist, geht die Anmeldung per HTTP-Basic (Skripte) nicht mehr, und Passwort ändern, Sicherung wiederherstellen, Geräteschlüssel anlegen oder umhängen und PINs ändern fragen jedes Mal nach einem Code. Notausgang ohne Handy und Codes: auf dem Spark sudo rm /var/lib/speech-spark/state/mfa-admin.json": "While it is on, sign-in by HTTP Basic (scripts) no longer works, and changing the password, restoring a backup, creating or moving device keys and changing PINs ask for a code every time. Way out without phone and codes: on the Spark sudo rm /var/lib/speech-spark/state/mfa-admin.json","Beendet die Admin-Anmeldung in allen Browsern, auch hier (z. B. nach einem verlorenen Gerät).": "Ends the admin sign-in in every browser, here too (e.g. after a lost device).","Wie der Spark mit Speicher, hängenden Diensten, Logs und Ports umgeht.": "How the Spark handles memory, hanging services, logs and ports.","Warnen unter": "Warn below","GiB frei": "GiB free","Hängende Dienste neu starten": "Restart hanging services","Startet ASR, TTS oder eine Engine neu, wenn sie hängt; höchstens dreimal pro Stunde.": "Restarts ASR, TTS or an engine when it hangs; at most three times an hour.","Hängen heißt: 5 Minuten keine Antwort, 5 Minuten arbeiten, ohne eine Anfrage fertigzustellen, oder 45 Minuten laden. Jeder Neustart steht im Änderungsprotokoll.": "Hanging means: no answer for 5 minutes, working for 5 minutes without finishing a request, or loading for 45 minutes. Every restart is in the change log.","Höchstens so viel Platz": "At most this much space","Aufbewahren": "Keep","Wirkt nach dem nächsten Update oder sudo ./install.sh.": "Applies after the next update or sudo ./install.sh.","Tage": "days","Ein Update holt den neuesten Stand von GitHub und installiert ihn. Einstellungen, Modelle und Stimmen bleiben. Vor dem Umschalten prüft ein Selbsttest die neue Version; schlägt er oder ein Schritt davor fehl, läuft die bisherige Version unverändert weiter. Geht nach dem Umschalten etwas schief, wird die bisherige Version wieder eingespielt. Während des Updates starten die Dienste kurz neu.": "An update gets the newest state from GitHub and installs it. Settings, models and voices stay. Before switching over, a self-test checks the new version; if it or a step before fails, the current version keeps running unchanged. If something goes wrong after switching, the previous version is put back. During the update the services restart briefly.","wirkt sofort": "applies at once","Stand": "State","jeden Tag automatisch": "automatically every day","Was gesichert wird": "What is backed up","Profile, geklonte Stimmen, Einstellungen und was der Spark für alle hält.": "Profiles, cloned voices, settings and what the Spark keeps for everyone.","Legt sofort eine Sicherung auf dem Spark an.": "Makes a backup on the Spark right now.","Sichern": "Back up","Aus Datei wiederherstellen": "Restore from file","Eine heruntergeladene Sicherung (.tar.gz) einspielen.": "Restore a downloaded backup (.tar.gz).","Umzugs-Sicherung": "Move backup","Für einen anderen Spark: bringt den Schlüssel für Passwörter und Tokens mit.": "For another Spark: brings the key for passwords and tokens along.","· was beim letzten Update passiert ist": "· what happened during the last update","Welche Stimme der Assistent nutzt, steht unter Einstellungen → Sprachausgabe → Standardstimme; jedes Profil kann sich unter Ich → Gespräch eine andere wählen. Wer spricht, erkennt dagegen die Sprechererkennung.": "Which voice the assistant uses is set under Settings → Speech output → default voice; every profile can choose another one under Me → Conversation. Who is speaking is recognized by speaker recognition instead.","Angemeldete Browser": "Signed-in browsers","Meldet dein Profil in allen anderen Browsern ab; dieser bleibt angemeldet. Geräte mit Schlüssel (Lautsprecher, Uhr) sperrst du oben einzeln. Einzelne Browser meldest du in der Liste darüber ab. Eine Anmeldung endet außerdem nach": "Logs your profile out in all other browsers; this one stays signed in. Devices with a key (speakers, watch) are blocked one by one above. Single browsers are signed out in the list above it. A sign-in also ends after","Tagen ohne Nutzung. Mit zweitem Anmeldeschritt müssen auch vertraute Browser danach wieder einen Code eingeben.": "days without use. With the second sign-in step, trusted browsers have to enter a code again afterwards.","Anmeldung im Browser": "Sign-in in the browser","Ein Profil bleibt so viele Tage ohne Nutzung angemeldet (7 bis 90).": "A profile stays signed in for this many days without use (7 to 90).","rot = offen, gelb = empfohlen, grün = gut": "red = open, yellow = recommended, green = fine","Suchen …": "Search …","Gespräch einstellen": "Conversation settings","Spark": "Spark","Anfragen verfolgen": "Trace requests","Zeigt unter Zustand → Logs → Anfragen den Weg jeder Anfrage mit Werkzeugen und Zeiten.": "Shows the way of every request with tools and times under Status → Logs → Requests.","Aufgezeichnet werden nur Wege, Werkzeugnamen und Zahlen, nie Frage, Antwort, Suchbegriffe oder Ergebnisse. Höchstens 48 Stunden und 500 Anfragen. Den Namen eines Profils zeigt die Liste nur, wenn das Profil es unter Ich → Gespräch erlaubt; sonst steht dort „Profil“. Sehen können es der Admin und Mit-Admins.": "Only ways, tool names and numbers are recorded, never the question, the answer, search words or results. At most 48 hours and 500 requests. The list shows a profile's name only when the profile allows it under Me → Conversation; otherwise it says \"Profile\". The admin and co-admins can see it.","Erst lokal suchen": "Look locally first","Wissensfragen zuerst in Dokumenten, Kiwix-Archiv und früheren Gesprächen, dann im Web. Aktuelles wie Wetter geht direkt hinaus.": "Knowledge questions first in documents, the Kiwix archive and earlier conversations, then on the web. Current things like weather go straight out.","Zeitgrenze für das Nachsehen (ms)": "Time limit for looking (ms)","Zeitgrenze für das Kiwix-Archiv (ms)": "Time limit for the Kiwix archive (ms)","Adresse für Links (frei lassen: wie oben)": "Address for links (leave empty: as above)","Nur für die Links unter einer Antwort, zum Beispiel der Name hinter deinem Proxy. Gefragt wird das Kiwix weiter über die Adresse oben. Ändern braucht den zweiten Anmeldeschritt.": "Only for the links under an answer, for example the name behind your proxy. The Kiwix is still asked at the address above. Changing it needs the second sign-in step.","200 bis 2000, Standard 900. Ein großes Archiv braucht oft länger als die eigenen Unterlagen; die übrigen Quellen warten nicht mit.": "200 to 2000, default 900. A big archive often needs longer than the own documents; the other sources do not wait for it.","Erst lokal testen": "Test looking locally first","Zeigt für einen Satz, ob er erst lokal gesucht wird, und was Dokumente, Kiwix-Archiv und frühere Gespräche finden, mit Zeiten. Gesucht wird in den Unterlagen des Profils, das in diesem Browser angemeldet ist. Schalter unter Funktionen → Websuche.": "Shows for one sentence whether it is looked up locally first, and what documents, the Kiwix archive and earlier conversations find, with times. It searches the documents of the profile signed in in this browser. Switch under Features → Web search.","+ Neues Profil": "+ New profile","+ Neues Gerät": "+ New device","Update-Verlauf": "Update history","Profile verbinden ihr my.remarkable-Konto; gewählte Notizbücher kommen in ihre Dokumente, Handschrift liest das Sprachmodell.": "Profiles connect their my.remarkable account; chosen notebooks go into their documents, the language model reads handwriting.","Antworten und diktierte Notizen als neues Dokument in den Ordner „Spark“; sonst ändert der Spark dort nichts.": "Answers and dictated notes as a new document in the folder \"Spark\"; otherwise the Spark changes nothing there.","Technische Details": "Technical details","Sicherung nach außen": "Backup to the outside","aus, bis du sie einschaltest": "off until you switch it on","Jeden Tag verschlüsselt auf den NAS": "Encrypted to the NAS every day","Eine Kopie der Sicherung geht per WebDAV in einen Ordner (NAS, Nextcloud, Synology). Der NAS sieht nur verschlüsselte Daten.": "A copy of the backup goes over WebDAV into a folder (NAS, Nextcloud, Synology). The NAS only sees encrypted data.","Die Kopie ist eine Umzugs-Sicherung, als Ganzes mit dem Sicherungs-Passwort verschlüsselt (scrypt, AES-256-GCM), bevor sie den Spark verlässt. Wiederherstellen: die Datei vom NAS laden, oben unter „Aus Datei wiederherstellen“ mit demselben Passwort einspielen; das geht auch auf einem neuen Spark. Ohne das Passwort ist die Kopie verloren: schreib es auf. Dort bleiben die letzten 7 Kopien; der Spark löscht nur, was er selbst geschickt hat. Nur https.": "The copy is a move backup, encrypted as a whole with the backup password (scrypt, AES-256-GCM) before it leaves the Spark. To restore: download the file from the NAS and load it above under \"Aus Datei wiederherstellen\" with the same password; this also works on a new Spark. Without the password the copy is lost: write it down. The last 7 copies stay there; the Spark only deletes what it sent itself. https only.","WebDAV-Ordner": "WebDAV folder","WebDAV-Passwort": "WebDAV password","Sicherungs-Passwort (mind. 12 Zeichen, aufschreiben)": "Backup password (at least 12 characters, write it down)","Sicherungs-Passwort": "Backup password","Zertifikat prüfen": "Check certificate","Jetzt senden": "Send now","Mein Zustand aller Profile": "My status of all profiles","Nur Anzahlen über alle Profile, die die Seite nutzen; nie Namen, Dienste oder Inhalte.": "Counts only, over all profiles that use the page; never names, services or contents.","Mein Zustand": "My status","Jedes Profil sieht unter Ich, was der Spark im Hintergrund für es erledigt und ob seine verbundenen Dienste antworten.": "Every profile sees under Me what the Spark does for it in the background and whether its connected services answer.","Vorrang für Personen": "Priority for people","Reden mehrere gleichzeitig, bekommen ausgewählte Profile ihre Antwort zuerst. Wer Vorrang hat, legst du unter Personen und Geräte fest.": "When several people talk at once, chosen profiles get their answer first. You pick who has priority under People and devices.","Andere warten höchstens": "Others wait at most","gar nicht (nur Sprachausgabe und Erkennung)": "not at all (speech output and recognition only)","1 Sekunde": "1 second","2 Sekunden (empfohlen)": "2 seconds (recommended)","3 Sekunden": "3 seconds","5 Sekunden": "5 seconds","So lange halten neue Anfragen anderer ans Sprachmodell an, bis die Antwort mit Vorrang ihren ersten Satz hat. Laufende Antworten werden nie abgebrochen.": "This long new requests of others to the language model hold until the answer with priority has its first sentence. Running answers are never stopped.","In anderen Programmen": "In other programs","Mac-Schnellaktion, Windows-Programm, Office-Add-in, Browser-Erweiterung und iPhone-Kurzbefehl, je mit eigenem Schlüssel.": "Mac quick action, Windows program, Office add-in, browser extension and iPhone shortcut, each with its own key.","Spark-Begleiter am PC und Mac": "Spark companion on PC and Mac","Programm in Taskleiste und Menüleiste: Schreibhilfe, Frag Spark, Diktieren, Meldungen, Notaus; pro Gerät im Panel eingestellt.": "Program in the taskbar and menu bar: writing help, Ask Spark, dictation, notes, kill switch; set per device in the panel.","Neue Version jetzt holen": "Fetch the new version now","Schlüssel für Home Assistant": "Key for Home Assistant","Ein Schlüssel kann nur den Notaus auslösen, nichts lesen und nichts aufheben. Nur aus dem Heimnetz.": "A key can only trigger the emergency stop: it reads nothing and lifts nothing. Home network only.","Name, z. B. Home Assistant": "Name, e.g. Home Assistant","Name des Schlüssels": "Name of the key","Schlüssel erzeugen": "Create key","Nur jetzt sichtbar. In Home Assistant in configuration.yaml einfügen, dann neu laden; „rest_command.spark_notaus“ löst Stufe 2 aus, der Sensor zeigt die Stufe.": "Shown only now. Paste into configuration.yaml in Home Assistant and reload; “rest_command.spark_notaus” triggers stage 2, the sensor shows the stage.","Notaus von selbst": "Emergency stop by itself","Der Wächter schaltet Stufe 1 „Außen zu“ ein, wenn von außen jemand angreift.": "The guard switches on stage 1 “Outside closed” when someone attacks from outside.","Feste Regeln, nie das Sprachmodell: 20 falsche Anmeldungen von außen in 10 Minuten, eine MCP-Flut von außen (30 abgewiesene Anfragen in 10 Minuten) oder 15 gesperrte Verbindungen nach außen in 10 Minuten. Nur Stufe 1, nie höher; die Admins bekommen einen Push, aufheben wie immer nur als Admin im Browser im Heimnetz.": "Fixed rules, never the language model: 20 wrong sign-ins from outside in 10 minutes, an MCP flood from outside (30 turned-away requests in 10 minutes) or 15 refused outbound connections in 10 minutes. Stage 1 only, never higher; the admins get a push, lifting as always only as an admin in the browser at home.","Besprechungen mitschreiben": "Write along in meetings","Bildschirm zeigen und bedienen": "Show and operate the screen","Spark bedient den Rechner": "Spark operates the computer","Der Spark erledigt Aufträge am eigenen PC oder Mac Schritt für Schritt und beschreibt auf Frage den Bildschirm; der Rechner fragt jedes Mal.": "The Spark does tasks on your own PC or Mac step by step and describes the screen when asked; the computer asks every time.","Den eigenen PC oder Mac vom Handy oder Panel aus ansehen und bedienen; der Rechner fragt jedes Mal, nichts wird aufgezeichnet.": "View and operate your own PC or Mac from the phone or panel; the computer asks every time, nothing is recorded.","Begleiter schreibt auf Klick mit (Mikrofon und Ton des Rechners), danach Zusammenfassung und Aufgaben; nichts bleibt gespeichert.": "The companion writes along on a click (microphone and the computer's sound), then summary and tasks; nothing stays stored.","Zum Update": "To the update","Aufs reMarkable schicken": "Send to the reMarkable","Neueste zuerst": "Newest first","Mehr mit dem reMarkable": "More with the reMarkable","Eigene Lautsprecher (ESP32)": "Own speakers (ESP32)","Firmware jetzt holen": "Fetch firmware now","Adresse des Spark für die Lautsprecher": "Address of the Spark for the speakers","Adresse prüfen": "Check address","Panel-Adresse für Links in Telegram": "Panel address for links in Telegram","Diese Adresse nehmen": "Use this address","Nennt eine Nachricht eine Stelle im Panel, bekommt sie einen Knopf „Im Panel öffnen“. Leer: kein Knopf. Nur https.": "When a message names a place in the panel, it gets an \"Open in the panel\" button. Empty: no button. https only.","Leer = die Adresse dieser Seite. Am besten dein Reverse Proxy mit echtem Zertifikat (er muss WebSockets durchlassen); ein selbst signiertes Zertifikat (Port 31443) nimmt das Board nicht an, im Heimnetz geht auch http://<Spark-IP>:31080.": "Empty = the address of this page. Best is your reverse proxy with a real certificate (it must let WebSockets through); the board does not accept a self-signed certificate (port 31443), in the home network http://<Spark-IP>:31080 works too.","Leer = die Adresse dieser Seite. Am besten dein Reverse Proxy mit echtem Zertifikat (er muss WebSockets durchlassen); ein selbst signiertes Zertifikat (Port 31443) nimmt das Board nicht an, im Heimnetz geht auch http://<Spark-IP>:31080 (unverschlüsselt).": "Empty = the address of this page. Best is your reverse proxy with a real certificate (it must let WebSockets through); the board does not accept a self-signed certificate (port 31443), in the home network http://<Spark-IP>:31080 works too (unencrypted).","Eine Zeile pro Werkzeug: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, wikipedia, tasks_show. Nur ganze Wörter, höchstens 20 pro Werkzeug. Die eingebauten Wörter bleiben immer.": "One line per tool: calendar_events, mail_list, reminder_list, web_search, weather, parcels, transit, wikipedia, tasks_show. Whole words only, at most 20 per tool. The built-in words always stay.","Rohwerte": "Raw values","Pebble-Uhr": "Pebble watch","App „Spark“ für Pebble Time 2 und Core 2 Duo (Antwort als Text und über den Lautsprecher der Uhr) sowie Pebble Round 2 (nur Text). Frage per Knopfdruck, die Pebble-Diktierfunktion macht Text daraus, die Antwort kommt von hier.": "\"Spark\" app for Pebble Time 2 and Core 2 Duo (answer as text and through the watch speaker) and Pebble Round 2 (text only). Ask with a button, the Pebble dictation turns it into text, the answer comes from here.","In der Pebble-App bei „Spark“ die Einstellungen öffnen und den Einrichtungscode einfügen (oder Spark-Adresse und Geräteschlüssel eintragen). Die Uhr muss dabei mit dem Handy verbunden sein.": "In the Pebble app open the settings of \"Spark\" and paste the setup code (or enter the Spark address and the device key). The watch has to be connected to the phone meanwhile.","Auf der Uhr: SELECT fragt, nochmal SELECT stoppt die Sprache, lang SELECT beginnt ein neues Gespräch.": "On the watch: SELECT asks, SELECT again stops the speech, a long SELECT starts a new conversation.","Das Handy muss die Spark erreichen: zu Hause im WLAN, unterwegs über ein VPN wie Tailscale. Die Uhr-App nutzt normales HTTP, weil die Pebble-App dem selbstsignierten Zertifikat nicht vertraut.": "The phone has to reach the Spark: at home over Wi-Fi, away from home through a VPN like Tailscale. The watch app uses plain HTTP because the Pebble app does not trust the self-signed certificate.","„Hey Siri, frag Spark“": "\"Hey Siri, ask Spark\"","Ein iPhone-Kurzbefehl schickt deine Frage an den Spark, Siri liest die Antwort vor. Geht ohne geöffnete Seite, auch auf der Apple Watch, mit AirPods und im Auto (CarPlay). Nachfragen innerhalb von 10 Minuten kennen den Zusammenhang; die Fragen eines Tages stehen im Verlauf deines Profils.": "An iPhone shortcut sends your question to the Spark, Siri reads the answer aloud. Works without an open page, also on the Apple Watch, with AirPods and in the car (CarPlay). Follow-up questions within 10 minutes know the context; the questions of a day are in your profile's history.","Fertig: „Hey Siri, Frag Spark“, dann die Frage sagen.": "Done: \"Hey Siri, Frag Spark\" (the shortcut's name), then say the question.","Unterwegs muss das iPhone den Spark erreichen, zum Beispiel über deinen Reverse-Proxy mit https oder ein VPN. Trag dann die Adresse des Proxys statt der Adresse im Heimnetz ein.": "Away from home the iPhone has to reach the Spark, for example through your reverse proxy with https or a VPN. Then enter the proxy's address instead of the home network address.","Später": "Later","Hell / Dunkel / System": "Light / Dark / System","Menü": "Menu","Umzugs-Passwort": "Move password","WebDAV-Benutzer": "WebDAV user","Raum-Modus: hört dem Gespräch im Raum zu und hilft in Pausen; endet von selbst": "Room mode: listens to the conversation in the room and helps in pauses; ends by itself","In früheren Gesprächen suchen": "Search earlier conversations","Bild anhängen": "Attach a picture","Alle paar Sekunden neu laden; pausiert, solange du hochscrollst oder etwas markierst": "Reload every few seconds; pauses while you scroll up or select something","Im Changelog suchen": "Search the changelog","Dienste, die Profile unter <b>Ich → Meine MCP-Dienste</b> selbst angebunden haben, ohne Schlüssel. Sperren gilt sofort, auch wenn das Profil den Dienst neu anbindet.": "Services that profiles connected themselves under <b>Me → My MCP services</b>, without keys. Blocking applies at once, even when the profile connects the service again.","Unter <b>Ich → Pebble-Uhr</b> „Pebble koppeln“ tippen und den Einrichtungscode kopieren (Admin: Funktionen → Pebble-Uhr koppeln an). Ohne das: unter Personen und Geräte beim eigenen Profil ein Gerät „Pebble“ anlegen und den Schlüssel kopieren.": "Under <b>Me → Pebble watch</b> tap \"Pair Pebble\" and copy the setup code (admin: Features → pair the Pebble watch on). Without that: under People and devices add a device \"Pebble\" to your own profile and copy the key.","Auf dem Handy, das mit der Uhr gekoppelt ist, die App-Datei laden und mit der Pebble-App öffnen: <a id=\"int-pbw\" href=\"/pebble/speech-spark.pbw\">speech-spark.pbw</a>": "On the phone paired with the watch, download the app file and open it with the Pebble app: <a id=\"int-pbw\" href=\"/pebble/speech-spark.pbw\">speech-spark.pbw</a>","Unter <b>Personen und Geräte</b> beim eigenen Profil ein Gerät „iPhone Siri“ anlegen und den Schlüssel kopieren.": "Under <b>People and devices</b> add a device \"iPhone Siri\" to your own profile and copy the key.","In der App <b>Kurzbefehle</b> einen neuen Kurzbefehl mit dem Namen <b>Frag Spark</b> anlegen.": "In the <b>Shortcuts</b> app create a new shortcut named <b>Frag Spark</b> (or a name of your own).","Aktion <b>Text diktieren</b> (Sprache Deutsch, Diktieren beenden: nach Pause).": "Action <b>Dictate Text</b> (language of your choice, stop listening: after pause).","Aktion <b>Inhalte von URL abrufen</b>: URL siehe unten, Methode <b>POST</b>, Header <code>X-Speech-Device</code> = dein Schlüssel, Haupttext <b>JSON</b> mit dem Feld <code>text</code> = <i>Diktierter Text</i>.": "Action <b>Get Contents of URL</b>: URL see below, method <b>POST</b>, header <code>X-Speech-Device</code> = your key, request body <b>JSON</b> with the field <code>text</code> = <i>Dictated Text</i>.","Aktion <b>Wörterbuchwert abrufen</b>: Schlüssel <code>answer</code>.": "Action <b>Get Dictionary Value</b>: key <code>answer</code>.","Aktion <b>Text sprechen</b> mit dem Wörterbuchwert.": "Action <b>Speak Text</b> with the dictionary value.","Was der Assistent bei deinen Fragen nachgeschlagen hat: welche Werkzeuge, mit welchen Angaben, was zurückkam und was er geantwortet hat. Steht bei einer Antwort „kein Werkzeug“, kam sie nur aus dem Modell. Einträge verschwinden nach <span id=\"logdays\">7</span> Tagen.": "What the assistant looked up for your questions: which tools, with which details, what came back and what it answered. When an answer says \"no tool\", it came from the model alone. Entries disappear after <span id=\"logdays\">7</span> days.","Das Sprachmodell ist gerade nicht erreichbar. Bitte später noch einmal.": "The language model cannot be reached right now. Please try again later.","Der Kalender ist nicht erreichbar. Bitte Adresse und Netz prüfen.": "The calendar cannot be reached. Please check the address and the network.","Der Mailserver ist nicht erreichbar. Bitte Server, Port und Netz prüfen.": "The mail server cannot be reached. Please check server, port and network.","Home Assistant hat das nicht angenommen.": "Home Assistant did not accept that.","Home Assistant ist nicht erreichbar. Bitte Adresse und Netz prüfen.": "Home Assistant cannot be reached. Please check the address and the network.","Die Sicherung ging nicht: auf dem Spark ist kein Platz mehr frei.": "The backup did not work: there is no free space left on the Spark.","Die Sicherung ging nicht: der Sicherungsordner ist nicht beschreibbar.": "The backup did not work: the backup folder cannot be written.","Die Sicherung ging nicht. Mehr steht unter Zustand → Logs (Panel).": "The backup did not work. More under Status → Logs (Panel).","Wiederherstellen ging nicht: die Datei ist unvollständig oder nicht lesbar.": "Restore failed: the file is incomplete or cannot be read.","Frage an den Assistenten": "Question to the assistant","Dienst-Wächter": "Service watch","Der Spark prüft selbst, ob Archiv, Internet, Websuche und andere Dienste antworten, und meldet den Admins Ausfall und Entwarnung.": "The Spark checks by itself whether archive, internet, web search and other services answer, and tells the admins about outages and all-clears.","Hinweis an Nutzer, wenn ein Dienst fehlt": "Note to users when a service is missing","Fragt jemand etwas, das einen gerade fehlenden Dienst braucht, sagt der Assistent das sofort, statt lange zu warten.": "When somebody asks something that needs a service that is missing right now, the assistant says so at once instead of waiting long.","Nur ob ein Dienst antwortet, nie Inhalte, Adressen oder Fehlertexte. Ein Haken weg: der Dienst wird nicht geprüft und niemand bekommt Hinweise dazu.": "Only whether a service answers, never contents, addresses or error texts. A tick removed: the service is not looked at and nobody gets notes about it.","Eigener Speicher": "Own storage","Pro Profil nur Art, Zustand, Größen und Anzahlen, nie Dateinamen oder Inhalte.": "Per profile only kind, state, sizes and counts, never file names or contents.","Speicher im Heimnetz erlauben": "Allow storage in the home network","Originale auslagern": "Move originals out","Profile dürfen Originale von Dokumenten, die 30 Tage ruhen, nur auf ihrem Speicher lassen; beim Öffnen holt der Spark sie zurück.": "Profiles may keep originals of documents unused for 30 days only on their storage; the Spark fetches them back when opened.","Ziele mit Adressen im Heimnetz (NAS, Fritzbox, Nextcloud zu Hause). Aus: nur Adressen im Internet.": "Targets with addresses in the home network (NAS, Fritzbox, Nextcloud at home). Off: only internet addresses.","Ordner auf dem Spark": "Folder on the Spark","Ein Ordner, den du selbst eingehängt hast (NFS, SMB, USB-Platte); Profile wählen darin einen Unterordner.": "A folder you mounted yourself (NFS, SMB, USB disk); profiles choose a subfolder in it.","Unter /mnt, /media oder /srv, schon vorhanden, kein Verweis; der Spark-Dienst braucht dort Schreibrecht.": "Below /mnt, /media or /srv, existing, no link; the Spark service needs the right to write there.","Android: Mitteilungen sofort": "Android: notes at once","Android: Update in der App": "Android: update in the app","Die App zeigt eine neue Version oben an, lädt sie von diesem Spark, prüft sie und lässt Android sie installieren.": "The app shows a new version at the top, loads it from this Spark, checks it and lets Android install it.","Die App hält eine Verbindung offen und zeigt Hinweise und Chats sofort statt alle 15 Minuten; eine stille Daueranzeige, etwas mehr Akku.": "The app keeps a connection open and shows notes and chats at once instead of every 15 minutes; a quiet lasting notice, a bit more battery.","Chats": "Chats","Dein Platz für Fotos, Dateien und Sprache ist voll (2 GB). Alte Chats leeren oder Nachrichten zurücknehmen schafft Platz.": "Your space for photos, files and voice is full (2 GB). Clearing old chats or taking messages back makes room.","Foto": "Photo","Verwerfen": "Discard","Sprachnachricht senden": "Send voice message","Foto oder Datei schicken": "Send a photo or file","Sprachnachricht aufnehmen": "Record a voice message","höchstens 5 Minuten": "at most 5 minutes","Fotos, Dateien und Sprache in Chats": "Photos, files and voice in chats","Fotos ohne Ort, PDF, Office und Text bis 25 MB, Sprachnachrichten bis 5 Minuten; verschlüsselt auf dem Spark, bis 2 GB pro Person.": "Photos without place, PDF, Office and text up to 25 MB, voice messages up to 5 minutes; encrypted on the Spark, up to 2 GB per person.","In einen Chat einladen": "Invite into a chat","Per Link oder QR-Code direkt in den eigenen Chat einladen, 3 pro Person. Braucht Personen und Geräte → Neue Personen „nur mit Einladung“.": "Invite by link or QR code straight into your chat, 3 open per person. Needs People and devices → New people \"only by invitation\".","Diese Einladung gibt es nicht mehr.": "This invitation no longer exists.","Einladungen in Chats sind auf dem Spark aus.": "Invitations into chats are off on the Spark.","Du hast schon 3 offene Einladungen. Erst eine zurückziehen.": "You already have 3 open invitations. Withdraw one first.","Fotos, Dateien und Sprachnachrichten sind für dich ausgeschaltet.": "Photos, files and voice messages are switched off for you.","Das Foto ist zu groß.": "The photo is too large.","Das ist kein Foto, das sich lesen lässt (JPEG, PNG oder WebP).": "This is not a photo that can be read (JPEG, PNG or WebP).","Die Datei ist leer.": "The file is empty.","Die Datei ist zu groß (höchstens 25 MB).": "The file is too large (at most 25 MB).","Bilder bitte als Foto schicken.": "Please send pictures as a photo.","Diese Datei ist kein Dokument, das Chats annehmen (PDF, Office, OpenDocument, Text).": "This file is not a document chats take (PDF, Office, OpenDocument, text).","Diese Datei ist kein Dokument, das Chats annehmen.": "This file is not a document chats take.","Die Aufnahme ist zu groß.": "The recording is too large.","Die Aufnahme lässt sich nicht lesen.": "The recording cannot be read.","Die Aufnahme ist zu kurz.": "The recording is too short.","Einladungen brauchen die https-Adresse des Panels (diese Seite über https öffnen).": "Invitations need the panel's https address (open this page over https).","＋ Neuer Chat": "＋ New chat","In meinen Chats suchen": "Search my chats","Wähle einen Chat oder starte mit „＋ Neuer Chat“ einen neuen.": "Pick a chat or start a new one with \"＋ New chat\".","Zurück zu den Chats": "Back to the chats","Chat-Info": "Chat info","Antwort abbrechen": "Cancel the reply","Gruppen-Chats": "Group chats","Gruppen mit Namen und Admins, bis 50 Personen; nur wer Nachrichten vom Ersteller annimmt, kommt hinein.": "Groups with a name and admins, up to 50 people; only who takes messages from the creator gets in.","Gruppe": "Group","Gelöschtes Profil": "Deleted profile","Diese Person gibt es nicht mehr.": "This person no longer exists.","Chats sind für dich ausgeschaltet.": "Chats are switched off for you.","Gruppen-Chats sind ausgeschaltet.": "Group chats are switched off.","Gruppen-Chats sind gerade ausgeschaltet.": "Group chats are switched off right now.","Niemand davon nimmt gerade Nachrichten von dir an.": "None of them takes messages from you right now.","Nur die Admins der Gruppe ändern das.": "Only the group's admins change that.","Zurückziehen geht nur in der ersten Stunde.": "Taking back works only in the first hour.","Ändern geht nur in den ersten 15 Minuten.": "Changing works only in the first 15 minutes.","Der Gruppe fehlt ein Name.": "The group needs a name.","Die Nachricht ist leer.": "The message is empty.","Höchstens 50 Personen in einer Gruppe.": "At most 50 people in a group.","Höchstens 30 Gruppen.": "At most 30 groups.","Höchstens 300 Chats.": "At most 300 chats.","Du hast in der letzten Stunde schon 240 Nachrichten geschickt.": "You already sent 240 messages in the last hour.","Zustand per Sprache": "Status by voice","„Läuft alles?“, „Ist der Notaus an?“: der Spark liest seinen Zustand nach, statt zu raten. Gilt für alle Profile.": "\"Is everything running?\", \"Is the emergency stop on?\": the Spark reads its state instead of guessing. Holds for every profile.","Rückgängig per Sprache": "Undo by voice","„Mach das rückgängig“: nimmt die letzte Tat nach dem Ja zurück (30 Minuten lang). Gilt für alle Profile.": "\"Undo that\": takes back the last deed after the yes (for 30 minutes). Holds for every profile.","Gilt für alle, die unter Ich → Gespräch kein eigenes gewählt haben: Assistent, schwebender Knopf, Apps und Uhr.": "Applies to everybody who picked none of their own under Me → Conversation: assistant, floating button, apps and watch.","Gesicht": "Face","Was Fragen bekommen, die keine Regel erkennt, dazu Gruppen, eigene Wörter, Pflicht-Wörter, Testsätze und den Weg einzelner Sätze siehst und änderst du unter Funktionen → Weiche.": "What questions no rule recognizes get, and groups, own words, must words, test sentences and the way of single sentences: see and change them under Features → Routing.","Ab welcher Wahrscheinlichkeit die Werkzeugwahl eingrenzt und „Einordnung messen“ stehen unter Funktionen → Weiche.": "From which probability tool choice narrows and “Measure classification” are under Features → Routing.","Eigene Stichwörter für die Werkzeugpflicht (Pflicht-Wörter) stehen jetzt bei den anderen Wörtern der Weiche unter Funktionen → Weiche.": "Own keywords that require a tool (must words) are now with the switch’s other words under Features → Routing.","Antwortet das schon laufende Sprachmodell, ohne eigenen Speicher; braucht das eigene LLM-Tor oder dgx-spark-qwen38 ab v1.15. Für die Werkzeugwahl unter Funktionen → Weiche bei „Fragen, die keine Regel erkennt“ die Einordnung wählen. Ist das Sprachmodell ausgelastet, geht alles wie bisher weiter.": "The language model that already runs answers, without memory of its own; needs the own LLM-Tor or dgx-spark-qwen38 v1.15 or later. For tool choice pick the classification under Features → Routing at “Questions no rule recognizes”. When the language model is busy, everything goes on as before.","Zustand der NAS": "NAS status","Der Spark liest über SNMPv3 Belegung, RAID, Festplatten und Temperatur der NAS; Admins bekommen Hinweise und fragen per Sprache.": "The Spark reads use, RAID, disks and temperature of the NAS over SNMPv3; admins get notes and ask by voice.","Name oder IP der NAS": "Name or IP of the NAS","SNMPv3-Benutzer": "SNMPv3 user","ds.fritz.box oder 192.168.178.20": "ds.fritz.box or 192.168.178.20","Passwort für die Anmeldung (SHA)": "Sign-in password (SHA)","Passwort für die Verschlüsselung (AES)": "Privacy password (AES)","Auf der Synology: Systemsteuerung → Terminal & SNMP → SNMP, nur SNMPv3, SHA und AES. Nur lesen; der Spark stellt nie etwas ein.": "On the Synology: Control Panel → Terminal & SNMP → SNMP, only SNMPv3, SHA and AES. Reading only; the Spark never sets anything.","Jetzt lesen": "Read now","Vergessen": "Forget","Hinweis ab Belegung (%)": "Note from use (%)","50 bis 99, Standard 90.": "50 to 99, default 90.","Hinweis ab Temperatur (°C)": "Note from temperature (°C)","40 bis 90, Standard 60; für das System und jede Festplatte.": "40 to 90, default 60; for the system and each disk.","Werte aus SNMPv3, nur lesen; nie Adresse oder Passwort.": "Values from SNMPv3, reading only; never address or password.","100 bis 20000, Standard 5000; zählt getrennt von hochgeladenen Dokumenten. Liegt mehr im Ordner, kommen zuerst Dokumente, Tabellen und Text, dann Bilder, jeweils die neuesten.": "100 to 20000, default 5000; counted apart from uploaded documents. When a folder holds more, documents, tables and text come first, then pictures, the newest first each.","Nur die Funktionen, die der Admin für ein Profil gesperrt hat; antippen hebt die Sperre auf. Neue Sperren setzt du in der Funktion selbst unter „Wer darf es“.": "Only the functions the admin blocked for a profile; tap to lift the block. You set new blocks in the function itself under \"Who may use it\".","Admin: darf alles, nur das Panel-Passwort selbst, sein zweiter Schritt und „Überall abmelden“ bleiben beim Passwort (Notzugang). Verwalter: nur Zustand, Logs, Personen und Geräte, Sperren aufheben (Funktionen schaltet und sperrt nur der Admin). Eine Rolle gibt es nur mit dem zweiten Anmeldeschritt des Profils; die Rechte gelten in der Anmeldung mit Code, Face ID oder vertrautem Browser und in der eigenen iPhone-App, nie über Sprache, Lautsprecher, Uhr, Telegram oder Siri. „Bestätigen“ fragt Admins nicht, „Schutz ändern“ fragt jedes Mal. Haupt-Admin: sein Code gilt auch für das Panel-Passwort; ihn und sein Profil ändert nur er selbst oder das Passwort, und die letzte Admin-Rolle nimmt nur das Passwort. Neue Admin-Anmeldungen und Rollenwechsel melden sich per Push bei den Admins. Was ein Profil als Admin tut, steht unter Zustand → Logs → Admin-Protokoll.": "Admin: may do everything; only the panel password itself, its second step and “Sign out everywhere” stay with the password (emergency access). Manager: only status, logs, people and devices, lifting blocks (only the admin switches and blocks features). A role exists only with the profile's second login step; the rights count in the sign-in with a code, Face ID or a trusted browser and in the own iPhone app, never via voice, speaker, watch, Telegram or Siri. “Confirm” never asks admins, “Change protection” asks every time. Main admin: its code also counts for the panel password; it and its profile are changed only by itself or the password, and only the password takes away the last admin role. New admin sign-ins and role changes send a push note to the admins. What a profile does as admin is under Status → Logs → Admin log.","Haushaltsordner": "Household folder","Ein Admin-Profil wählt an seinem Ort Ordner „für alle“; jedes Profil findet die Dokumente darin, Gäste und fremde Stimmen nie.": "An admin profile picks folders at its place \"for everyone\"; every profile finds the documents in them, guests and unknown voices never.","Verbrauchszähler": "Usage counter","Zählt Tokens, Sekunden und Bilder je Modell, Aufgabe und Profil, nur Zahlen. Zu sehen unter Zustand → Verbrauch und Ich → Verbrauch.": "Counts tokens, seconds and pictures per model, task and profile, numbers only. Shown under Status → Usage and Me → Usage.","Tokens pro Tag und Profil (Tausend)": "Tokens per day and profile (thousands)","Verbrauch heute": "Usage today","Nur Zahlen je Modell, nie Fragen oder Antworten.": "Numbers per model only, never questions or answers.","Verbrauch": "Usage","Zähler leeren": "Empty counters","Wie viel jedes Modell arbeitet: Tokens beim Sprachmodell, Sekunden beim Hören und Sprechen, Texte bei der Bedeutungssuche, Bilder. Nur Zahlen, nie Inhalte.": "How much each model works: tokens at the language model, seconds of listening and speaking, texts of the meaning search, pictures. Numbers only, never contents.","Der Verbrauchszähler ist aus. Einschalten unter Funktionen → Verbrauchszähler.": "The usage counter is off. Switch it on under Features → Usage counter.","Bilder malen": "Painting pictures","Bilder, Zeichnungen oder Malvorlagen malen lassen; ohne Internet, als KI-Bild gekennzeichnet.": "Have pictures, drawings or colouring pages painted; without the internet, marked as made by an AI.","Das Bildmodell kommt mit der Installation: sudo ./install.sh --bild 4b-q8 (4b-q4 braucht weniger Speicher, 9b-… nur privat). Es lädt beim ersten Bild und gibt den Speicher danach wieder frei. Nacktes, Gewalt, Hasssymbole und Personen, die der Spark kennt, malt er nie (feste Regeln, Bildprüfung danach).": "The picture model comes with the installation: sudo ./install.sh --bild 4b-q8 (4b-q4 needs less memory, 9b-… private use only). It loads with the first picture and frees the memory again afterwards. It never paints nudity, violence, hate symbols or people the Spark knows (fixed rules, image check afterwards).","Bilder pro Profil und Tag": "Pictures per profile and day","1 bis 500, Standard 30.": "1 to 500, default 30.","Platz pro Profil (MB)": "Space per profile (MB)","50 bis 20000, Standard 500. Voll: erst alte Bilder löschen.": "50 to 20000, default 500. Full: delete old pictures first.","Längste Seite (Pixel)": "Longest side (pixels)","512 bis 1408 in 64er-Schritten, Standard 1024. Größer dauert länger und braucht mehr Speicher.": "512 to 1408 in steps of 64, default 1024. Larger takes longer and needs more memory.","Entladen nach Minuten ohne Bild": "Unload after minutes without a picture","1 bis 120, Standard 10.": "1 to 120, default 10.","Bild testen": "Test a picture","Kontingent": "Quota","Grenzen beim Sprachmodell je Profil für Tag, Woche und Monat, danach ein fester Satz. Admin-Profile ohne Grenze.": "Language model limits per profile for day, week and month, then a fixed sentence. Admin profiles without a limit.","Tokens pro Woche und Profil (Tausend)": "Tokens per week and profile (thousands)","Tokens pro Monat und Profil (Tausend)": "Tokens per month and profile (thousands)","Vorwarnung ab (Prozent)": "Warning from (percent)","0 heißt keine Grenze, bei der Vorwarnung keine Warnung. Die Woche beginnt am Montag, der Monat am 1. Eigene Werte und einen Nachschlag für einzelne Profile gibst du unter Zustand → Verbrauch.": "0 means no limit, for the warning no warning. The week starts on Monday, the month on the 1st. Own values and an extra for single profiles under Status → Usage.","Telefon": "Phone","1. Telefonanlage wählen": "1. Pick the telephone system","Im Heimnetz suchen": "Search the home network","2. Den Spark in der Anlage anlegen": "2. Add the Spark in the system","Vorschlag: Benutzername": "Suggestion: user name",", Kennwort": ", password","3. Zugang eintragen und prüfen": "3. Enter and check the access","Adresse der Anlage": "Address of the system","Benutzername": "User name","Kennwort": "Password","Speichern und prüfen": "Save and check","Verbindung prüfen": "Check connection","4. Testanruf und Mobilteile zuordnen": "4. Test call and assign handsets","Ruf vom Mobilteil die interne Nummer des Spark an (FRITZ!Box: meist **620). Die Nummer erscheint hier; ordne sie einem Profil zu oder als gemeinsames Telefon. Dort wählt die Stimme das Profil.": "Call the Spark's internal number from a handset (FRITZ!Box: usually **620). The number shows up here; assign it to a profile or as a shared phone. There the voice picks the profile.","Anrufe von außen": "Calls from outside","Spark ruft an": "Spark calls","Der Spark ruft die interne Nummer an und sagt einen Testsatz. So prüfst du, ob er auch hinaus telefonieren darf.": "The Spark calls the internal number and says a test sentence. This checks that it may also place calls.","Der Spark ruft an": "The Spark calls","Wen der Spark anruft": "Whom the Spark calls","nur zugeordnete Mobilteile": "only assigned handsets","auch bestätigte eigene Nummern (Rückruf)": "also confirmed own numbers (call back)","Anruf bei Dienstausfall": "Call on outages","Vom Telefon im Haus den Spark anrufen und mit ihm sprechen; er meldet sich an deiner Telefonanlage als IP-Telefon an.": "Call the Spark from a phone in the house and talk to it; it signs in at your telephone system as an IP phone.","Bestätigte Nummern der Profile kommen von unterwegs durch; Persönliches nur mit sicherer Stimme, PIN oder Rückruf.": "Confirmed numbers of the profiles get through from on the go; personal things only with a sure voice, PIN or call back.","Nicht zugeordnete Mobilteile und unbekannte Nummern bekommen Frage und Antwort als Gast, nie ein Werkzeug.": "Unassigned handsets and unknown numbers get questions and answers as a guest, never a tool.","Weckruf, Erinnerung per Anruf und Rückruf, nur ans eigene Mobilteil oder die bestätigte Nummer, höchstens 5 am Tag.": "Wake-up call, reminder by call and call back, only to the own handset or the confirmed number, at most 5 a day.","Ist ein Dienst 10 Minuten weg, ruft der Spark den Admin an, höchstens stündlich, nie zwischen 22 und 7 Uhr.": "If a service is gone 10 minutes, the Spark calls the admin, at most hourly, never between 10 pm and 7 am.","Unbekannte Anrufer als Gast": "Unknown callers as guests","Ton": "Sound","HD (G.722), sonst G.711": "HD (G.722), else G.711","nur G.711 (spart Rechenzeit)": "G.711 only (saves computing time)","Gespräche gleichzeitig": "Calls at once","Gesperrte Funktionen": "Blocked functions","Ein neues Profil bekommt gleich alles, was im Spark an ist; einzelne Funktionen sperrst du in der Funktion unter „Wer darf es“, alle Sperren stehen unter Personen und Geräte → Gesperrte Funktionen.": "A new profile gets everything that is switched on in the Spark at once; you block single functions in the function under \"Who may use it\", all blocks are listed under People and devices → Blocked functions.","Android: Spark als Assistent": "Android: Spark as assistant","Spark als Assistent des Handys: ein Blatt über jeder App mit eigener Stimme, dazu Widget, Kachel „Spark zuhören“ und Kurzmenü am Symbol.": "Spark as the phone's assistant: a sheet over any app with its own voice, plus a widget, the tile \"Spark listen\" and shortcuts on the icon.","Android: Fingerabdruck für Admins": "Android: fingerprint for admins","Ist in der App ein Admin angemeldet, fragt sie beim Öffnen und nach 5 Minuten Pause nach Fingerabdruck, Gesicht oder Displaysperre.": "When an admin is signed in to the app, it asks for the fingerprint, face or screen lock when opened and after a 5-minute break.","Welches Modell je Art gerade läuft und wie viel Speicher belegt ist. Mit Funktionen → Modelle wechseln zeigt „Wechseln“ die Auswahl: wechseln, ausprobieren oder bei Hugging Face suchen. Messwerte und Lange Gespräche stehen unter „Mehr“.": "Which model runs per kind and how much memory is taken. With Features → Routing models, \"Switch\" shows the choice: switch, try or search Hugging Face. Measurements and long conversations are under \"More\".","Mitteilung ans genutzte Gerät": "Notes to the device in use","Eine Mitteilung geht an das Gerät, das gerade benutzt wird, sonst an die Handy-App.": "A note goes to the device in use right now, else to the phone app."};
function translatePage(){document.documentElement.lang=L;$('langbtn').textContent=L==='en'?'Deutsch':'English';if(L!=='en')return;
  // whole sentences with tags inside (B1): data-tr, the key is the inner HTML with single spaces; first, before the words
  document.querySelectorAll('[data-tr]').forEach(e=>{const v=EN[e.innerHTML.replace(/\s+/g,' ').trim()];if(v)e.innerHTML=v});
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('pre,code,script,style,option:not([value])')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  for(let n;(n=w.nextNode());){const k=n.nodeValue.trim();if(EN[k]!==undefined)n.nodeValue=n.nodeValue.replace(k,EN[k])}
  document.querySelectorAll('[placeholder]').forEach(e=>{if(EN[e.placeholder])e.placeholder=EN[e.placeholder]});
  // tooltips and screen-reader names too (B1)
  for(const a of['title','aria-label'])document.querySelectorAll('['+a+']').forEach(e=>{const v=EN[e.getAttribute(a)];if(v)e.setAttribute(a,v)});
  const tx=$('ttstext');if(EN[tx.value])tx.value=EN[tx.value];}
$('langbtn').onclick=()=>{try{localStorage.setItem('lang',L==='en'?'de':'en')}catch{}location.reload()};
translatePage();
